INSERT INTO questions (question_text, option1, option2, option3, option4, correct_answer, solution_text, concept_id, difficulty_tier, source, status) VALUES

-- ============================================================
-- c_matter_dalton (7 easy, 7 medium, 7 hard = 21)
-- Matter, Dalton''s atomic theory, laws of chemical combination
-- ============================================================
('Which of the following is NOT a postulate of Dalton''s atomic theory?', 'Atoms of the same element are identical in mass and properties', 'Atoms can be created or destroyed in chemical reactions', 'Compounds are formed by combination of atoms in simple whole-number ratios', 'Atoms are indivisible particles', 'option2', 'Dalton stated atoms cannot be created or destroyed. Option 2 contradicts this — it is NOT a postulate.', 'c_matter_dalton', 1, 'JEE Mains Prep', 'approved'),
('The law of conservation of mass was proposed by', 'Dalton', 'Lavoisier', 'Proust', 'Gay-Lussac', 'option2', 'Lavoisier (1789) established that mass is neither created nor destroyed in a chemical reaction.', 'c_matter_dalton', 1, 'JEE Mains Prep', 'approved'),
('The law of definite proportions states that', 'Elements combine in any ratio', 'A compound always contains the same elements in the same proportion by mass', 'Mass is conserved in reactions', 'Gases combine in simple volume ratios', 'option2', 'Proust''s law: a given compound always has the same elemental composition by mass, regardless of source.', 'c_matter_dalton', 1, 'JEE Mains Prep', 'approved'),
('The law of multiple proportions was proposed by', 'Proust', 'Lavoisier', 'Dalton', 'Avogadro', 'option3', 'Dalton (1803): when two elements form more than one compound, the ratios of masses of one element that combine with a fixed mass of the other are small whole numbers.', 'c_matter_dalton', 1, 'JEE Mains Prep', 'approved'),
('Which of the following is a heterogeneous mixture?', 'Salt solution', 'Sugar solution', 'Milk', 'Air', 'option3', 'Milk is a colloid (heterogeneous). Salt solution, sugar solution, and air are homogeneous mixtures.', 'c_matter_dalton', 1, 'JEE Mains Prep', 'approved'),
('An element is a substance that', 'Contains two or more types of atoms', 'Cannot be broken down into simpler substances by chemical means', 'Is always a gas', 'Is always found in nature', 'option2', 'An element consists of only one type of atom and cannot be decomposed chemically.', 'c_matter_dalton', 1, 'JEE Mains Prep', 'approved'),
('Gay-Lussac''s law of gaseous volumes states that gases react in', 'Simple ratios by mass', 'Simple ratios by volume (at same T and P)', 'Equal volumes always', 'Ratios proportional to their molecular masses', 'option2', 'Gases combine in simple whole-number ratios by volume when measured at the same temperature and pressure.', 'c_matter_dalton', 1, 'JEE Mains Prep', 'approved'),
('Carbon forms two oxides: CO and CO$_2$. The masses of oxygen combining with $12\;\text{g}$ of carbon are $16\;\text{g}$ and $32\;\text{g}$ respectively. This illustrates the law of', 'Definite proportions', 'Conservation of mass', 'Multiple proportions', 'Reciprocal proportions', 'option3', 'Ratio of oxygen masses $= 16:32 = 1:2$ (simple whole number). This is the law of multiple proportions.', 'c_matter_dalton', 2, 'JEE Mains Prep', 'approved'),
('Avogadro''s hypothesis helped resolve the conflict between', 'Dalton''s theory and Gay-Lussac''s law', 'Proust''s law and Lavoisier''s law', 'Newton''s laws and thermodynamics', 'Bohr''s model and Rutherford''s model', 'option1', 'Dalton rejected Gay-Lussac''s law. Avogadro resolved this by distinguishing atoms from molecules and proposing equal volumes of gases contain equal numbers of molecules.', 'c_matter_dalton', 2, 'JEE Mains Prep', 'approved'),
('The law of reciprocal proportions was proposed by', 'Dalton', 'Richter', 'Proust', 'Lavoisier', 'option2', 'Richter (1792): the ratio of masses of two elements that separately combine with a fixed mass of a third element is either the same as or a simple multiple of the ratio in which they combine with each other.', 'c_matter_dalton', 2, 'JEE Mains Prep', 'approved'),
('Which limitation of Dalton''s atomic theory was revealed by the discovery of isotopes?', 'Atoms are indivisible', 'Atoms of the same element are identical in mass', 'Atoms combine in whole-number ratios', 'Atoms cannot be created or destroyed', 'option2', 'Isotopes (same element, different mass) disproved the claim that all atoms of an element have identical mass.', 'c_matter_dalton', 2, 'JEE Mains Prep', 'approved'),
('In the reaction $2\text{H}_2 + \text{O}_2 \to 2\text{H}_2\text{O}$, $4\;\text{g}$ of H$_2$ reacts with $32\;\text{g}$ of O$_2$. The mass of water formed is', '$36\;\text{g}$', '$28\;\text{g}$', '$18\;\text{g}$', '$72\;\text{g}$', 'option1', 'By conservation of mass: $4 + 32 = 36\;\text{g}$ of water.', 'c_matter_dalton', 2, 'JEE Mains Prep', 'approved'),
('A compound contains $40\%$ carbon, $6.7\%$ hydrogen, and $53.3\%$ oxygen by mass. This data illustrates the law of', 'Definite proportions', 'Multiple proportions', 'Conservation of mass', 'Gaseous volumes', 'option1', 'A compound always has the same percentage composition by mass — this is the law of definite proportions.', 'c_matter_dalton', 2, 'JEE Mains Prep', 'approved'),
('Which of the following is NOT a physical change?', 'Melting of ice', 'Dissolution of sugar in water', 'Rusting of iron', 'Evaporation of water', 'option3', 'Rusting involves a chemical reaction ($4\text{Fe} + 3\text{O}_2 + 6\text{H}_2\text{O} \to 4\text{Fe(OH)}_3$). The others are physical changes.', 'c_matter_dalton', 2, 'JEE Mains Prep', 'approved'),
('Nitrogen forms five oxides: N$_2$O, NO, N$_2$O$_3$, NO$_2$, N$_2$O$_5$. The masses of oxygen per $14\;\text{g}$ of nitrogen are $8, 16, 24, 32, 40\;\text{g}$. The ratio $8:16:24:32:40$ simplifies to', '$1:2:3:4:5$', '$2:4:6:8:10$', '$1:1:1:1:1$', '$5:4:3:2:1$', 'option1', 'Dividing by 8: $1:2:3:4:5$. Simple whole-number ratios confirm the law of multiple proportions.', 'c_matter_dalton', 3, 'JEE Mains Prep', 'approved'),
('The discovery of subatomic particles (electron, proton, neutron) disproved which aspect of Dalton''s theory?', 'Atoms combine in simple ratios', 'Atoms are indivisible', 'Mass is conserved', 'Compounds have definite composition', 'option2', 'Thomson''s discovery of the electron (1897) showed atoms are divisible, contradicting Dalton''s "indivisible atom" postulate.', 'c_matter_dalton', 3, 'JEE Mains Prep', 'approved'),
('$10\;\text{g}$ of CaCO$_3$ is heated and produces $5.6\;\text{g}$ of CaO and some CO$_2$. The mass of CO$_2$ produced is', '$10\;\text{g}$', '$5.6\;\text{g}$', '$4.4\;\text{g}$', '$15.6\;\text{g}$', 'option3', 'By conservation of mass: $m_{\text{CO}_2} = 10 - 5.6 = 4.4\;\text{g}$.', 'c_matter_dalton', 3, 'JEE Mains Prep', 'approved'),
('Two samples of water from different sources are analyzed. Sample A has $88.9\%$ oxygen and Sample B has $88.9\%$ oxygen. This confirms', 'The law of multiple proportions', 'The law of definite proportions', 'Avogadro''s law', 'The law of reciprocal proportions', 'option2', 'Regardless of source, water always has the same composition — this is the law of definite proportions.', 'c_matter_dalton', 3, 'JEE Mains Prep', 'approved'),
('Hydrogen and oxygen combine to form H$_2$O and H$_2$O$_2$. In H$_2$O, $2\;\text{g}$ H combines with $16\;\text{g}$ O. In H$_2$O$_2$, $2\;\text{g}$ H combines with $32\;\text{g}$ O. The ratio of oxygen masses is $16:32 = 1:2$. This is an example of', 'Law of conservation of mass', 'Law of multiple proportions', 'Law of definite proportions', 'Avogadro''s law', 'option2', 'When two elements form multiple compounds, the masses of one element combining with a fixed mass of the other are in simple whole-number ratios.', 'c_matter_dalton', 3, 'JEE Mains Prep', 'approved'),
('The equivalent mass of an element is $8$ and its atomic mass is $32$. The valency of the element is', '$2$', '$4$', '$8$', '$1$', 'option2', 'Valency $=$ Atomic mass / Equivalent mass $= 32/8 = 4$. The element is likely sulfur.', 'c_matter_dalton', 3, 'JEE Mains Prep', 'approved'),
('Which of the following pairs of compounds illustrates the law of reciprocal proportions?', 'H$_2$O, H$_2$O$_2$', 'NaCl, Na$_2$SO$_4$', 'H$_2$O, H$_2$S, SO$_2$', 'CO, CO$_2$', 'option3', 'H combines with O (in H$_2$O) and S (in H$_2$S). O and S combine in SO$_2$. The ratio of O:S in SO$_2$ is related to the ratios in H$_2$O and H$_2$S — this is reciprocal proportions.', 'c_matter_dalton', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_mole_concept (7 easy, 7 medium, 7 hard = 21)
-- Mole concept, molar mass, percentage composition, stoichiometry
-- ============================================================
('One mole of any substance contains', '$6.022 \times 10^{22}$ particles', '$6.022 \times 10^{23}$ particles', '$6.022 \times 10^{24}$ particles', '$6.022 \times 10^{20}$ particles', 'option2', 'Avogadro''s number $N_A = 6.022 \times 10^{23}\;\text{mol}^{-1}$.', 'c_mole_concept', 1, 'JEE Mains Prep', 'approved'),
('The molar mass of water (H$_2$O) is', '$16\;\text{g/mol}$', '$18\;\text{g/mol}$', '$20\;\text{g/mol}$', '$36\;\text{g/mol}$', 'option2', '$M = 2(1) + 16 = 18\;\text{g/mol}$.', 'c_mole_concept', 1, 'JEE Mains Prep', 'approved'),
('The number of moles in $44\;\text{g}$ of CO$_2$ is', '$0.5$', '$1$', '$2$', '$44$', 'option2', '$n = m/M = 44/44 = 1\;\text{mol}$.', 'c_mole_concept', 1, 'JEE Mains Prep', 'approved'),
('At STP, one mole of an ideal gas occupies', '$11.2\;\text{L}$', '$22.4\;\text{L}$', '$44.8\;\text{L}$', '$2.24\;\text{L}$', 'option2', 'Molar volume at STP ($0°\text{C}$, $1\;\text{atm}$) $= 22.4\;\text{L/mol}$.', 'c_mole_concept', 1, 'JEE Mains Prep', 'approved'),
('The empirical formula of a compound with $40\%$ C, $6.7\%$ H, and $53.3\%$ O is', 'CHO', 'CH$_2$O', 'C$_2$H$_4$O$_2$', 'CH$_3$O', 'option2', 'C: $40/12 = 3.33$, H: $6.7/1 = 6.7$, O: $53.3/16 = 3.33$. Ratio $= 1:2:1$. Empirical formula $= \text{CH}_2\text{O}$.', 'c_mole_concept', 1, 'JEE Mains Prep', 'approved'),
('The percentage of nitrogen in urea (NH$_2$CONH$_2$, $M = 60$) is', '$23.3\%$', '$46.7\%$', '$14\%$', '$28\%$', 'option2', '$\% \text{N} = 2 \times 14/60 \times 100 = 46.7\%$.', 'c_mole_concept', 1, 'JEE Mains Prep', 'approved'),
('The molecular formula is always a _____ multiple of the empirical formula.', 'Fractional', 'Whole number', 'Negative', 'Irrational', 'option2', 'Molecular formula $= n \times$ empirical formula, where $n$ is a positive integer.', 'c_mole_concept', 1, 'JEE Mains Prep', 'approved'),
('How many molecules are present in $9\;\text{g}$ of water?', '$12.044 \times 10^{23}$', '$6.022 \times 10^{23}$', '$1.505 \times 10^{23}$', '$3.011 \times 10^{23}$', 'option4', '$n = 9/18 = 0.5\;\text{mol}$. Molecules $= 0.5 \times 6.022 \times 10^{23} = 3.011 \times 10^{23}$.', 'c_mole_concept', 2, 'JEE Mains Prep', 'approved'),
('The number of atoms in $0.1\;\text{mol}$ of H$_2$SO$_4$ is', '$6.022 \times 10^{23}$', '$6.022 \times 10^{22}$', '$2.107 \times 10^{23}$', '$4.215 \times 10^{23}$', 'option4', 'Each molecule has $2 + 1 + 4 = 7$ atoms. Total atoms $= 0.1 \times 6.022 \times 10^{23} \times 7 = 4.215 \times 10^{23}$.', 'c_mole_concept', 2, 'JEE Mains Prep', 'approved'),
('$5.6\;\text{L}$ of a gas at STP has mass $11\;\text{g}$. The molar mass of the gas is', '$22\;\text{g/mol}$', '$44\;\text{g/mol}$', '$28\;\text{g/mol}$', '$32\;\text{g/mol}$', 'option2', '$n = 5.6/22.4 = 0.25\;\text{mol}$. $M = 11/0.25 = 44\;\text{g/mol}$ (likely CO$_2$).', 'c_mole_concept', 2, 'JEE Mains Prep', 'approved'),
('In the reaction $\text{N}_2 + 3\text{H}_2 \to 2\text{NH}_3$, $28\;\text{g}$ of N$_2$ reacts with excess H$_2$. The mass of NH$_3$ produced is', '$17\;\text{g}$', '$34\;\text{g}$', '$51\;\text{g}$', '$68\;\text{g}$', 'option2', '$28\;\text{g}$ N$_2$ $= 1\;\text{mol}$. Produces $2\;\text{mol}$ NH$_3$ $= 2 \times 17 = 34\;\text{g}$.', 'c_mole_concept', 2, 'JEE Mains Prep', 'approved'),
('A compound has empirical formula CH$_2$O and molar mass $180\;\text{g/mol}$. Its molecular formula is', 'C$_3$H$_6$O$_3$', 'C$_6$H$_{12}$O$_6$', 'C$_2$H$_4$O$_2$', 'C$_4$H$_8$O$_4$', 'option2', 'Empirical formula mass $= 12 + 2 + 16 = 30$. $n = 180/30 = 6$. Molecular formula $= \text{C}_6\text{H}_{12}\text{O}_6$ (glucose).', 'c_mole_concept', 2, 'JEE Mains Prep', 'approved'),
('The molarity of a solution containing $4\;\text{g}$ of NaOH ($M = 40$) in $500\;\text{mL}$ is', '$0.1\;\text{M}$', '$0.2\;\text{M}$', '$0.4\;\text{M}$', '$0.05\;\text{M}$', 'option2', '$n = 4/40 = 0.1\;\text{mol}$. $M = 0.1/0.5 = 0.2\;\text{M}$.', 'c_mole_concept', 2, 'JEE Mains Prep', 'approved'),
('The limiting reagent in a reaction is the reactant that', 'Is present in excess', 'Is completely consumed first and limits the product formed', 'Has the highest molar mass', 'Is added last', 'option2', 'The limiting reagent determines the maximum amount of product. It is fully consumed while other reactants may remain.', 'c_mole_concept', 2, 'JEE Mains Prep', 'approved'),
('$10\;\text{g}$ of CaCO$_3$ ($M = 100$) is treated with excess HCl. The volume of CO$_2$ at STP is', '$1.12\;\text{L}$', '$2.24\;\text{L}$', '$11.2\;\text{L}$', '$22.4\;\text{L}$', 'option2', 'CaCO$_3$ + 2HCl $\to$ CaCl$_2$ + H$_2$O + CO$_2$. $n = 10/100 = 0.1\;\text{mol}$ CaCO$_3$ gives $0.1\;\text{mol}$ CO$_2$. $V = 0.1 \times 22.4 = 2.24\;\text{L}$.', 'c_mole_concept', 3, 'JEE Mains Prep', 'approved'),
('$2.76\;\text{g}$ of Ag$_2$CO$_3$ ($M = 276$) is heated. The residue (Ag) weighs', '$0.54\;\text{g}$', '$1.08\;\text{g}$', '$3.24\;\text{g}$', '$2.16\;\text{g}$', 'option4', 'Ag$_2$CO$_3 \to 2\text{Ag} + \text{CO}_2 + \frac{1}{2}\text{O}_2$. $n = 2.76/276 = 0.01\;\text{mol}$. Ag $= 0.02\;\text{mol} = 0.02 \times 108 = 2.16\;\text{g}$.', 'c_mole_concept', 3, 'JEE Mains Prep', 'approved'),
('A mixture of $2\;\text{g}$ H$_2$ and $16\;\text{g}$ O$_2$ is ignited. The mass of water formed and the gas remaining are', '$18\;\text{g}$ H$_2$O, no gas remaining', '$18\;\text{g}$ H$_2$O, $0\;\text{g}$ remaining', '$36\;\text{g}$ H$_2$O, no gas remaining', '$18\;\text{g}$ H$_2$O, excess H$_2$ remaining', 'option1', '$2\text{H}_2 + \text{O}_2 \to 2\text{H}_2\text{O}$. H$_2$: $2/2 = 1\;\text{mol}$. O$_2$: $16/32 = 0.5\;\text{mol}$. Stoichiometry: $1\;\text{mol}$ H$_2$ needs $0.5\;\text{mol}$ O$_2$. Both fully consumed. H$_2$O $= 1\;\text{mol} = 18\;\text{g}$.', 'c_mole_concept', 3, 'JEE Mains Prep', 'approved'),
('The density of a gas at STP is $1.96\;\text{g/L}$. Its molar mass is', '$22\;\text{g/mol}$', '$44\;\text{g/mol}$', '$28\;\text{g/mol}$', '$32\;\text{g/mol}$', 'option2', '$M = \rho \times V_m = 1.96 \times 22.4 = 43.9 \approx 44\;\text{g/mol}$ (CO$_2$).', 'c_mole_concept', 3, 'JEE Mains Prep', 'approved'),
('$1.6\;\text{g}$ of an iron oxide contains $1.12\;\text{g}$ of iron ($M = 56$). The formula of the oxide is', 'FeO', 'Fe$_2$O$_3$', 'Fe$_3$O$_4$', 'FeO$_2$', 'option2', 'Fe: $1.12/56 = 0.02\;\text{mol}$. O: $(1.6 - 1.12)/16 = 0.48/16 = 0.03\;\text{mol}$. Ratio $= 0.02:0.03 = 2:3$. Formula $= \text{Fe}_2\text{O}_3$.', 'c_mole_concept', 3, 'JEE Mains Prep', 'approved'),
('A sample of an organic compound contains $3.0\;\text{g}$ C, $0.5\;\text{g}$ H, and $4.0\;\text{g}$ O. The empirical formula is', 'CHO', 'CH$_2$O', 'C$_2$H$_4$O$_2$', 'CHO$_2$', 'option2', 'C: $3.0/12 = 0.25$, H: $0.5/1 = 0.5$, O: $4.0/16 = 0.25$. Ratio $= 1:2:1$. Empirical formula $= \text{CH}_2\text{O}$.', 'c_mole_concept', 3, 'JEE Mains Prep', 'approved'),
('$8\;\text{g}$ of methane (CH$_4$, $M = 16$) is burned completely. The volume of CO$_2$ produced at STP is', '$5.6\;\text{L}$', '$22.4\;\text{L}$', '$11.2\;\text{L}$', '$44.8\;\text{L}$', 'option3', 'CH$_4$ + 2O$_2 \to$ CO$_2$ + 2H$_2$O. $n_{\text{CH}_4} = 8/16 = 0.5\;\text{mol}$. $n_{\text{CO}_2} = 0.5\;\text{mol}$. $V = 0.5 \times 22.4 = 11.2\;\text{L}$.', 'c_mole_concept', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_em_radiation_photoelectric (7 easy, 7 medium, 7 hard = 21)
-- Nature of EM radiation, photoelectric effect, hydrogen spectrum
-- ============================================================
('Electromagnetic radiation has', 'Only wave nature', 'Only particle nature', 'Dual nature (both wave and particle)', 'Neither wave nor particle nature', 'option3', 'EM radiation exhibits wave-particle duality: wave nature (interference, diffraction) and particle nature (photoelectric effect).', 'c_em_radiation_photoelectric', 1, 'JEE Mains Prep', 'approved'),
('The speed of all electromagnetic radiation in vacuum is', '$3 \times 10^6\;\text{m/s}$', '$3 \times 10^{10}\;\text{m/s}$', '$3 \times 10^8\;\text{m/s}$', '$3 \times 10^{12}\;\text{m/s}$', 'option3', '$c = 3 \times 10^8\;\text{m/s}$ for all EM radiation in vacuum.', 'c_em_radiation_photoelectric', 1, 'JEE Mains Prep', 'approved'),
('The energy of a photon is given by', '$E = mc^2$', '$E = h\nu$', '$E = hc$', '$E = h/\nu$', 'option2', '$E = h\nu = hc/\lambda$ where $h = 6.626 \times 10^{-34}\;\text{J}\cdot\text{s}$.', 'c_em_radiation_photoelectric', 1, 'JEE Mains Prep', 'approved'),
('The photoelectric effect demonstrates the _____ nature of light.', 'Wave', 'Particle', 'Dual', 'Mechanical', 'option2', 'The photoelectric effect can only be explained by treating light as particles (photons) with energy $h\nu$.', 'c_em_radiation_photoelectric', 1, 'JEE Mains Prep', 'approved'),
('The hydrogen emission spectrum consists of', 'A continuous band of colours', 'Discrete lines at specific wavelengths', 'A single line', 'No visible lines', 'option2', 'Hydrogen emits light at specific wavelengths corresponding to electron transitions between energy levels (line spectrum).', 'c_em_radiation_photoelectric', 1, 'JEE Mains Prep', 'approved'),
('The relationship between wavelength $\lambda$, frequency $\nu$, and speed $c$ of EM radiation is', '$c = \lambda/\nu$', '$c = \lambda\nu$', '$c = \lambda + \nu$', '$\lambda = c\nu$', 'option2', '$c = \lambda\nu$. Higher frequency means shorter wavelength.', 'c_em_radiation_photoelectric', 1, 'JEE Mains Prep', 'approved'),
('The wavenumber $\bar{\nu}$ is defined as', '$\lambda$', '$1/\lambda$', '$c/\lambda$', '$\lambda/c$', 'option2', 'Wavenumber $\bar{\nu} = 1/\lambda$ (in cm$^{-1}$ or m$^{-1}$). It is proportional to energy.', 'c_em_radiation_photoelectric', 1, 'JEE Mains Prep', 'approved'),
('The wavelength of radiation with frequency $6 \times 10^{14}\;\text{Hz}$ is', '$500\;\text{nm}$', '$600\;\text{nm}$', '$400\;\text{nm}$', '$700\;\text{nm}$', 'option1', '$\lambda = c/\nu = 3 \times 10^8/(6 \times 10^{14}) = 5 \times 10^{-7}\;\text{m} = 500\;\text{nm}$.', 'c_em_radiation_photoelectric', 2, 'JEE Mains Prep', 'approved'),
('The Balmer series of hydrogen lies in the', 'Ultraviolet region', 'Visible region', 'Infrared region', 'Microwave region', 'option2', 'Balmer series: transitions to $n = 2$. Wavelengths range from $365$-$656\;\text{nm}$ (visible and near-UV).', 'c_em_radiation_photoelectric', 2, 'JEE Mains Prep', 'approved'),
('The Lyman series of hydrogen lies in the', 'Visible region', 'Infrared region', 'Ultraviolet region', 'X-ray region', 'option3', 'Lyman series: transitions to $n = 1$. All wavelengths are in the UV region ($< 122\;\text{nm}$).', 'c_em_radiation_photoelectric', 2, 'JEE Mains Prep', 'approved'),
('The energy of a photon of wavelength $248\;\text{nm}$ is approximately ($h = 6.626 \times 10^{-34}\;\text{J}\cdot\text{s}$)', '$8 \times 10^{-17}\;\text{J}$', '$5 \times 10^{-19}\;\text{J}$', '$8 \times 10^{-19}\;\text{J}$', '$5 \times 10^{-17}\;\text{J}$', 'option3', '$E = hc/\lambda = 6.626 \times 10^{-34} \times 3 \times 10^8/(248 \times 10^{-9}) = 8.02 \times 10^{-19}\;\text{J}$.', 'c_em_radiation_photoelectric', 2, 'JEE Mains Prep', 'approved'),
('The Rydberg formula for hydrogen spectral lines is', '$1/\lambda = R_H(1/n_1 - 1/n_2)$', '$1/\lambda = R_H(1/n_1^2 - 1/n_2^2)$', '$\lambda = R_H(n_2^2 - n_1^2)$', '$1/\lambda = R_H(1/n_1^2 + 1/n_2^2)$', 'option2', '$1/\lambda = R_H(1/n_1^2 - 1/n_2^2)$ where $n_2 > n_1$ and $R_H = 1.097 \times 10^7\;\text{m}^{-1}$.', 'c_em_radiation_photoelectric', 2, 'JEE Mains Prep', 'approved'),
('Black body radiation and Planck''s quantum theory showed that energy is', 'Emitted continuously', 'Emitted in discrete packets called quanta', 'Not related to frequency', 'Infinite at all frequencies', 'option2', 'Planck (1900): energy is quantized, $E = nh\nu$. This resolved the ultraviolet catastrophe of classical physics.', 'c_em_radiation_photoelectric', 2, 'JEE Mains Prep', 'approved'),
('The work function of a metal is $4.0\;\text{eV}$. The threshold wavelength for photoelectric emission is', '$620\;\text{nm}$', '$248\;\text{nm}$', '$310\;\text{nm}$', '$124\;\text{nm}$', 'option3', '$\lambda_0 = hc/\phi = 1240/4.0 = 310\;\text{nm}$ (using $hc = 1240\;\text{eV}\cdot\text{nm}$).', 'c_em_radiation_photoelectric', 2, 'JEE Mains Prep', 'approved'),
('The first line of the Lyman series has wavelength $121.6\;\text{nm}$. The ionization energy of hydrogen from the ground state is', '$3.4\;\text{eV}$', '$10.2\;\text{eV}$', '$13.6\;\text{eV}$', '$1.51\;\text{eV}$', 'option3', 'First Lyman line: $n = 2 \to 1$, energy $= 10.2\;\text{eV}$. Ionization $= n = \infty \to 1 = 13.6\;\text{eV}$. The series limit gives ionization energy directly.', 'c_em_radiation_photoelectric', 3, 'JEE Mains Prep', 'approved'),
('The ratio of energies of photons of wavelengths $4000\;\text{\AA}$ and $8000\;\text{\AA}$ is', '$1:2$', '$2:1$', '$4:1$', '$1:4$', 'option2', '$E \propto 1/\lambda$. Ratio $= 8000/4000 = 2:1$.', 'c_em_radiation_photoelectric', 3, 'JEE Mains Prep', 'approved'),
('The number of photons emitted per second by a $60\;\text{W}$ source of wavelength $600\;\text{nm}$ is approximately', '$6 \times 10^{20}$', '$3.6 \times 10^{20}$', '$1.8 \times 10^{20}$', '$1.2 \times 10^{20}$', 'option3', '$n = P\lambda/(hc) = 60 \times 600 \times 10^{-9}/(6.626 \times 10^{-34} \times 3 \times 10^8) = 3.6 \times 10^{-5}/(1.988 \times 10^{-25}) = 1.81 \times 10^{20}$.', 'c_em_radiation_photoelectric', 3, 'JEE Mains Prep', 'approved'),
('The Paschen series of hydrogen corresponds to transitions ending at $n = 3$. The longest wavelength in this series is', '$1282\;\text{nm}$', '$1875\;\text{nm}$', '$820\;\text{nm}$', '$656\;\text{nm}$', 'option2', 'Longest wavelength: $n = 4 \to 3$. $1/\lambda = R_H(1/9 - 1/16) = R_H(7/144)$. $\lambda = 144/(7 \times 1.097 \times 10^7) = 1875\;\text{nm}$ (IR).', 'c_em_radiation_photoelectric', 3, 'JEE Mains Prep', 'approved'),
('The maximum number of spectral lines emitted when hydrogen atoms are excited to $n = 4$ is', '$3$', '$4$', '$6$', '$10$', 'option3', 'Number of lines $= n(n-1)/2 = 4 \times 3/2 = 6$. Transitions: $4 \to 3$, $4 \to 2$, $4 \to 1$, $3 \to 2$, $3 \to 1$, $2 \to 1$.', 'c_em_radiation_photoelectric', 3, 'JEE Mains Prep', 'approved'),
('The convergence limit (series limit) of the Balmer series corresponds to a wavelength of', '$364.6\;\text{nm}$', '$121.6\;\text{nm}$', '$91.2\;\text{nm}$', '$820\;\text{nm}$', 'option1', 'Series limit: $n = \infty \to 2$. $1/\lambda = R_H(1/4) = 1.097 \times 10^7/4$. $\lambda = 4/(1.097 \times 10^7) = 364.6\;\text{nm}$.', 'c_em_radiation_photoelectric', 3, 'JEE Mains Prep', 'approved'),
('The photoelectric effect equation $KE_{max} = h\nu - \phi$ was given by', 'Planck', 'Bohr', 'Einstein', 'Hertz', 'option3', 'Einstein (1905) explained the photoelectric effect using the photon concept, earning the Nobel Prize.', 'c_em_radiation_photoelectric', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_bohr_model (7 easy, 7 medium, 7 hard = 21)
-- Bohr model, postulates, energy/radii relations, limitations
-- ============================================================
('Bohr''s model of the atom applies to', 'All atoms', 'Only hydrogen and hydrogen-like (one-electron) species', 'Only multi-electron atoms', 'Only noble gases', 'option2', 'Bohr''s model works only for one-electron systems: H, He$^+$, Li$^{2+}$, etc.', 'c_bohr_model', 1, 'JEE Mains Prep', 'approved'),
('According to Bohr, electrons revolve in', 'Any orbit around the nucleus', 'Fixed circular orbits of definite energy (stationary states)', 'Elliptical orbits', 'Random paths', 'option2', 'Bohr postulated that electrons occupy specific circular orbits with quantized angular momentum.', 'c_bohr_model', 1, 'JEE Mains Prep', 'approved'),
('The energy of an electron in the $n$th orbit of hydrogen is', '$-13.6/n\;\text{eV}$', '$+13.6/n^2\;\text{eV}$', '$-13.6/n^2\;\text{eV}$', '$-13.6n^2\;\text{eV}$', 'option3', '$E_n = -13.6Z^2/n^2\;\text{eV}$. For hydrogen ($Z = 1$): $E_n = -13.6/n^2\;\text{eV}$.', 'c_bohr_model', 1, 'JEE Mains Prep', 'approved'),
('The radius of the first Bohr orbit of hydrogen is', '$0.0529\;\text{\AA}$', '$5.29\;\text{\AA}$', '$0.529\;\text{\AA}$', '$52.9\;\text{\AA}$', 'option3', '$r_1 = a_0 = 0.529\;\text{\AA} = 52.9\;\text{pm}$.', 'c_bohr_model', 1, 'JEE Mains Prep', 'approved'),
('The angular momentum of an electron in the $n$th Bohr orbit is quantized as', '$mvr = n^2 h$', '$mvr = nh$', '$mvr = nh/(2\pi)$', '$mvr = h/(2\pi n)$', 'option3', 'Bohr''s quantization condition: $L = mvr = n\hbar = nh/(2\pi)$.', 'c_bohr_model', 1, 'JEE Mains Prep', 'approved'),
('When an electron transitions from a higher to a lower energy level, it', 'Absorbs a photon', 'Emits a photon of energy $\Delta E = h\nu$', 'Loses mass', 'Gains angular momentum', 'option2', 'Transition to lower level releases energy as a photon: $h\nu = E_{higher} - E_{lower}$.', 'c_bohr_model', 1, 'JEE Mains Prep', 'approved'),
('The ground state of hydrogen corresponds to', '$n = 0$', '$n = 1$', '$n = 2$', '$n = \infty$', 'option2', 'The lowest energy state is $n = 1$ with $E_1 = -13.6\;\text{eV}$.', 'c_bohr_model', 1, 'JEE Mains Prep', 'approved'),
('The radius of the $n$th Bohr orbit for a hydrogen-like ion of atomic number $Z$ is', '$0.529 n^2/Z\;\text{\AA}$', '$0.529 Z/n^2\;\text{\AA}$', '$0.529 n/Z\;\text{\AA}$', '$0.529 Z^2/n^2\;\text{\AA}$', 'option1', '$r_n = a_0 n^2/Z = 0.529 n^2/Z\;\text{\AA}$.', 'c_bohr_model', 2, 'JEE Mains Prep', 'approved'),
('The energy required to excite hydrogen from $n = 1$ to $n = 3$ is', '$1.89\;\text{eV}$', '$10.2\;\text{eV}$', '$12.09\;\text{eV}$', '$13.6\;\text{eV}$', 'option3', '$\Delta E = -13.6/9 - (-13.6/1) = -1.51 + 13.6 = 12.09\;\text{eV}$.', 'c_bohr_model', 2, 'JEE Mains Prep', 'approved'),
('The velocity of an electron in the $n$th Bohr orbit is proportional to', '$n$', '$1/n$', '$n^2$', '$1/n^2$', 'option2', '$v_n = 2.18 \times 10^6 Z/n\;\text{m/s}$. $v \propto Z/n$.', 'c_bohr_model', 2, 'JEE Mains Prep', 'approved'),
('The ionization energy of He$^+$ (hydrogen-like, $Z = 2$) from the ground state is', '$13.6\;\text{eV}$', '$54.4\;\text{eV}$', '$27.2\;\text{eV}$', '$3.4\;\text{eV}$', 'option2', '$IE = 13.6 Z^2/n^2 = 13.6 \times 4/1 = 54.4\;\text{eV}$.', 'c_bohr_model', 2, 'JEE Mains Prep', 'approved'),
('The ratio of radii of the 2nd and 3rd Bohr orbits of hydrogen is', '$3:2$', '$9:4$', '$2:3$', '$4:9$', 'option4', '$r_n \propto n^2$. $r_2/r_3 = 4/9$.', 'c_bohr_model', 2, 'JEE Mains Prep', 'approved'),
('The frequency of revolution of an electron in the $n$th Bohr orbit is proportional to', '$n^2$', '$n^3$', '$1/n^2$', '$1/n^3$', 'option4', '$f = v/(2\pi r) \propto (1/n)/(n^2) = 1/n^3$.', 'c_bohr_model', 2, 'JEE Mains Prep', 'approved'),
('The wavelength of radiation emitted when hydrogen transitions from $n = 3$ to $n = 2$ is approximately', '$434\;\text{nm}$', '$486\;\text{nm}$', '$656\;\text{nm}$', '$121\;\text{nm}$', 'option3', '$1/\lambda = R_H(1/4 - 1/9) = R_H \times 5/36$. $\lambda = 36/(5 \times 1.097 \times 10^7) = 656\;\text{nm}$ (H$_\alpha$ line, red).', 'c_bohr_model', 2, 'JEE Mains Prep', 'approved'),
('A major limitation of Bohr''s model is that it', 'Cannot explain the spectra of multi-electron atoms', 'Cannot predict the hydrogen spectrum', 'Violates conservation of energy', 'Predicts wrong ionization energy for hydrogen', 'option1', 'Bohr''s model fails for atoms with more than one electron. It also cannot explain fine structure, Zeeman effect, or Stark effect.', 'c_bohr_model', 3, 'JEE Mains Prep', 'approved'),
('The ratio of the energies of the first excited state of H and He$^+$ is', '$1:4$', '$4:1$', '$1:1$', '$1:2$', 'option1', 'First excited state: $n = 2$. $E_H = -13.6/4 = -3.4\;\text{eV}$. $E_{He^+} = -13.6 \times 4/4 = -13.6\;\text{eV}$. Ratio $= 3.4:13.6 = 1:4$.', 'c_bohr_model', 3, 'JEE Mains Prep', 'approved'),
('The total energy of an electron in the $n$th Bohr orbit is', 'Negative (bound state)', 'Positive', 'Zero', 'Can be positive or negative', 'option1', 'Total energy $= KE + PE = -13.6Z^2/n^2 < 0$. Negative energy indicates a bound state.', 'c_bohr_model', 3, 'JEE Mains Prep', 'approved'),
('In the Bohr model, the kinetic energy of the electron in the $n$th orbit is', '$2E_n$', '$E_n$', '$-E_n$ (equal in magnitude to total energy but positive)', '$E_n/2$', 'option3', '$KE = -E_n = 13.6Z^2/n^2\;\text{eV}$ (positive). $PE = 2E_n$ (negative). $TE = KE + PE = E_n$.', 'c_bohr_model', 3, 'JEE Mains Prep', 'approved'),
('The orbit of Li$^{2+}$ ($Z = 3$) that has the same energy as the ground state of hydrogen is', '$n = 1$', '$n = 2$', '$n = 3$', '$n = 4$', 'option3', '$E_n = -13.6Z^2/n^2$. For H ground state: $E = -13.6\;\text{eV}$. For Li$^{2+}$: $-13.6 \times 9/n^2 = -13.6$. $n^2 = 9$. $n = 3$.', 'c_bohr_model', 3, 'JEE Mains Prep', 'approved'),
('The de Broglie wavelength of an electron in the $n$th Bohr orbit is related to the orbit circumference by', '$\pi r_n = n\lambda$', '$2\pi r_n = \lambda$', '$2\pi r_n = n\lambda$', '$r_n = n\lambda$', 'option3', 'Bohr''s quantization $mvr = n\hbar$ combined with $\lambda = h/(mv)$ gives $2\pi r = n\lambda$ (standing wave condition).', 'c_bohr_model', 3, 'JEE Mains Prep', 'approved'),
('The Bohr model could not explain', 'The ionization energy of hydrogen', 'The hydrogen spectrum', 'The splitting of spectral lines in a magnetic field (Zeeman effect)', 'The concept of stationary states', 'option3', 'The Zeeman effect (splitting in magnetic field), Stark effect (splitting in electric field), and fine structure require quantum mechanics.', 'c_bohr_model', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_dual_nature_uncertainty (7 easy, 7 medium, 7 hard = 21)
-- Dual nature of matter, de Broglie, Heisenberg uncertainty
-- ============================================================
('The de Broglie wavelength of a particle is given by', '$\lambda = p/h$', '$\lambda = hp$', '$\lambda = h/p$', '$\lambda = h^2/p$', 'option3', '$\lambda = h/p = h/(mv)$ where $p$ is the momentum.', 'c_dual_nature_uncertainty', 1, 'JEE Mains Prep', 'approved'),
('The wave nature of matter was proposed by', 'Bohr', 'de Broglie', 'Heisenberg', 'Schrödinger', 'option2', 'Louis de Broglie (1924) proposed that all matter has an associated wavelength $\lambda = h/p$.', 'c_dual_nature_uncertainty', 1, 'JEE Mains Prep', 'approved'),
('The Heisenberg uncertainty principle states that', 'Position and momentum can both be measured exactly', 'It is impossible to simultaneously determine the exact position and momentum of a particle', 'Energy is always conserved', 'Electrons move in fixed orbits', 'option2', '$\Delta x \cdot \Delta p \geq h/(4\pi)$. The more precisely one is known, the less precisely the other can be known.', 'c_dual_nature_uncertainty', 1, 'JEE Mains Prep', 'approved'),
('The de Broglie wavelength is significant for', 'Macroscopic objects like cars', 'Microscopic particles like electrons', 'All objects equally', 'Only photons', 'option2', 'For macroscopic objects, $\lambda$ is negligibly small. Only for subatomic particles is $\lambda$ comparable to atomic dimensions.', 'c_dual_nature_uncertainty', 1, 'JEE Mains Prep', 'approved'),
('The uncertainty principle is a consequence of', 'The dual (wave-particle) nature of matter', 'Experimental limitations only', 'Classical mechanics', 'Dalton''s atomic theory', 'option1', 'The uncertainty principle is fundamental to quantum mechanics and arises from the wave nature of particles.', 'c_dual_nature_uncertainty', 1, 'JEE Mains Prep', 'approved'),
('The de Broglie wavelength of an electron accelerated through $V$ volts is', '$12.27/\sqrt{V}\;\text{\AA}$', '$\sqrt{V}/12.27\;\text{\AA}$', '$12.27V\;\text{\AA}$', '$12.27/V\;\text{\AA}$', 'option1', '$\lambda = h/\sqrt{2meV} = 12.27/\sqrt{V}\;\text{\AA}$ (for electrons).', 'c_dual_nature_uncertainty', 1, 'JEE Mains Prep', 'approved'),
('The uncertainty principle makes the concept of _____ in Bohr''s model invalid.', 'Energy levels', 'Well-defined circular orbits', 'Quantized angular momentum', 'Photon emission', 'option2', 'If we cannot know both position and momentum precisely, the concept of a definite orbit (trajectory) is meaningless.', 'c_dual_nature_uncertainty', 1, 'JEE Mains Prep', 'approved'),
('The de Broglie wavelength of an electron with kinetic energy $E$ is', '$h/(2mE)$', '$\sqrt{2mE}/h$', '$h\sqrt{2mE}$', '$h/\sqrt{2mE}$', 'option4', '$p = \sqrt{2mE}$. $\lambda = h/p = h/\sqrt{2mE}$.', 'c_dual_nature_uncertainty', 2, 'JEE Mains Prep', 'approved'),
('An electron has de Broglie wavelength $1\;\text{\AA}$. Its kinetic energy is approximately', '$1500\;\text{eV}$', '$15\;\text{eV}$', '$1.5\;\text{eV}$', '$150\;\text{eV}$', 'option4', '$\lambda = 12.27/\sqrt{V}$. $1 = 12.27/\sqrt{V}$. $\sqrt{V} = 12.27$. $V = 150.6\;\text{V}$. $KE = 150\;\text{eV}$.', 'c_dual_nature_uncertainty', 2, 'JEE Mains Prep', 'approved'),
('If the kinetic energy of a particle is doubled, its de Broglie wavelength becomes', '$\lambda/2$', '$\lambda\sqrt{2}$', '$\lambda/\sqrt{2}$', '$2\lambda$', 'option3', '$\lambda = h/\sqrt{2mKE}$. If $KE \to 2KE$: $\lambda'' = \lambda/\sqrt{2}$.', 'c_dual_nature_uncertainty', 2, 'JEE Mains Prep', 'approved'),
('A proton and an electron have the same de Broglie wavelength. Which has greater kinetic energy?', 'The proton', 'The electron', 'Both have the same', 'Cannot be determined', 'option2', 'Same $\lambda$ means same $p$. $KE = p^2/(2m)$. Since $m_e \ll m_p$: $KE_e \gg KE_p$.', 'c_dual_nature_uncertainty', 2, 'JEE Mains Prep', 'approved'),
('The uncertainty in the position of an electron ($m = 9.1 \times 10^{-31}\;\text{kg}$) with velocity uncertainty $\Delta v = 10^3\;\text{m/s}$ is at least', '$\approx 5.8 \times 10^{-2}\;\text{m}$', '$\approx 5.8 \times 10^{-5}\;\text{m}$', '$\approx 5.8 \times 10^{-11}\;\text{m}$', '$\approx 5.8 \times 10^{-8}\;\text{m}$', 'option4', '$\Delta x \geq h/(4\pi m\Delta v) = 6.626 \times 10^{-34}/(4\pi \times 9.1 \times 10^{-31} \times 10^3) = 5.79 \times 10^{-8}\;\text{m}$.', 'c_dual_nature_uncertainty', 2, 'JEE Mains Prep', 'approved'),
('The wave nature of electrons was experimentally verified by', 'Davisson and Germer', 'Bohr', 'Planck', 'Rutherford', 'option1', 'Davisson and Germer (1927) observed electron diffraction from a nickel crystal, confirming de Broglie''s hypothesis.', 'c_dual_nature_uncertainty', 2, 'JEE Mains Prep', 'approved'),
('A ball of mass $0.1\;\text{kg}$ moving at $10\;\text{m/s}$ has de Broglie wavelength of order', '$10^{-20}\;\text{m}$', '$10^{-10}\;\text{m}$', '$10^{-34}\;\text{m}$', '$10^{-5}\;\text{m}$', 'option3', '$\lambda = h/(mv) = 6.626 \times 10^{-34}/(0.1 \times 10) = 6.626 \times 10^{-34}\;\text{m}$. Undetectably small.', 'c_dual_nature_uncertainty', 2, 'JEE Mains Prep', 'approved'),
('The product $\Delta E \cdot \Delta t$ in the energy-time uncertainty relation is at least', '$h/(4\pi)$', '$h$', '$h/(2\pi)$', 'Zero', 'option1', '$\Delta E \cdot \Delta t \geq \hbar/2 = h/(4\pi)$. This limits how precisely energy can be measured in a short time.', 'c_dual_nature_uncertainty', 3, 'JEE Mains Prep', 'approved'),
('Two particles of masses $m$ and $4m$ have the same kinetic energy. The ratio of their de Broglie wavelengths is', '$2:1$', '$1:2$', '$4:1$', '$1:4$', 'option1', '$\lambda = h/\sqrt{2mKE}$. $\lambda_1/\lambda_2 = \sqrt{m_2/m_1} = \sqrt{4m/m} = 2$.', 'c_dual_nature_uncertainty', 3, 'JEE Mains Prep', 'approved'),
('An alpha particle and a proton are accelerated through the same potential difference. The ratio $\lambda_\alpha/\lambda_p$ is', '$2\sqrt{2}$', '$1/(2\sqrt{2})$', '$1/2$', '$2$', 'option2', '$\lambda = h/\sqrt{2mqV}$. $\lambda_\alpha/\lambda_p = \sqrt{m_p q_p/(m_\alpha q_\alpha)} = \sqrt{1 \times 1/(4 \times 2)} = 1/(2\sqrt{2})$.', 'c_dual_nature_uncertainty', 3, 'JEE Mains Prep', 'approved'),
('The uncertainty principle explains why electrons cannot exist inside the nucleus because', 'The confinement to nuclear size ($\sim 10^{-15}\;\text{m}$) would require impossibly high kinetic energy', 'Electrons are too heavy', 'The nucleus repels electrons', 'Electrons have no mass', 'option1', 'If $\Delta x \sim 10^{-15}\;\text{m}$: $\Delta p \geq h/(4\pi\Delta x) \sim 10^{-19}\;\text{kg}\cdot\text{m/s}$. $KE = p^2/(2m_e) \sim 10^{10}\;\text{eV}$, far exceeding nuclear binding energies.', 'c_dual_nature_uncertainty', 3, 'JEE Mains Prep', 'approved'),
('The de Broglie wavelength of a gas molecule at temperature $T$ is', '$h\sqrt{3mk_BT}$', '$h/\sqrt{3mk_BT}$', '$\sqrt{3mk_BT}/h$', '$h/(3mk_BT)$', 'option2', 'Average KE $= \frac{3}{2}k_BT$. $\lambda = h/\sqrt{2m \times \frac{3}{2}k_BT} = h/\sqrt{3mk_BT}$.', 'c_dual_nature_uncertainty', 3, 'JEE Mains Prep', 'approved'),
('A photon and an electron have the same wavelength. The ratio of their momenta is', '$m_e c:\lambda$', '$c:v$', '$v:c$', '$1:1$', 'option4', 'Same wavelength means same $p = h/\lambda$. Ratio $= 1:1$.', 'c_dual_nature_uncertainty', 3, 'JEE Mains Prep', 'approved'),
('The Heisenberg uncertainty principle is not significant for macroscopic objects because', 'Their mass is so large that the uncertainty in position/momentum is negligibly small', 'They do not have wave nature', 'Classical mechanics is always exact', 'Planck''s constant is zero for large objects', 'option1', 'For large $m$: $\Delta x \geq h/(4\pi m\Delta v)$ is extremely small (e.g., $\sim 10^{-34}\;\text{m}$ for a $1\;\text{kg}$ object).', 'c_dual_nature_uncertainty', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_quantum_mechanics_orbitals (7 easy, 7 medium, 7 hard = 21)
-- Quantum mechanical model, orbitals, wave functions, quantum numbers
-- ============================================================
('The Schrödinger wave equation describes', 'The exact path of an electron', 'The probability of finding an electron in a region of space', 'The speed of an electron', 'The mass of an electron', 'option2', 'The wave function $\psi$ gives the probability amplitude. $|\psi|^2$ gives the probability density of finding the electron.', 'c_quantum_mechanics_orbitals', 1, 'JEE Mains Prep', 'approved'),
('The principal quantum number $n$ determines', 'The shape of the orbital', 'The energy and size of the orbital', 'The orientation of the orbital', 'The spin of the electron', 'option2', '$n = 1, 2, 3, ...$ determines the shell, energy level, and average distance from the nucleus.', 'c_quantum_mechanics_orbitals', 1, 'JEE Mains Prep', 'approved'),
('The azimuthal quantum number $l$ determines', 'The energy of the orbital only', 'The shape of the orbital and the subshell', 'The orientation of the orbital', 'The spin of the electron', 'option2', '$l = 0, 1, 2, ..., (n-1)$. $l = 0$ (s), $l = 1$ (p), $l = 2$ (d), $l = 3$ (f).', 'c_quantum_mechanics_orbitals', 1, 'JEE Mains Prep', 'approved'),
('The magnetic quantum number $m_l$ determines', 'The shape of the orbital', 'The energy of the orbital', 'The orientation of the orbital in space', 'The spin of the electron', 'option3', '$m_l = -l, ..., 0, ..., +l$. It specifies the orientation of the orbital relative to an external field.', 'c_quantum_mechanics_orbitals', 1, 'JEE Mains Prep', 'approved'),
('The spin quantum number $m_s$ can have values', '$0, +1/2, -1/2$', '$0$ and $1$', '$+1$ and $-1$', '$+1/2$ and $-1/2$', 'option4', '$m_s = +1/2$ (spin up) or $-1/2$ (spin down). Each orbital can hold at most 2 electrons with opposite spins.', 'c_quantum_mechanics_orbitals', 1, 'JEE Mains Prep', 'approved'),
('The total number of orbitals in a shell with principal quantum number $n$ is', '$n$', '$n^2$', '$2n^2$', '$2n$', 'option2', 'Total orbitals $= \sum_{l=0}^{n-1}(2l+1) = n^2$. Total electrons $= 2n^2$.', 'c_quantum_mechanics_orbitals', 1, 'JEE Mains Prep', 'approved'),
('An orbital is', 'A definite circular path of an electron', 'A region of space where the probability of finding an electron is high', 'The same as an orbit', 'A fixed trajectory', 'option2', 'An orbital is a 3D region around the nucleus where there is a high probability ($\sim 90\%$) of finding the electron.', 'c_quantum_mechanics_orbitals', 1, 'JEE Mains Prep', 'approved'),
('The number of orbitals in the $d$ subshell ($l = 2$) is', '$3$', '$5$', '$7$', '$1$', 'option2', '$m_l = -2, -1, 0, +1, +2$. Five orientations, hence 5 orbitals.', 'c_quantum_mechanics_orbitals', 2, 'JEE Mains Prep', 'approved'),
('For $n = 3$, the possible values of $l$ are', '$0, 1$', '$0, 1, 2, 3$', '$1, 2, 3$', '$0, 1, 2$', 'option4', '$l = 0, 1, 2, ..., (n-1)$. For $n = 3$: $l = 0$ (3s), $1$ (3p), $2$ (3d).', 'c_quantum_mechanics_orbitals', 2, 'JEE Mains Prep', 'approved'),
('The maximum number of electrons in a subshell with $l = 3$ is', '$10$', '$14$', '$6$', '$18$', 'option2', 'Number of orbitals $= 2l + 1 = 7$. Max electrons $= 2(2l+1) = 14$.', 'c_quantum_mechanics_orbitals', 2, 'JEE Mains Prep', 'approved'),
('The set of quantum numbers $(n, l, m_l, m_s) = (2, 2, 0, +1/2)$ is', 'Valid', 'Invalid because $l$ cannot equal $n$', 'Invalid because $m_l$ is wrong', 'Invalid because $m_s$ is wrong', 'option2', 'For $n = 2$: $l$ can be $0$ or $1$ only ($l < n$). $l = 2$ is not allowed.', 'c_quantum_mechanics_orbitals', 2, 'JEE Mains Prep', 'approved'),
('The number of radial nodes in an orbital is given by', '$l$', '$n - 1$', '$n - l - 1$', '$n + l$', 'option3', 'Radial nodes $= n - l - 1$. Angular nodes $= l$. Total nodes $= n - 1$.', 'c_quantum_mechanics_orbitals', 2, 'JEE Mains Prep', 'approved'),
('The $3p$ orbital has quantum numbers', '$n = 3, l = 3$', '$n = 3, l = 0$', '$n = 3, l = 2$', '$n = 3, l = 1$', 'option4', '$p$ subshell corresponds to $l = 1$. So $3p$: $n = 3, l = 1$.', 'c_quantum_mechanics_orbitals', 2, 'JEE Mains Prep', 'approved'),
('The number of angular nodes in a $3d$ orbital is', '$0$', '$1$', '$2$', '$3$', 'option3', 'Angular nodes $= l$. For $d$ orbital: $l = 2$, so 2 angular nodes.', 'c_quantum_mechanics_orbitals', 2, 'JEE Mains Prep', 'approved'),
('Which set of quantum numbers is valid for an electron?', '$(3, 2, -3, +1/2)$', '$(3, 2, -2, +1/2)$', '$(2, 2, 1, -1/2)$', '$(1, 1, 0, +1/2)$', 'option2', 'Check: $n = 3, l = 2$ (valid, $l < n$), $m_l = -2$ (valid, $|m_l| \leq l$), $m_s = +1/2$ (valid). All others violate rules.', 'c_quantum_mechanics_orbitals', 3, 'JEE Mains Prep', 'approved'),
('The probability density of finding an electron at the nucleus ($r = 0$) for a $1s$ orbital is', 'Minimum but non-zero', 'Zero', 'Maximum', 'Undefined', 'option3', 'For $1s$: $|\psi|^2$ is maximum at $r = 0$. But the radial probability ($4\pi r^2|\psi|^2$) is zero at $r = 0$ due to the $r^2$ factor.', 'c_quantum_mechanics_orbitals', 3, 'JEE Mains Prep', 'approved'),
('The radial probability distribution function $4\pi r^2|\psi|^2$ for the $1s$ orbital has its maximum at', '$r = a_0$ (Bohr radius)', '$r = 0$', '$r = 2a_0$', '$r = \infty$', 'option1', 'The most probable distance for a $1s$ electron is $r = a_0 = 0.529\;\text{\AA}$, matching the Bohr radius.', 'c_quantum_mechanics_orbitals', 3, 'JEE Mains Prep', 'approved'),
('The number of radial nodes in a $3s$ orbital is', '$0$', '$1$', '$2$', '$3$', 'option3', 'Radial nodes $= n - l - 1 = 3 - 0 - 1 = 2$.', 'c_quantum_mechanics_orbitals', 3, 'JEE Mains Prep', 'approved'),
('The total number of nodes (radial + angular) in a $4d$ orbital is', '$2$', '$3$', '$4$', '$5$', 'option2', 'Total nodes $= n - 1 = 4 - 1 = 3$. (Radial $= 4 - 2 - 1 = 1$, Angular $= l = 2$, Total $= 3$).', 'c_quantum_mechanics_orbitals', 3, 'JEE Mains Prep', 'approved'),
('The boundary surface diagram of an orbital encloses a region where the probability of finding the electron is', '$100\%$', '$\approx 90\%$', '$50\%$', '$\approx 99.9\%$', 'option2', 'The boundary surface is drawn to enclose $\sim 90\%$ probability. $100\%$ would extend to infinity.', 'c_quantum_mechanics_orbitals', 3, 'JEE Mains Prep', 'approved'),
('For a hydrogen atom, orbitals with the same $n$ but different $l$ have', 'Different spins', 'Different energies', 'Different sizes', 'The same energy (degenerate)', 'option4', 'In hydrogen (one electron), energy depends only on $n$: $E_n = -13.6/n^2$. All subshells within a shell are degenerate.', 'c_quantum_mechanics_orbitals', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_orbital_shapes (7 easy, 7 medium, 7 hard = 21)
-- Shapes of s, p, d orbitals, electron spin
-- ============================================================
('The shape of an $s$ orbital is', 'Dumbbell', 'Spherical', 'Cloverleaf', 'Conical', 'option2', '$s$ orbitals ($l = 0$) are spherically symmetric.', 'c_orbital_shapes', 1, 'JEE Mains Prep', 'approved'),
('The shape of a $p$ orbital is', 'Spherical', 'Dumbbell (two lobes)', 'Cloverleaf', 'Ring-shaped', 'option2', '$p$ orbitals ($l = 1$) have two lobes on opposite sides of the nucleus (dumbbell shape).', 'c_orbital_shapes', 1, 'JEE Mains Prep', 'approved'),
('The number of $p$ orbitals in any shell ($n \geq 2$) is', '$1$', '$3$', '$5$', '$7$', 'option2', '$p$ subshell: $l = 1$, $m_l = -1, 0, +1$. Three orbitals: $p_x$, $p_y$, $p_z$.', 'c_orbital_shapes', 1, 'JEE Mains Prep', 'approved'),
('The electron spin quantum number was introduced to explain', 'The shape of orbitals', 'The splitting of spectral lines in a magnetic field', 'The size of atoms', 'Chemical bonding', 'option2', 'Electron spin explains the fine structure of spectral lines and the Stern-Gerlach experiment.', 'c_orbital_shapes', 1, 'JEE Mains Prep', 'approved'),
('The $d$ orbitals have shapes that are', 'Spherical', 'Dumbbell', 'Mostly cloverleaf (four lobes), except $d_{z^2}$', 'All identical', 'option3', 'Four $d$ orbitals ($d_{xy}$, $d_{xz}$, $d_{yz}$, $d_{x^2-y^2}$) have cloverleaf shapes. $d_{z^2}$ has a dumbbell with a ring.', 'c_orbital_shapes', 1, 'JEE Mains Prep', 'approved'),
('The three $p$ orbitals ($p_x$, $p_y$, $p_z$) are oriented along', 'The same axis', 'The three mutually perpendicular axes', 'Random directions', 'Only the $z$-axis', 'option2', '$p_x$, $p_y$, $p_z$ are oriented along the $x$, $y$, and $z$ axes respectively.', 'c_orbital_shapes', 1, 'JEE Mains Prep', 'approved'),
('Each orbital can hold a maximum of', '$1$ electron', '$2$ electrons with opposite spins', '$3$ electrons', '$4$ electrons', 'option2', 'Pauli exclusion: no two electrons can have the same set of four quantum numbers. Each orbital holds 2 electrons ($m_s = +1/2$ and $-1/2$).', 'c_orbital_shapes', 1, 'JEE Mains Prep', 'approved'),
('The $d_{z^2}$ orbital differs from other $d$ orbitals in that it has', 'A dumbbell shape with a doughnut (torus) in the equatorial plane', 'Four lobes like the others', 'A spherical shape', 'No angular nodes', 'option1', '$d_{z^2}$ has two lobes along the $z$-axis and a ring (torus) in the $xy$-plane. It still has 2 angular nodes.', 'c_orbital_shapes', 2, 'JEE Mains Prep', 'approved'),
('The $p$ orbitals have a nodal plane passing through', 'Infinity', 'The electron', 'The nucleus', 'The boundary surface', 'option3', 'Each $p$ orbital has one angular node (a plane through the nucleus where $\psi = 0$).', 'c_orbital_shapes', 2, 'JEE Mains Prep', 'approved'),
('The number of angular nodes in an $f$ orbital ($l = 3$) is', '$1$', '$2$', '$3$', '$4$', 'option3', 'Angular nodes $= l = 3$.', 'c_orbital_shapes', 2, 'JEE Mains Prep', 'approved'),
('The $2s$ orbital differs from the $1s$ orbital in that it', 'Has the same size', 'Has a larger size and one radial node', 'Is not spherical', 'Has no nodes', 'option2', '$2s$: larger, one radial node ($n - l - 1 = 2 - 0 - 1 = 1$). $1s$: no nodes.', 'c_orbital_shapes', 2, 'JEE Mains Prep', 'approved'),
('The $d_{xy}$ orbital has its lobes directed', 'Along the $x$ and $y$ axes', 'Between the $x$ and $y$ axes (at $45°$)', 'Along the $z$-axis', 'Along all three axes', 'option2', '$d_{xy}$ has lobes between the axes (in the $xy$-plane at $45°$ to both axes). $d_{x^2-y^2}$ has lobes along the axes.', 'c_orbital_shapes', 2, 'JEE Mains Prep', 'approved'),
('The Stern-Gerlach experiment demonstrated', 'The quantization of electron spin', 'The wave nature of electrons', 'The nuclear structure', 'The photoelectric effect', 'option1', 'A beam of silver atoms split into two in a non-uniform magnetic field, proving spin quantization ($m_s = \pm 1/2$).', 'c_orbital_shapes', 2, 'JEE Mains Prep', 'approved'),
('The sign of the wave function $\psi$ in the two lobes of a $p$ orbital is', 'The same (both positive)', 'Opposite (one positive, one negative)', 'Zero in both', 'Undefined', 'option2', 'The two lobes have opposite signs of $\psi$. The nodal plane between them has $\psi = 0$.', 'c_orbital_shapes', 2, 'JEE Mains Prep', 'approved'),
('The $4f$ orbitals have', '$3$ radial nodes and $3$ angular nodes', '$0$ radial nodes and $3$ angular nodes', '$1$ radial node and $3$ angular nodes', '$3$ radial nodes and $0$ angular nodes', 'option2', 'Radial nodes $= n - l - 1 = 4 - 3 - 1 = 0$. Angular nodes $= l = 3$. Total $= 3$.', 'c_orbital_shapes', 3, 'JEE Mains Prep', 'approved'),
('The probability of finding an electron at a node is', 'Maximum', 'Zero', '$50\%$', 'Undefined', 'option2', 'At a node, $\psi = 0$, so $|\psi|^2 = 0$. The probability of finding the electron there is zero.', 'c_orbital_shapes', 3, 'JEE Mains Prep', 'approved'),
('The $3d_{x^2-y^2}$ orbital has lobes directed', 'Between the $x$ and $y$ axes', 'Along the $x$ and $y$ axes', 'Along the $z$-axis', 'Along all three axes', 'option2', '$d_{x^2-y^2}$ has lobes along the $x$ and $y$ axes. $d_{xy}$ has lobes between them.', 'c_orbital_shapes', 3, 'JEE Mains Prep', 'approved'),
('The total number of orbitals with $n = 4$ and $l = 2$ is', '$3$', '$5$', '$7$', '$10$', 'option2', '$l = 2$ ($d$ subshell): $m_l = -2, -1, 0, +1, +2$. Five orbitals.', 'c_orbital_shapes', 3, 'JEE Mains Prep', 'approved'),
('The radial distribution function of a $2p$ orbital has', 'Two peaks', 'One peak', 'Three peaks', 'No peaks', 'option2', '$2p$: radial nodes $= n - l - 1 = 0$. One peak in the radial distribution function.', 'c_orbital_shapes', 3, 'JEE Mains Prep', 'approved'),
('The five $d$ orbitals in a free atom are', 'All degenerate (same energy)', 'All different in energy', 'Three degenerate and two non-degenerate', 'Non-degenerate in all cases', 'option1', 'In a free atom (no external field), all five $d$ orbitals have the same energy. Degeneracy is lifted in a crystal field.', 'c_orbital_shapes', 3, 'JEE Mains Prep', 'approved'),
('The angular part of the wave function for an $s$ orbital is', 'Proportional to $\cos\theta$', 'Constant (independent of $\theta$ and $\phi$)', 'Proportional to $\sin\theta$', 'Zero', 'option2', 'For $l = 0$: the angular part $Y_0^0 = 1/\sqrt{4\pi}$ (constant). This is why $s$ orbitals are spherically symmetric.', 'c_orbital_shapes', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_electron_configuration (7 easy, 7 medium, 7 hard = 21)
-- Aufbau, Pauli exclusion, Hund''s rule, electronic configuration
-- ============================================================
('The Aufbau principle states that electrons fill orbitals in order of', 'Decreasing energy', 'Increasing energy', 'Increasing size', 'Random order', 'option2', 'Aufbau (building up): electrons occupy the lowest available energy orbital first.', 'c_electron_configuration', 1, 'JEE Mains Prep', 'approved'),
('The Pauli exclusion principle states that', 'Electrons in the same subshell have parallel spins', 'Electrons always pair up', 'Electrons fill the lowest energy first', 'No two electrons in an atom can have the same set of four quantum numbers', 'option4', 'Each electron must have a unique set of $(n, l, m_l, m_s)$.', 'c_electron_configuration', 1, 'JEE Mains Prep', 'approved'),
('Hund''s rule of maximum multiplicity states that', 'Electrons pair up in orbitals before filling empty ones', 'Electrons occupy degenerate orbitals singly with parallel spins before pairing', 'Electrons fill higher energy orbitals first', 'Spin does not matter', 'option2', 'In degenerate orbitals, electrons spread out with parallel spins to minimize repulsion (maximum multiplicity).', 'c_electron_configuration', 1, 'JEE Mains Prep', 'approved'),
('The electronic configuration of carbon ($Z = 6$) is', '$1s^2 2s^2 2p^2$', '$1s^2 2s^2 2p^4$', '$1s^2 2s^1 2p^3$', '$1s^2 2p^4$', 'option1', 'C: $1s^2 2s^2 2p^2$. The two $2p$ electrons occupy different orbitals with parallel spins (Hund''s rule).', 'c_electron_configuration', 1, 'JEE Mains Prep', 'approved'),
('The order of filling of orbitals according to the $(n + l)$ rule is', '$1s < 2p < 2s < 3p < 3s < 4s$', '$1s < 2s < 2p < 3s < 3p < 3d < 4s < 4p$', '$1s < 2s < 3s < 2p < 3p < 4s < 3d$', '$1s < 2s < 2p < 3s < 3p < 4s < 3d < 4p$', 'option4', 'Madelung rule: lower $(n+l)$ fills first. For same $(n+l)$, lower $n$ fills first.', 'c_electron_configuration', 1, 'JEE Mains Prep', 'approved'),
('The maximum number of electrons in the $M$ shell ($n = 3$) is', '$8$', '$18$', '$32$', '$2$', 'option2', 'Max electrons $= 2n^2 = 2(9) = 18$.', 'c_electron_configuration', 1, 'JEE Mains Prep', 'approved'),
('The electronic configuration of neon ($Z = 10$) is', '$1s^2 2s^2 2p^4$', '$1s^2 2s^2 2p^6$', '$1s^2 2s^2 2p^5 3s^1$', '$1s^2 2s^2 3p^6$', 'option2', 'Ne: $1s^2 2s^2 2p^6$ (noble gas, completely filled $n = 2$ shell).', 'c_electron_configuration', 1, 'JEE Mains Prep', 'approved'),
('The electronic configuration of chromium ($Z = 24$) is', '$[\text{Ar}] 3d^4 4s^2$', '$[\text{Ar}] 3d^5 4s^1$', '$[\text{Ar}] 3d^3 4s^2 4p^1$', '$[\text{Ar}] 3d^6$', 'option2', 'Cr is an exception: $3d^5 4s^1$ (half-filled $d$ subshell is extra stable) instead of the expected $3d^4 4s^2$.', 'c_electron_configuration', 2, 'JEE Mains Prep', 'approved'),
('The electronic configuration of copper ($Z = 29$) is', '$[\text{Ar}] 3d^9 4s^2$', '$[\text{Ar}] 3d^{10} 4s^1$', '$[\text{Ar}] 3d^8 4s^2 4p^1$', '$[\text{Ar}] 3d^{10} 4s^2$', 'option2', 'Cu is an exception: $3d^{10} 4s^1$ (fully filled $d$ subshell is extra stable).', 'c_electron_configuration', 2, 'JEE Mains Prep', 'approved'),
('The number of unpaired electrons in Fe ($Z = 26$) in its ground state is', '$2$', '$4$', '$5$', '$6$', 'option2', 'Fe: $[\text{Ar}] 3d^6 4s^2$. In $3d^6$: by Hund''s rule, 5 orbitals get one each, then 1 pairs. Unpaired $= 4$.', 'c_electron_configuration', 2, 'JEE Mains Prep', 'approved'),
('The element with configuration $[\text{Ar}] 3d^{10} 4s^2 4p^3$ is', 'Arsenic ($Z = 33$)', 'Germanium ($Z = 32$)', 'Selenium ($Z = 34$)', 'Bromine ($Z = 35$)', 'option1', '$18 + 10 + 2 + 3 = 33$. This is arsenic (As).', 'c_electron_configuration', 2, 'JEE Mains Prep', 'approved'),
('Half-filled and fully filled subshells are extra stable due to', 'Larger atomic size', 'Lower nuclear charge', 'Higher angular momentum', 'Symmetrical distribution of electrons and exchange energy', 'option4', 'Half-filled ($d^5$, $p^3$) and fully filled ($d^{10}$, $p^6$) subshells have maximum exchange energy and symmetrical charge distribution.', 'c_electron_configuration', 2, 'JEE Mains Prep', 'approved'),
('The electronic configuration of Mn$^{2+}$ ($Z = 25$) is', '$[\text{Ar}] 3d^3 4s^2$', '$[\text{Ar}] 3d^5$', '$[\text{Ar}] 3d^4 4s^1$', '$[\text{Ar}] 3d^5 4s^2$', 'option2', 'Mn: $[\text{Ar}] 3d^5 4s^2$. Mn$^{2+}$: loses $4s^2$ first. Configuration: $[\text{Ar}] 3d^5$.', 'c_electron_configuration', 2, 'JEE Mains Prep', 'approved'),
('When forming cations, transition metals lose electrons from the _____ subshell first.', '$3d$', '$4s$', '$4p$', '$3p$', 'option2', 'Despite $4s$ filling before $3d$, ionization removes $4s$ electrons first (they have higher energy in the presence of $d$ electrons).', 'c_electron_configuration', 2, 'JEE Mains Prep', 'approved'),
('The element with the highest number of unpaired electrons among the first-row transition metals is', 'Ti ($Z = 22$)', 'Fe ($Z = 26$)', 'Co ($Z = 27$)', 'Cr ($Z = 24$) or Mn ($Z = 25$)', 'option4', 'Cr: $3d^5 4s^1$ (6 unpaired, but $4s$ has 1). Mn: $3d^5 4s^2$ (5 unpaired in $d$). Both Cr and Mn have 5 unpaired $d$ electrons. Cr has 6 total unpaired.', 'c_electron_configuration', 3, 'JEE Mains Prep', 'approved'),
('The electronic configuration of Cu$^{2+}$ is', '$[\text{Ar}] 3d^9$', '$[\text{Ar}] 3d^8 4s^1$', '$[\text{Ar}] 3d^7 4s^2$', '$[\text{Ar}] 3d^{10}$', 'option1', 'Cu: $[\text{Ar}] 3d^{10} 4s^1$. Cu$^{2+}$: loses $4s^1$ and one $3d$. Configuration: $[\text{Ar}] 3d^9$.', 'c_electron_configuration', 3, 'JEE Mains Prep', 'approved'),
('The magnetic moment of an ion with 3 unpaired electrons is approximately', '$\sqrt{15}\;\text{BM} \approx 3.87\;\text{BM}$', '$3\;\text{BM}$', '$\sqrt{3}\;\text{BM}$', '$\sqrt{8}\;\text{BM}$', 'option1', '$\mu = \sqrt{n(n+2)}\;\text{BM} = \sqrt{3 \times 5} = \sqrt{15} \approx 3.87\;\text{BM}$.', 'c_electron_configuration', 3, 'JEE Mains Prep', 'approved'),
('The element with configuration $[\text{Xe}] 4f^{14} 5d^{10} 6s^2 6p^2$ is', 'Bismuth ($Z = 83$)', 'Tin ($Z = 50$)', 'Lead ($Z = 82$)', 'Thallium ($Z = 81$)', 'option3', '$54 + 14 + 10 + 2 + 2 = 82$. This is lead (Pb).', 'c_electron_configuration', 3, 'JEE Mains Prep', 'approved'),
('The number of electrons with $m_l = 0$ in the ground state of nitrogen ($Z = 7$) is', '$3$', '$4$', '$5$', '$2$', 'option3', 'N: $1s^2 2s^2 2p^3$. Electrons with $m_l = 0$: $1s$ (2, since $l = 0$), $2s$ (2, since $l = 0$), $2p$ with $m_l = 0$ (1). Total $= 2 + 2 + 1 = 5$.', 'c_electron_configuration', 3, 'JEE Mains Prep', 'approved'),
('The exchange energy is maximum for the configuration', '$d^6$', '$d^4$', '$d^5$ (half-filled)', '$d^3$', 'option3', 'Exchange energy $\propto$ number of pairs of parallel-spin electrons $= \binom{n}{2}$ where $n$ is the number of unpaired electrons. $d^5$ has $\binom{5}{2} = 10$ exchange pairs (maximum for $d$ subshell).', 'c_electron_configuration', 3, 'JEE Mains Prep', 'approved'),
('The electronic configuration of Pd ($Z = 46$) is anomalous. It is', '$[\text{Kr}] 4d^{10} 5s^2$', '$[\text{Kr}] 4d^8 5s^2$', '$[\text{Kr}] 4d^9 5s^1$', '$[\text{Kr}] 4d^{10}$ (no $5s$ electrons)', 'option4', 'Palladium is a notable exception: all 10 electrons go into $4d$, leaving $5s$ empty. This maximizes $d$-orbital stability.', 'c_electron_configuration', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_kossel_lewis (7 easy, 7 medium, 7 hard = 21)
-- Kossel-Lewis approach, ionic and covalent bonds
-- ============================================================
('The octet rule states that atoms tend to', 'Gain or lose electrons to achieve 8 electrons in their valence shell', 'Always form ionic bonds', 'Have 2 electrons in the valence shell', 'Share all their electrons', 'option1', 'Kossel and Lewis proposed that atoms achieve noble gas configuration (8 valence electrons) through electron transfer or sharing.', 'c_kossel_lewis', 1, 'JEE Mains Prep', 'approved'),
('A covalent bond is formed by', 'Transfer of electrons', 'Sharing of electron pairs between atoms', 'Electrostatic attraction between ions', 'Metallic bonding', 'option2', 'In covalent bonding, atoms share one or more pairs of electrons to achieve stable configurations.', 'c_kossel_lewis', 1, 'JEE Mains Prep', 'approved'),
('An ionic bond is formed by', 'Sharing of electrons', 'Transfer of electrons from one atom to another', 'Delocalization of electrons', 'Magnetic attraction', 'option2', 'Ionic bonds form when one atom transfers electrons to another, creating oppositely charged ions that attract electrostatically.', 'c_kossel_lewis', 1, 'JEE Mains Prep', 'approved'),
('In the Lewis structure of water (H$_2$O), oxygen has', 'No lone pairs', 'One lone pair', 'Two lone pairs', 'Three lone pairs', 'option3', 'O has 6 valence electrons. Two are shared with H atoms (2 bond pairs), leaving 2 lone pairs.', 'c_kossel_lewis', 1, 'JEE Mains Prep', 'approved'),
('A coordinate (dative) bond is a covalent bond where', 'No electrons are shared', 'Electrons are transferred', 'Each atom contributes one electron', 'Both electrons in the shared pair come from the same atom', 'option4', 'In a coordinate bond, one atom (donor) provides both electrons of the shared pair to the other atom (acceptor).', 'c_kossel_lewis', 1, 'JEE Mains Prep', 'approved'),
('Which of the following is an ionic compound?', 'CCl$_4$', 'NaCl', 'H$_2$O', 'CH$_4$', 'option2', 'NaCl is formed by transfer of an electron from Na to Cl, creating Na$^+$ and Cl$^-$ ions.', 'c_kossel_lewis', 1, 'JEE Mains Prep', 'approved'),
('The Lewis dot structure of N$_2$ shows', 'A single bond', 'A double bond', 'A triple bond', 'No bond', 'option3', 'Each N has 5 valence electrons. They share 3 pairs (triple bond) and each retains 1 lone pair: $:$N$\equiv$N$:$', 'c_kossel_lewis', 1, 'JEE Mains Prep', 'approved'),
('The formal charge on the nitrogen atom in NH$_4^+$ is', '$0$', '$+1$', '$-1$', '$+2$', 'option2', 'N has 5 valence electrons. In NH$_4^+$: 4 bond pairs (contributes 4 electrons). Formal charge $= 5 - 0 - 4 = +1$.', 'c_kossel_lewis', 2, 'JEE Mains Prep', 'approved'),
('The Lewis structure of CO has', 'A double bond only', 'A triple bond with a lone pair on each atom', 'A single bond', 'Two double bonds', 'option2', 'CO: $:$C$\equiv$O$:$ (triple bond). Carbon has a lone pair and a formal charge of $-1$; oxygen has a lone pair and formal charge of $+1$.', 'c_kossel_lewis', 2, 'JEE Mains Prep', 'approved'),
('Which of the following violates the octet rule?', 'H$_2$O', 'BF$_3$', 'CCl$_4$', 'NF$_3$', 'option2', 'In BF$_3$, boron has only 6 electrons around it (electron-deficient). It is a Lewis acid.', 'c_kossel_lewis', 2, 'JEE Mains Prep', 'approved'),
('The bond in HCl is best described as', 'Pure ionic', 'Pure covalent', 'Polar covalent', 'Coordinate', 'option3', 'HCl has unequal sharing of electrons due to the electronegativity difference between H and Cl, making it polar covalent.', 'c_kossel_lewis', 2, 'JEE Mains Prep', 'approved'),
('PCl$_5$ violates the octet rule because phosphorus has', '8 electrons around it', '10 electrons around it (expanded octet)', '6 electrons around it', '12 electrons around it', 'option2', 'P uses its $3d$ orbitals to accommodate 10 electrons (5 bond pairs). Elements in period 3+ can expand their octet.', 'c_kossel_lewis', 2, 'JEE Mains Prep', 'approved'),
('The number of lone pairs on the central atom in XeF$_2$ is', '$1$', '$2$', '$3$', '$0$', 'option3', 'Xe has 8 valence electrons. 2 bond pairs with F, leaving 3 lone pairs on Xe. Total electron pairs $= 5$ (trigonal bipyramidal).', 'c_kossel_lewis', 2, 'JEE Mains Prep', 'approved'),
('In the Lewis structure of SO$_4^{2-}$, the formal charge on sulfur (if all bonds are single with expanded octet shown as double bonds) is minimized when sulfur forms', '4 single bonds', '2 double bonds and 2 single bonds', '4 double bonds', '1 double bond and 3 single bonds', 'option2', 'With 2 double bonds: S formal charge $= 6 - 0 - 4 = +2$... Actually with 2 double bonds and 2 single bonds: S has $6 - 0 - (2 \times 2 + 2 \times 1) = 6 - 6 = 0$. Minimized formal charge.', 'c_kossel_lewis', 2, 'JEE Mains Prep', 'approved'),
('The resonance structures of the carbonate ion CO$_3^{2-}$ show that', 'All three C-O bonds are equivalent with bond order $4/3$', 'One C-O bond is shorter than the others', 'All bonds are single bonds', 'There is no resonance', 'option1', 'CO$_3^{2-}$ has 3 equivalent resonance structures. Each C-O bond has bond order $= 4/3$ (between single and double).', 'c_kossel_lewis', 3, 'JEE Mains Prep', 'approved'),
('The species that acts as both a Lewis acid and a Lewis base is', 'BF$_3$', 'H$_2$O', 'NH$_3$', 'AlCl$_3$', 'option2', 'H$_2$O can donate a lone pair (Lewis base) and accept a proton into its lone pair (Lewis acid in autoionization). It is amphoteric.', 'c_kossel_lewis', 3, 'JEE Mains Prep', 'approved'),
('The formal charge on each oxygen in ozone (O$_3$) in its most stable Lewis structure is', 'Central O: $+1$, terminal O with double bond: $0$, terminal O with single bond: $-1$', 'All zero', 'All $-1$', 'Central O: $0$, both terminal O: $-1$', 'option1', 'O$_3$: central O forms one double bond and one single bond (with coordinate character). Formal charges: central $= +1$, double-bonded terminal $= 0$, single-bonded terminal $= -1$.', 'c_kossel_lewis', 3, 'JEE Mains Prep', 'approved'),
('Which of the following has the maximum number of resonance structures?', 'CO$_3^{2-}$', 'SO$_3$', 'NO$_3^-$', 'C$_6$H$_6$ (benzene)', 'option4', 'Benzene has 2 Kekule structures plus 3 Dewar structures (5 total). CO$_3^{2-}$, SO$_3$, and NO$_3^-$ each have 3.', 'c_kossel_lewis', 3, 'JEE Mains Prep', 'approved'),
('The bond order in the nitrate ion NO$_3^-$ is', '$1$', '$4/3$', '$3/2$', '$2$', 'option2', 'NO$_3^-$ has 3 resonance structures, each with one N=O double bond and two N-O single bonds. Bond order $= (1 + 1 + 2)/3 = 4/3$.', 'c_kossel_lewis', 3, 'JEE Mains Prep', 'approved'),
('Among BF$_3$, NF$_3$, and ClF$_3$, the species that obeys the octet rule is', 'BF$_3$ only', 'NF$_3$ only', 'ClF$_3$ only', 'All three', 'option2', 'BF$_3$: B has only 6 electrons (electron-deficient). ClF$_3$: Cl has 10 electrons (expanded octet). Only NF$_3$ has exactly 8 electrons around N.', 'c_kossel_lewis', 3, 'JEE Mains Prep', 'approved'),
('The lattice energy of an ionic compound increases with', 'Increasing covalent character', 'Decreasing ionic charge', 'Increasing ionic radii', 'Increasing ionic charge and decreasing ionic radii', 'option4', 'Lattice energy $\propto q^+ q^-/(r^+ + r^-)$ (Born-Lande equation). Higher charges and smaller ions give stronger lattice energy.', 'c_kossel_lewis', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_ionic_bonding (7 easy, 7 medium, 7 hard = 21)
-- Ionic bonding: formation, factors, lattice enthalpy
-- ============================================================
('Ionic bonds are typically formed between', 'Two non-metals', 'A metal and a non-metal', 'Two metals', 'Two noble gases', 'option2', 'Metals (low IE) lose electrons; non-metals (high EA) gain them. The resulting ions attract electrostatically.', 'c_ionic_bonding', 1, 'JEE Mains Prep', 'approved'),
('The lattice enthalpy of an ionic compound is', 'The energy of formation of the compound', 'The energy required to completely separate one mole of ionic solid into gaseous ions', 'The ionization energy of the metal', 'The electron affinity of the non-metal', 'option2', 'Lattice enthalpy is always positive (endothermic to break the lattice). Higher lattice enthalpy means stronger ionic bonding.', 'c_ionic_bonding', 1, 'JEE Mains Prep', 'approved'),
('Which of the following has the highest lattice enthalpy?', 'NaCl', 'NaF', 'NaBr', 'NaI', 'option2', 'F$^-$ is the smallest halide ion. Smaller ions $\rightarrow$ shorter interionic distance $\rightarrow$ higher lattice enthalpy.', 'c_ionic_bonding', 1, 'JEE Mains Prep', 'approved'),
('Ionic compounds generally have', 'Low melting points and are soft', 'High melting points and conduct electricity in molten state', 'Low melting points and conduct electricity', 'High melting points but never conduct electricity', 'option2', 'Strong electrostatic forces require high energy to break (high mp). Molten/dissolved ions conduct electricity.', 'c_ionic_bonding', 1, 'JEE Mains Prep', 'approved'),
('The Born-Haber cycle is used to calculate', 'Bond dissociation energy', 'Lattice enthalpy of ionic compounds', 'Ionization energy', 'Electron affinity directly', 'option2', 'The Born-Haber cycle applies Hess''s law to relate lattice enthalpy to measurable quantities (IE, EA, sublimation, dissociation, formation enthalpy).', 'c_ionic_bonding', 1, 'JEE Mains Prep', 'approved'),
('The formation of NaCl from Na and Cl$_2$ involves', 'Only electron transfer', 'Sublimation of Na, dissociation of Cl$_2$, ionization of Na, electron gain by Cl, and lattice formation', 'Only lattice formation', 'Only ionization', 'option2', 'The Born-Haber cycle includes all these steps to arrive at the overall enthalpy of formation.', 'c_ionic_bonding', 1, 'JEE Mains Prep', 'approved'),
('Ionic compounds are generally soluble in', 'Non-polar solvents like benzene', 'Polar solvents like water', 'All solvents equally', 'No solvents', 'option2', 'Polar solvents (high dielectric constant) can stabilize ions through solvation, overcoming lattice enthalpy.', 'c_ionic_bonding', 1, 'JEE Mains Prep', 'approved'),
('Among LiF, NaF, KF, and CsF, the compound with the highest lattice enthalpy is', 'CsF', 'KF', 'NaF', 'LiF', 'option4', 'Li$^+$ is the smallest alkali metal cation. Smaller cation $\rightarrow$ shorter interionic distance $\rightarrow$ highest lattice enthalpy.', 'c_ionic_bonding', 2, 'JEE Mains Prep', 'approved'),
('The lattice enthalpy of MgO is much higher than that of NaCl because', 'MgO has lower melting point', 'MgO has covalent character', 'NaCl is more ionic', 'Mg$^{2+}$ and O$^{2-}$ have higher charges and smaller sizes than Na$^+$ and Cl$^-$', 'option4', 'Lattice enthalpy $\propto q^+ \times q^-/r$. MgO: $2 \times 2 = 4$ vs NaCl: $1 \times 1 = 1$. Also Mg$^{2+}$ and O$^{2-}$ are smaller.', 'c_ionic_bonding', 2, 'JEE Mains Prep', 'approved'),
('Fajan''s rules predict that covalent character in an ionic bond increases when', 'The cation is small and highly charged, and the anion is large and highly charged', 'Both ions are large', 'The cation is large', 'The anion is small', 'option1', 'Small, highly charged cation polarizes the large, highly charged anion, distorting its electron cloud towards covalent character.', 'c_ionic_bonding', 2, 'JEE Mains Prep', 'approved'),
('According to Fajan''s rules, which of the following has the most covalent character?', 'NaCl', 'MgCl$_2$', 'AlCl$_3$', 'KCl', 'option3', 'Al$^{3+}$ has the highest charge/size ratio among Na$^+$, Mg$^{2+}$, Al$^{3+}$, K$^+$. It polarizes Cl$^-$ the most.', 'c_ionic_bonding', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy of formation of NaCl is $-411\;\text{kJ/mol}$. This means', 'Energy is absorbed during formation', 'NaCl is unstable', 'The formation of NaCl from its elements is exothermic', 'The lattice enthalpy is $-411\;\text{kJ/mol}$', 'option3', 'Negative $\Delta H_f$ means the reaction Na(s) + $\frac{1}{2}$Cl$_2$(g) $\rightarrow$ NaCl(s) releases energy.', 'c_ionic_bonding', 2, 'JEE Mains Prep', 'approved'),
('The coordination number of Na$^+$ in the NaCl crystal structure is', '$4$', '$6$', '$8$', '$12$', 'option2', 'In the rock salt (NaCl) structure, each Na$^+$ is surrounded by 6 Cl$^-$ ions (octahedral coordination).', 'c_ionic_bonding', 2, 'JEE Mains Prep', 'approved'),
('The coordination number of Cs$^+$ in CsCl crystal structure is', '$4$', '$6$', '$8$', '$12$', 'option3', 'In the CsCl structure (BCC-like), each Cs$^+$ is surrounded by 8 Cl$^-$ ions (cubic coordination).', 'c_ionic_bonding', 2, 'JEE Mains Prep', 'approved'),
('Using the Born-Haber cycle for NaCl: sublimation of Na $= 108$, IE of Na $= 496$, dissociation of Cl$_2 = 242$ (per mole Cl), EA of Cl $= -349$, $\Delta H_f = -411\;\text{kJ/mol}$. The lattice enthalpy is', '$-788\;\text{kJ/mol}$', '$+788\;\text{kJ/mol}$', '$-411\;\text{kJ/mol}$', '$+908\;\text{kJ/mol}$', 'option2', '$\Delta H_f = \Delta H_{sub} + IE + \frac{1}{2}D + EA - U$. $-411 = 108 + 496 + 121 - 349 - U$. $-411 = 376 - U$. $U = 787 \approx 788\;\text{kJ/mol}$ (positive, endothermic to break lattice).', 'c_ionic_bonding', 3, 'JEE Mains Prep', 'approved'),
('The Madelung constant depends on', 'The sizes of the ions', 'The charges of the ions', 'The geometry of the crystal lattice only', 'The temperature', 'option3', 'The Madelung constant is a dimensionless number determined solely by the crystal structure geometry (e.g., 1.748 for NaCl, 1.763 for CsCl).', 'c_ionic_bonding', 3, 'JEE Mains Prep', 'approved'),
('Among LiCl, LiBr, and LiI, the order of covalent character is', 'LiCl $>$ LiBr $>$ LiI', 'LiI $>$ LiBr $>$ LiCl', 'LiBr $>$ LiCl $>$ LiI', 'All are equally ionic', 'option2', 'Larger anion (I$^-$ $>$ Br$^-$ $>$ Cl$^-$) is more easily polarized by Li$^+$, increasing covalent character.', 'c_ionic_bonding', 3, 'JEE Mains Prep', 'approved'),
('The solubility of ionic compounds in water depends on the balance between', 'Lattice enthalpy and hydration enthalpy', 'Only lattice enthalpy', 'Only hydration enthalpy', 'Ionization energy and electron affinity', 'option1', 'Dissolution occurs when hydration enthalpy (exothermic, stabilizing ions in solution) exceeds lattice enthalpy (endothermic, breaking the lattice).', 'c_ionic_bonding', 3, 'JEE Mains Prep', 'approved'),
('AgCl has significant covalent character despite being considered ionic because', 'Ag$^+$ has a pseudo-noble gas configuration ($d^{10}$) and high polarizing power', 'Ag is a non-metal', 'Cl is very small', 'AgCl has low lattice enthalpy', 'option1', 'Ag$^+$ ($d^{10}$, not a true noble gas core) has high polarizing power, distorting Cl$^-$ electron cloud significantly.', 'c_ionic_bonding', 3, 'JEE Mains Prep', 'approved'),
('The Born-Lande equation for lattice energy includes the term $(1 - 1/n)$ where $n$ is', 'The number of ions', 'The Born exponent related to the repulsive forces between ions', 'The coordination number', 'The Madelung constant', 'option2', 'The Born exponent $n$ accounts for short-range repulsion when electron clouds overlap. Typical values: 5-12 depending on ion configuration.', 'c_ionic_bonding', 3, 'JEE Mains Prep', 'approved'),
('The compound with the highest melting point among NaF, NaCl, NaBr, NaI is', 'NaI', 'NaBr', 'NaCl', 'NaF', 'option4', 'NaF has the highest lattice enthalpy (smallest anion) and therefore the highest melting point (993°C vs 801°C for NaCl).', 'c_ionic_bonding', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_covalent_vsepr (7 easy, 7 medium, 7 hard = 21)
-- Covalent bonding, electronegativity, VSEPR, molecular shapes
-- ============================================================
('Electronegativity is the tendency of an atom to', 'Lose electrons', 'Attract shared electrons towards itself in a covalent bond', 'Repel electrons', 'Donate electrons', 'option2', 'Pauling defined electronegativity as the ability of an atom in a molecule to attract bonding electrons.', 'c_covalent_vsepr', 1, 'JEE Mains Prep', 'approved'),
('The most electronegative element is', 'Oxygen', 'Chlorine', 'Fluorine', 'Nitrogen', 'option3', 'Fluorine has the highest electronegativity (3.98 on the Pauling scale).', 'c_covalent_vsepr', 1, 'JEE Mains Prep', 'approved'),
('VSEPR theory predicts molecular geometry based on', 'The number of protons', 'The electronegativity of atoms', 'The atomic mass', 'The number of electron pairs (bonding and lone) around the central atom', 'option4', 'VSEPR: Valence Shell Electron Pair Repulsion. Electron pairs arrange to minimize repulsion, determining geometry.', 'c_covalent_vsepr', 1, 'JEE Mains Prep', 'approved'),
('The shape of methane (CH$_4$) is', 'Square planar', 'Tetrahedral', 'Trigonal pyramidal', 'Linear', 'option2', '4 bond pairs, 0 lone pairs on C. VSEPR: tetrahedral with bond angle $109.5°$.', 'c_covalent_vsepr', 1, 'JEE Mains Prep', 'approved'),
('The shape of water (H$_2$O) is', 'Linear', 'Trigonal planar', 'Bent (V-shaped)', 'Tetrahedral', 'option3', '2 bond pairs + 2 lone pairs on O. Electron geometry: tetrahedral. Molecular shape: bent. Bond angle $\approx 104.5°$.', 'c_covalent_vsepr', 1, 'JEE Mains Prep', 'approved'),
('The dipole moment of a molecule is zero when', 'The molecule is symmetric and bond dipoles cancel', 'All bonds are polar', 'The molecule has lone pairs', 'The molecule is large', 'option1', 'Symmetric molecules (CO$_2$, BF$_3$, CCl$_4$) have zero net dipole despite having polar bonds.', 'c_covalent_vsepr', 1, 'JEE Mains Prep', 'approved'),
('The shape of BF$_3$ is', 'Tetrahedral', 'Trigonal planar', 'Pyramidal', 'Linear', 'option2', '3 bond pairs, 0 lone pairs on B. VSEPR: trigonal planar with bond angle $120°$.', 'c_covalent_vsepr', 1, 'JEE Mains Prep', 'approved'),
('The shape of ammonia (NH$_3$) is', 'Tetrahedral', 'Trigonal planar', 'Trigonal pyramidal', 'Bent', 'option3', '3 bond pairs + 1 lone pair on N. Electron geometry: tetrahedral. Molecular shape: trigonal pyramidal. Bond angle $\approx 107°$.', 'c_covalent_vsepr', 2, 'JEE Mains Prep', 'approved'),
('The bond angle in NH$_3$ ($107°$) is less than in CH$_4$ ($109.5°$) because', 'H atoms are larger in NH$_3$', 'N is smaller than C', 'Lone pair-bond pair repulsion is greater than bond pair-bond pair repulsion', 'NH$_3$ has fewer bonds', 'option3', 'Lone pairs occupy more space than bond pairs, compressing the bond angles.', 'c_covalent_vsepr', 2, 'JEE Mains Prep', 'approved'),
('The shape of SF$_6$ is', 'Trigonal bipyramidal', 'Octahedral', 'Square planar', 'Tetrahedral', 'option2', '6 bond pairs, 0 lone pairs on S. VSEPR: octahedral with bond angles $90°$.', 'c_covalent_vsepr', 2, 'JEE Mains Prep', 'approved'),
('The shape of XeF$_4$ is', 'Tetrahedral', 'Square planar', 'See-saw', 'Octahedral', 'option2', '4 bond pairs + 2 lone pairs on Xe. Electron geometry: octahedral. Lone pairs occupy opposite positions. Molecular shape: square planar.', 'c_covalent_vsepr', 2, 'JEE Mains Prep', 'approved'),
('Which molecule has a non-zero dipole moment?', 'CO$_2$', 'BF$_3$', 'CHCl$_3$', 'CCl$_4$', 'option3', 'CHCl$_3$ (chloroform) is not symmetric — the C-H bond dipole does not cancel the three C-Cl dipoles. Net dipole $\neq 0$.', 'c_covalent_vsepr', 2, 'JEE Mains Prep', 'approved'),
('The shape of PCl$_5$ is', 'Square pyramidal', 'Trigonal bipyramidal', 'Octahedral', 'Pentagonal planar', 'option2', '5 bond pairs, 0 lone pairs on P. VSEPR: trigonal bipyramidal (3 equatorial at $120°$, 2 axial at $90°$).', 'c_covalent_vsepr', 2, 'JEE Mains Prep', 'approved'),
('The shape of ClF$_3$ is', 'Trigonal planar', 'T-shaped', 'Trigonal pyramidal', 'Linear', 'option2', '3 bond pairs + 2 lone pairs on Cl. Electron geometry: trigonal bipyramidal. Lone pairs in equatorial positions. Molecular shape: T-shaped.', 'c_covalent_vsepr', 2, 'JEE Mains Prep', 'approved'),
('The order of bond angles: CH$_4$ $>$ NH$_3$ $>$ H$_2$O is explained by', 'Increasing number of lone pairs compressing bond angles', 'Decreasing electronegativity', 'Increasing atomic size', 'Decreasing number of bonds', 'option1', 'CH$_4$: 0 lone pairs ($109.5°$). NH$_3$: 1 lone pair ($107°$). H$_2$O: 2 lone pairs ($104.5°$). More lone pairs $\rightarrow$ more compression.', 'c_covalent_vsepr', 3, 'JEE Mains Prep', 'approved'),
('In PCl$_5$, the axial P-Cl bonds are longer than equatorial P-Cl bonds because', 'Axial bonds experience more repulsion from 3 equatorial pairs at $90°$', 'Equatorial bonds are ionic', 'Axial Cl atoms are larger', 'The molecule is unstable', 'option1', 'Axial positions have 3 close ($90°$) neighbours vs equatorial positions with only 2 close neighbours. More repulsion weakens and lengthens axial bonds.', 'c_covalent_vsepr', 3, 'JEE Mains Prep', 'approved'),
('The shape of XeF$_2$ is', 'Bent', 'Linear', 'Trigonal planar', 'T-shaped', 'option2', '2 bond pairs + 3 lone pairs on Xe. Electron geometry: trigonal bipyramidal. Lone pairs in equatorial positions. Molecular shape: linear ($180°$).', 'c_covalent_vsepr', 3, 'JEE Mains Prep', 'approved'),
('Among NF$_3$ and BF$_3$, the molecule with non-zero dipole moment is', 'BF$_3$', 'NF$_3$', 'Both', 'Neither', 'option2', 'BF$_3$ is trigonal planar (symmetric, $\mu = 0$). NF$_3$ is trigonal pyramidal (asymmetric, $\mu \neq 0$).', 'c_covalent_vsepr', 3, 'JEE Mains Prep', 'approved'),
('The dipole moment of NF$_3$ ($0.24\;\text{D}$) is much less than NH$_3$ ($1.47\;\text{D}$) because', 'NF$_3$ is non-polar', 'In NF$_3$, the bond dipoles oppose the lone pair dipole; in NH$_3$, they reinforce it', 'NH$_3$ has more lone pairs', 'F is less electronegative than H', 'option2', 'In NH$_3$: bond dipoles (H$\rightarrow$N) and lone pair dipole point in the same direction. In NF$_3$: bond dipoles (N$\rightarrow$F) oppose the lone pair dipole, nearly cancelling.', 'c_covalent_vsepr', 3, 'JEE Mains Prep', 'approved'),
('The shape of IF$_7$ is', 'Octahedral', 'Pentagonal bipyramidal', 'Capped octahedral', 'Trigonal bipyramidal', 'option2', '7 bond pairs, 0 lone pairs on I. VSEPR: pentagonal bipyramidal (5 equatorial + 2 axial).', 'c_covalent_vsepr', 3, 'JEE Mains Prep', 'approved'),
('The percentage ionic character of a bond with dipole moment $\mu$ and bond length $d$ is', '$e \times d/\mu \times 100\%$', '$\mu \times d \times 100\%$', '$(\mu/(e \times d)) \times 100\%$', '$\mu^2/(e \times d) \times 100\%$', 'option3', '$\%$ ionic character $= (\mu_{observed}/\mu_{ionic}) \times 100 = \mu/(e \times d) \times 100$ where $e = 1.6 \times 10^{-19}\;\text{C}$.', 'c_covalent_vsepr', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_vbt_hybridization (7 easy, 7 medium, 7 hard = 21)
-- VBT, hybridization (s, p, d orbitals), resonance
-- ============================================================
('In $sp^3$ hybridization, the geometry is', 'Linear', 'Trigonal planar', 'Tetrahedral', 'Octahedral', 'option3', '$sp^3$: 4 equivalent hybrid orbitals directed towards the corners of a tetrahedron ($109.5°$).', 'c_vbt_hybridization', 1, 'JEE Mains Prep', 'approved'),
('In $sp^2$ hybridization, the geometry is', 'Linear', 'Trigonal planar', 'Tetrahedral', 'Square planar', 'option2', '$sp^2$: 3 equivalent hybrid orbitals in a plane at $120°$. One unhybridized $p$ orbital remains.', 'c_vbt_hybridization', 1, 'JEE Mains Prep', 'approved'),
('In $sp$ hybridization, the geometry is', 'Linear', 'Trigonal planar', 'Tetrahedral', 'Bent', 'option1', '$sp$: 2 equivalent hybrid orbitals at $180°$ (linear). Two unhybridized $p$ orbitals remain.', 'c_vbt_hybridization', 1, 'JEE Mains Prep', 'approved'),
('The hybridization of carbon in methane (CH$_4$) is', '$sp$', '$sp^2$', '$sp^3$', '$sp^3d$', 'option3', 'C forms 4 equivalent bonds with H. 4 hybrid orbitals $\rightarrow$ $sp^3$.', 'c_vbt_hybridization', 1, 'JEE Mains Prep', 'approved'),
('The hybridization of carbon in ethylene (C$_2$H$_4$) is', '$sp$', '$sp^2$', '$sp^3$', '$sp^3d$', 'option2', 'Each C forms 3 $\sigma$ bonds (2 C-H + 1 C-C) and 1 $\pi$ bond. 3 hybrid orbitals $\rightarrow$ $sp^2$.', 'c_vbt_hybridization', 1, 'JEE Mains Prep', 'approved'),
('A sigma ($\sigma$) bond is formed by', 'Lateral overlap of orbitals', 'Head-on (axial) overlap of orbitals', 'No overlap', 'Electrostatic attraction', 'option2', '$\sigma$ bonds have electron density concentrated along the internuclear axis (head-on overlap).', 'c_vbt_hybridization', 1, 'JEE Mains Prep', 'approved'),
('A pi ($\pi$) bond is formed by', 'Head-on overlap', 'Lateral (sideways) overlap of $p$ orbitals', 'Overlap of $s$ orbitals', 'Ionic interaction', 'option2', '$\pi$ bonds have electron density above and below the internuclear axis (lateral overlap of unhybridized $p$ orbitals).', 'c_vbt_hybridization', 1, 'JEE Mains Prep', 'approved'),
('The hybridization of nitrogen in NH$_3$ is', '$sp$', '$sp^2$', '$sp^3$', '$sp^3d$', 'option3', 'N has 3 bond pairs + 1 lone pair $= 4$ electron domains $\rightarrow$ $sp^3$ hybridization.', 'c_vbt_hybridization', 2, 'JEE Mains Prep', 'approved'),
('The hybridization of carbon in acetylene (C$_2$H$_2$) is', '$dsp^2$', '$sp^2$', '$sp^3$', '$sp$', 'option4', 'Each C forms 2 $\sigma$ bonds (1 C-H + 1 C-C) and 2 $\pi$ bonds. 2 hybrid orbitals $\rightarrow$ $sp$.', 'c_vbt_hybridization', 2, 'JEE Mains Prep', 'approved'),
('The number of $\sigma$ and $\pi$ bonds in C$_2$H$_2$ is', '3$\sigma$, 2$\pi$', '2$\sigma$, 3$\pi$', '5$\sigma$, 0$\pi$', '2$\sigma$, 2$\pi$', 'option1', 'C$_2$H$_2$: 1 C-C $\sigma$ + 2 C-H $\sigma$ + 2 C-C $\pi$ $= 3\sigma + 2\pi$.', 'c_vbt_hybridization', 2, 'JEE Mains Prep', 'approved'),
('The hybridization of sulfur in SF$_6$ is', '$sp^3$', '$sp^3d$', '$sp^3d^2$', '$d^2sp^3$', 'option3', 'S has 6 bond pairs $\rightarrow$ 6 hybrid orbitals $\rightarrow$ $sp^3d^2$ (octahedral).', 'c_vbt_hybridization', 2, 'JEE Mains Prep', 'approved'),
('Resonance structures differ in', 'The arrangement of atoms', 'The distribution of electrons only', 'The number of atoms', 'The molecular formula', 'option2', 'Resonance structures have the same atomic arrangement but different electron distributions (bond positions).', 'c_vbt_hybridization', 2, 'JEE Mains Prep', 'approved'),
('The hybridization of phosphorus in PCl$_5$ is', '$sp^3$', '$sp^3d$', '$sp^3d^2$', '$sp^2$', 'option2', 'P has 5 bond pairs $\rightarrow$ 5 hybrid orbitals $\rightarrow$ $sp^3d$ (trigonal bipyramidal).', 'c_vbt_hybridization', 2, 'JEE Mains Prep', 'approved'),
('The hybridization of Xe in XeF$_4$ is', '$sp^3$', '$sp^3d$', '$sp^3d^2$', '$dsp^2$', 'option3', 'Xe has 4 bond pairs + 2 lone pairs $= 6$ electron domains $\rightarrow$ $sp^3d^2$ (octahedral electron geometry, square planar molecular shape).', 'c_vbt_hybridization', 2, 'JEE Mains Prep', 'approved'),
('In benzene (C$_6$H$_6$), each carbon is $sp^2$ hybridized. The delocalized $\pi$ system contains', '$3$ electrons', '$6$ electrons', '$12$ electrons', '$2$ electrons', 'option2', 'Each C contributes 1 unhybridized $p$ electron. 6 carbons $\rightarrow$ 6 $\pi$ electrons delocalized over the ring.', 'c_vbt_hybridization', 3, 'JEE Mains Prep', 'approved'),
('The C-C bond length in benzene ($1.39\;\text{\AA}$) is between that of a C-C single bond ($1.54\;\text{\AA}$) and C=C double bond ($1.34\;\text{\AA}$) because', 'Benzene has alternating single and double bonds', 'Benzene has resonance — the actual structure is a hybrid of two Kekule structures', 'Benzene is not aromatic', 'The bonds are ionic', 'option2', 'Resonance delocalizes the $\pi$ electrons, making all C-C bonds equivalent with bond order $1.5$.', 'c_vbt_hybridization', 3, 'JEE Mains Prep', 'approved'),
('The number of $\sigma$ and $\pi$ bonds in CH$_2$=CH-CH=CH$_2$ (1,3-butadiene) is', '9$\sigma$, 2$\pi$', '7$\sigma$, 2$\pi$', '8$\sigma$, 3$\pi$', '10$\sigma$, 2$\pi$', 'option1', '3 C-C $\sigma$ + 6 C-H $\sigma$ + 2 C=C $\pi$ $= 9\sigma + 2\pi$.', 'c_vbt_hybridization', 3, 'JEE Mains Prep', 'approved'),
('The hybridization of the central atom in ICl$_4^-$ is', '$sp^3$', '$sp^3d$', '$sp^3d^2$', '$dsp^2$', 'option3', 'I has 4 bond pairs + 2 lone pairs $= 6$ electron domains $\rightarrow$ $sp^3d^2$. Shape: square planar.', 'c_vbt_hybridization', 3, 'JEE Mains Prep', 'approved'),
('In the molecule H$_2$CO (formaldehyde), the hybridization of C and the number of $\pi$ bonds are', '$sp^2$, 1 $\pi$ bond', '$sp^3$, 0 $\pi$ bonds', '$sp$, 2 $\pi$ bonds', '$sp^2$, 2 $\pi$ bonds', 'option1', 'C forms 2 C-H $\sigma$ + 1 C=O ($\sigma + \pi$). 3 $\sigma$ domains $\rightarrow$ $sp^2$. One $\pi$ bond.', 'c_vbt_hybridization', 3, 'JEE Mains Prep', 'approved'),
('The resonance energy of benzene is approximately', '$150\;\text{kJ/mol}$', '$36\;\text{kJ/mol}$', '$250\;\text{kJ/mol}$', '$75\;\text{kJ/mol}$', 'option1', 'Benzene is $\sim 150\;\text{kJ/mol}$ more stable than the hypothetical cyclohexatriene (Kekule structure). This stabilization is the resonance energy.', 'c_vbt_hybridization', 3, 'JEE Mains Prep', 'approved'),
('The hybridization of S in SO$_2$ is', '$sp$', '$sp^2$', '$sp^3$', '$sp^3d$', 'option2', 'S has 2 bond pairs (double bonds to O) + 1 lone pair $= 3$ electron domains $\rightarrow$ $sp^2$. Shape: bent.', 'c_vbt_hybridization', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_mot (7 easy, 7 medium, 7 hard = 21)
-- MOT: LCAOs, bonding/antibonding orbitals, sigma/pi bonds
-- ============================================================
('In Molecular Orbital Theory, atomic orbitals combine to form', 'Hybrid orbitals', 'Molecular orbitals that belong to the molecule as a whole', 'Ionic bonds', 'Localized bonds only', 'option2', 'MOT: atomic orbitals combine (LCAO) to form molecular orbitals that are delocalized over the entire molecule.', 'c_mot', 1, 'JEE Mains Prep', 'approved'),
('When two atomic orbitals combine, they form', 'One molecular orbital', 'Two molecular orbitals (one bonding, one antibonding)', 'Three molecular orbitals', 'No molecular orbitals', 'option2', 'LCAO: $n$ atomic orbitals combine to form $n$ molecular orbitals — half bonding, half antibonding.', 'c_mot', 1, 'JEE Mains Prep', 'approved'),
('A bonding molecular orbital has', 'Higher energy than the constituent atomic orbitals', 'Lower energy than the constituent atomic orbitals', 'The same energy as atomic orbitals', 'No electrons', 'option2', 'Bonding MOs result from constructive interference — electron density increases between nuclei, lowering energy.', 'c_mot', 1, 'JEE Mains Prep', 'approved'),
('An antibonding molecular orbital is denoted by', '$\sigma$', '$\sigma^*$', '$\pi$', '$\delta$', 'option2', 'Antibonding orbitals are marked with an asterisk: $\sigma^*$, $\pi^*$. They have a node between the nuclei.', 'c_mot', 1, 'JEE Mains Prep', 'approved'),
('Bond order in MOT is calculated as', '(Bonding electrons $-$ Antibonding electrons) $/$ 2', '(Bonding $+$ Antibonding) $/$ 2', 'Bonding electrons only', 'Number of bonds in Lewis structure', 'option1', 'Bond order $= (N_b - N_a)/2$. Higher bond order means stronger, shorter bond.', 'c_mot', 1, 'JEE Mains Prep', 'approved'),
('If bond order is zero, the molecule', 'Is very stable', 'Does not exist (unstable)', 'Has a single bond', 'Has a triple bond', 'option2', 'Bond order $= 0$ means no net bonding — the molecule is unstable and does not form.', 'c_mot', 1, 'JEE Mains Prep', 'approved'),
('The $\sigma$ bonding molecular orbital formed from two $1s$ orbitals has', 'A node between the nuclei', 'Increased electron density between the nuclei', 'Decreased electron density between the nuclei', 'No electron density anywhere', 'option2', 'Constructive overlap of $1s$ orbitals concentrates electron density between the nuclei (bonding).', 'c_mot', 1, 'JEE Mains Prep', 'approved'),
('The MO energy level diagram for O$_2$ differs from that of N$_2$ in that', 'N$_2$ has no $\sigma$ bonds', 'They are identical', 'O$_2$ has no $\pi$ bonds', 'In O$_2$, $\sigma_{2p}$ is lower in energy than $\pi_{2p}$; in N$_2$, $\pi_{2p}$ is lower', 'option4', 'For O$_2$, F$_2$, Ne$_2$: $\sigma_{2p} < \pi_{2p}$ (normal order). For B$_2$, C$_2$, N$_2$: $\pi_{2p} < \sigma_{2p}$ (due to $s$-$p$ mixing).', 'c_mot', 2, 'JEE Mains Prep', 'approved'),
('The bond order of O$_2$ is', '$1$', '$2$', '$3$', '$1.5$', 'option2', 'O$_2$: $\sigma_{1s}^2 \sigma^*_{1s}^2 \sigma_{2s}^2 \sigma^*_{2s}^2 \sigma_{2p}^2 \pi_{2p}^4 \pi^*_{2p}^2$. $N_b = 10$, $N_a = 6$. BO $= (10-6)/2 = 2$.', 'c_mot', 2, 'JEE Mains Prep', 'approved'),
('O$_2$ is paramagnetic because', 'It is ionic', 'It has no unpaired electrons', 'It has two unpaired electrons in $\pi^*_{2p}$ orbitals', 'It has a triple bond', 'option3', 'The two $\pi^*_{2p}$ electrons occupy separate degenerate orbitals with parallel spins (Hund''s rule), making O$_2$ paramagnetic.', 'c_mot', 2, 'JEE Mains Prep', 'approved'),
('The bond order of N$_2$ is', '$1$', '$2$', '$3$', '$2.5$', 'option3', 'N$_2$: $N_b = 10$, $N_a = 4$. BO $= (10-4)/2 = 3$ (triple bond). N$_2$ is very stable.', 'c_mot', 2, 'JEE Mains Prep', 'approved'),
('He$_2$ does not exist because its bond order is', '$1$', '$0.5$', '$0$', '$-1$', 'option3', 'He$_2$: $\sigma_{1s}^2 \sigma^*_{1s}^2$. BO $= (2-2)/2 = 0$. No net bonding.', 'c_mot', 2, 'JEE Mains Prep', 'approved'),
('The species He$_2^+$ has bond order', '$0$', '$0.5$', '$1$', '$1.5$', 'option2', 'He$_2^+$: $\sigma_{1s}^2 \sigma^*_{1s}^1$. BO $= (2-1)/2 = 0.5$. It exists but is weakly bonded.', 'c_mot', 2, 'JEE Mains Prep', 'approved'),
('The $s$-$p$ mixing (hybridization of $\sigma_{2s}$ and $\sigma_{2p}$) is significant for', 'B$_2$, C$_2$, N$_2$ (elements with small $2s$-$2p$ energy gap)', 'O$_2$, F$_2$ only', 'All diatomic molecules', 'No molecules', 'option1', 'For lighter elements (B, C, N), the $2s$-$2p$ energy gap is small, causing $s$-$p$ mixing that raises $\sigma_{2p}$ above $\pi_{2p}$.', 'c_mot', 2, 'JEE Mains Prep', 'approved'),
('The bond order of O$_2^-$ (superoxide ion) is', '$1$', '$1.5$', '$2$', '$2.5$', 'option2', 'O$_2^-$: one extra electron in $\pi^*$. $N_b = 10$, $N_a = 7$. BO $= (10-7)/2 = 1.5$.', 'c_mot', 3, 'JEE Mains Prep', 'approved'),
('Among O$_2$, O$_2^+$, O$_2^-$, and O$_2^{2-}$, the correct order of bond length is', 'O$_2^{2-} <$ O$_2^- <$ O$_2 <$ O$_2^+$', 'O$_2^+ <$ O$_2 <$ O$_2^- <$ O$_2^{2-}$', 'All are equal', 'O$_2 <$ O$_2^+ <$ O$_2^- <$ O$_2^{2-}$', 'option2', 'Bond orders: O$_2^+$ (2.5) $>$ O$_2$ (2) $>$ O$_2^-$ (1.5) $>$ O$_2^{2-}$ (1). Higher BO $\rightarrow$ shorter bond.', 'c_mot', 3, 'JEE Mains Prep', 'approved'),
('B$_2$ is paramagnetic. This is explained by MOT because', 'B$_2$ is ionic', 'B$_2$ has unpaired $\sigma$ electrons', 'The two electrons in the $\pi_{2p}$ level occupy separate degenerate orbitals with parallel spins', 'VBT predicts paramagnetism', 'option3', 'Due to $s$-$p$ mixing, $\pi_{2p}$ fills before $\sigma_{2p}$ in B$_2$. Two electrons in degenerate $\pi_{2p}$ orbitals $\rightarrow$ 2 unpaired electrons.', 'c_mot', 3, 'JEE Mains Prep', 'approved'),
('The bond order of NO is', '$2$', '$2.5$', '$3$', '$1.5$', 'option2', 'NO has 15 electrons. BO $= (10 - 5)/2 = 2.5$. The extra electron (vs N$_2$) goes into $\pi^*_{2p}$.', 'c_mot', 3, 'JEE Mains Prep', 'approved'),
('CO is isoelectronic with N$_2$ (both have 14 electrons). The bond order of CO is', '$2$', '$2.5$', '$3$', '$1$', 'option3', 'CO has the same MO configuration as N$_2$: BO $= (10-4)/2 = 3$. CO has a triple bond.', 'c_mot', 3, 'JEE Mains Prep', 'approved'),
('The species with the highest bond dissociation energy among N$_2$, N$_2^+$, O$_2$, O$_2^+$ is', 'O$_2$', 'O$_2^+$', 'N$_2$', 'N$_2^+$', 'option3', 'Bond orders: N$_2$ (3) $>$ N$_2^+$ (2.5) $>$ O$_2^+$ (2.5) $>$ O$_2$ (2). N$_2$ has the highest BO and strongest bond ($945\;\text{kJ/mol}$).', 'c_mot', 3, 'JEE Mains Prep', 'approved'),
('The magnetic behaviour of O$_2$ (paramagnetic) is a triumph of MOT because', 'MOT is always correct', 'VBT also predicts paramagnetism', 'Lewis structures show unpaired electrons', 'VBT and Lewis structures predict O$_2$ to be diamagnetic, which is experimentally wrong', 'option4', 'The Lewis structure of O$_2$ (O=O) shows all electrons paired (diamagnetic). MOT correctly predicts 2 unpaired electrons in $\pi^*$ orbitals.', 'c_mot', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_mo_config_bond_order (7 easy, 7 medium, 7 hard = 21)
-- MO configurations of homonuclear diatomics, bond order, length, energy
-- ============================================================
('The MO electronic configuration of H$_2$ is', '$\sigma_{1s}^1$', '$\sigma_{1s}^2$', '$\sigma_{1s}^2 \sigma^*_{1s}^2$', '$\sigma_{1s}^1 \sigma^*_{1s}^1$', 'option2', 'H$_2$ has 2 electrons: both fill the bonding $\sigma_{1s}$ orbital. BO $= (2-0)/2 = 1$.', 'c_mo_config_bond_order', 1, 'JEE Mains Prep', 'approved'),
('The bond order of H$_2^+$ is', '$0$', '$0.5$', '$1$', '$1.5$', 'option2', 'H$_2^+$: 1 electron in $\sigma_{1s}$. BO $= (1-0)/2 = 0.5$.', 'c_mo_config_bond_order', 1, 'JEE Mains Prep', 'approved'),
('Li$_2$ exists as a stable molecule with bond order', '$0$', '$1$', '$2$', '$0.5$', 'option2', 'Li$_2$: $\sigma_{1s}^2 \sigma^*_{1s}^2 \sigma_{2s}^2$. BO $= (4-2)/2 = 1$.', 'c_mo_config_bond_order', 1, 'JEE Mains Prep', 'approved'),
('Be$_2$ does not exist because its bond order is', '$1$', '$0.5$', '$0$', '$2$', 'option3', 'Be$_2$: $\sigma_{1s}^2 \sigma^*_{1s}^2 \sigma_{2s}^2 \sigma^*_{2s}^2$. BO $= (4-4)/2 = 0$.', 'c_mo_config_bond_order', 1, 'JEE Mains Prep', 'approved'),
('Higher bond order corresponds to', 'Longer bond and weaker bond', 'Shorter bond and stronger bond', 'No change in bond properties', 'Weaker bond only', 'option2', 'Higher BO $\rightarrow$ more bonding electrons $\rightarrow$ stronger attraction $\rightarrow$ shorter and stronger bond.', 'c_mo_config_bond_order', 1, 'JEE Mains Prep', 'approved'),
('The total number of electrons in the MO diagram of N$_2$ is', '$10$', '$12$', '$14$', '$16$', 'option3', 'N has 7 electrons. N$_2$ has $7 + 7 = 14$ electrons.', 'c_mo_config_bond_order', 1, 'JEE Mains Prep', 'approved'),
('F$_2$ has bond order', '$0$', '$1$', '$2$', '$3$', 'option2', 'F$_2$ (18 electrons): BO $= (10-8)/2 = 1$. Single bond, consistent with Lewis structure.', 'c_mo_config_bond_order', 1, 'JEE Mains Prep', 'approved'),
('The MO configuration of C$_2$ is $\sigma_{1s}^2 \sigma^*_{1s}^2 \sigma_{2s}^2 \sigma^*_{2s}^2 \pi_{2p}^4$. The bond order is', '$1$', '$2$', '$3$', '$0$', 'option2', 'BO $= (8-4)/2 = 2$. C$_2$ has a double bond (both $\pi$ bonds, no $\sigma_{2p}$ bond due to $s$-$p$ mixing).', 'c_mo_config_bond_order', 2, 'JEE Mains Prep', 'approved'),
('C$_2$ is predicted to be', 'Paramagnetic', 'Diamagnetic', 'Ferromagnetic', 'Non-magnetic', 'option2', 'C$_2$: $\pi_{2p}^4$ — all electrons are paired. C$_2$ is diamagnetic.', 'c_mo_config_bond_order', 2, 'JEE Mains Prep', 'approved'),
('The correct order of bond dissociation energy is', 'F$_2 >$ O$_2 >$ N$_2$', 'N$_2 >$ O$_2 >$ F$_2$', 'O$_2 >$ N$_2 >$ F$_2$', 'N$_2 >$ F$_2 >$ O$_2$', 'option2', 'Bond orders: N$_2$ (3) $>$ O$_2$ (2) $>$ F$_2$ (1). BDE follows the same order.', 'c_mo_config_bond_order', 2, 'JEE Mains Prep', 'approved'),
('The correct order of bond length is', 'O$_2 <$ N$_2 <$ F$_2$', 'F$_2 <$ O$_2 <$ N$_2$', 'N$_2 <$ F$_2 <$ O$_2$', 'N$_2 <$ O$_2 <$ F$_2$', 'option4', 'Higher BO $\rightarrow$ shorter bond. N$_2$ (BO 3) $<$ O$_2$ (BO 2) $<$ F$_2$ (BO 1).', 'c_mo_config_bond_order', 2, 'JEE Mains Prep', 'approved'),
('Ne$_2$ does not exist because', 'Ne is too heavy', 'BO $= 0$ (equal bonding and antibonding electrons)', 'Ne has no electrons', 'Ne is radioactive', 'option2', 'Ne$_2$ (20 electrons): BO $= (10-10)/2 = 0$. No net bonding.', 'c_mo_config_bond_order', 2, 'JEE Mains Prep', 'approved'),
('The number of unpaired electrons in O$_2$ according to MOT is', '$0$', '$1$', '$2$', '$4$', 'option3', 'O$_2$: two electrons in degenerate $\pi^*_{2p}$ orbitals occupy them singly (Hund''s rule). 2 unpaired electrons.', 'c_mo_config_bond_order', 2, 'JEE Mains Prep', 'approved'),
('When N$_2$ loses an electron to form N$_2^+$, the bond order', 'Increases', 'Decreases from 3 to 2.5', 'Remains the same', 'Becomes zero', 'option2', 'N$_2^+$: loses one bonding electron. BO $= (9-4)/2 = 2.5$. Bond weakens and lengthens.', 'c_mo_config_bond_order', 2, 'JEE Mains Prep', 'approved'),
('When O$_2$ loses an electron to form O$_2^+$, the bond order', 'Decreases', 'Increases from 2 to 2.5', 'Remains the same', 'Becomes zero', 'option2', 'O$_2^+$: loses one antibonding $\pi^*$ electron. BO $= (10-5)/2 = 2.5$. Bond strengthens and shortens.', 'c_mo_config_bond_order', 3, 'JEE Mains Prep', 'approved'),
('The peroxide ion O$_2^{2-}$ has bond order', '$0$', '$1$', '$1.5$', '$2$', 'option2', 'O$_2^{2-}$: 18 electrons. BO $= (10-8)/2 = 1$. Single bond, consistent with the Lewis structure $[{:}\text{O}-\text{O}{:}]^{2-}$.', 'c_mo_config_bond_order', 3, 'JEE Mains Prep', 'approved'),
('Among N$_2$, CO, and NO$^+$, which are isoelectronic (14 electrons each)?', 'Only N$_2$ and CO', 'All three', 'Only CO and NO$^+$', 'None are isoelectronic', 'option2', 'N$_2$: 14e, CO: 14e, NO$^+$: 14e. All three are isoelectronic with BO $= 3$.', 'c_mo_config_bond_order', 3, 'JEE Mains Prep', 'approved'),
('The species with the weakest bond among O$_2$, O$_2^+$, O$_2^-$, O$_2^{2-}$ is', 'O$_2$', 'O$_2^+$', 'O$_2^-$', 'O$_2^{2-}$', 'option4', 'Bond orders: O$_2^+$ (2.5) $>$ O$_2$ (2) $>$ O$_2^-$ (1.5) $>$ O$_2^{2-}$ (1). Lowest BO $=$ weakest bond.', 'c_mo_config_bond_order', 3, 'JEE Mains Prep', 'approved'),
('The MO theory predicts that B$_2$ has a bond order of $1$ and is paramagnetic. The number of unpaired electrons is', '$0$', '$1$', '$2$', '$4$', 'option3', 'B$_2$ (10 electrons): $\pi_{2p}^2$ (due to $s$-$p$ mixing). Two electrons in degenerate $\pi$ orbitals $\rightarrow$ 2 unpaired.', 'c_mo_config_bond_order', 3, 'JEE Mains Prep', 'approved'),
('The bond order of CN$^-$ is', '$2$', '$2.5$', '$3$', '$3.5$', 'option3', 'CN$^-$: 14 electrons (isoelectronic with N$_2$ and CO). BO $= (10-4)/2 = 3$.', 'c_mo_config_bond_order', 3, 'JEE Mains Prep', 'approved'),
('Among H$_2$, He$_2$, Li$_2$, Be$_2$, the species that do NOT exist are', 'H$_2$ and Li$_2$', 'He$_2$ and Be$_2$', 'Li$_2$ and Be$_2$', 'H$_2$ and He$_2$', 'option2', 'He$_2$ (BO $= 0$) and Be$_2$ (BO $= 0$) do not exist. H$_2$ (BO $= 1$) and Li$_2$ (BO $= 1$) are stable.', 'c_mo_config_bond_order', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_metallic_hydrogen_bonding (7 easy, 7 medium, 7 hard = 21)
-- Metallic bonding, hydrogen bonding and applications
-- ============================================================
('Metallic bonding involves', 'Transfer of electrons', 'Sharing of electron pairs', 'A ''sea'' of delocalized electrons shared by all metal atoms', 'Hydrogen bonds', 'option3', 'In metals, valence electrons are delocalized over the entire lattice, forming an ''electron sea'' that holds the positive metal ions together.', 'c_metallic_hydrogen_bonding', 1, 'JEE Mains Prep', 'approved'),
('Hydrogen bonding occurs between', 'Any two hydrogen atoms', 'A hydrogen atom bonded to F, O, or N and a lone pair on another F, O, or N', 'Any two molecules', 'Only in water', 'option2', 'H-bonding requires H bonded to a highly electronegative atom (F, O, N) interacting with a lone pair on another such atom.', 'c_metallic_hydrogen_bonding', 1, 'JEE Mains Prep', 'approved'),
('Metals are good conductors of electricity because', 'They have ionic bonds', 'Delocalized electrons can move freely through the lattice', 'They have covalent bonds', 'They are transparent', 'option2', 'The mobile electron sea allows charge to flow easily when a potential difference is applied.', 'c_metallic_hydrogen_bonding', 1, 'JEE Mains Prep', 'approved'),
('The unusually high boiling point of water compared to H$_2$S is due to', 'Covalent bonding', 'Hydrogen bonding in water', 'Metallic bonding', 'Van der Waals forces', 'option2', 'Water has extensive H-bonding (2 H-bond donors, 2 acceptors per molecule). H$_2$S cannot form H-bonds (S is not electronegative enough).', 'c_metallic_hydrogen_bonding', 1, 'JEE Mains Prep', 'approved'),
('Metals are malleable and ductile because', 'The electron sea allows layers of atoms to slide over each other without breaking bonds', 'They have weak bonds', 'They are soft', 'They have directional bonds', 'option1', 'Non-directional metallic bonding allows deformation without fracture — layers slide while maintaining the electron sea.', 'c_metallic_hydrogen_bonding', 1, 'JEE Mains Prep', 'approved'),
('Which of the following exhibits hydrogen bonding?', 'CH$_4$', 'HF', 'H$_2$S', 'PH$_3$', 'option2', 'HF: H bonded to F (highly electronegative). CH$_4$, H$_2$S, PH$_3$ do not have H bonded to F, O, or N.', 'c_metallic_hydrogen_bonding', 1, 'JEE Mains Prep', 'approved'),
('Metals have a lustrous appearance because', 'They are transparent', 'Delocalized electrons absorb and re-emit light at all visible wavelengths', 'They have ionic bonds', 'They reflect UV light only', 'option2', 'Free electrons absorb photons and re-emit them, giving metals their characteristic lustre.', 'c_metallic_hydrogen_bonding', 1, 'JEE Mains Prep', 'approved'),
('The strength of metallic bonding increases with', 'Increasing atomic radius', 'Decreasing number of valence electrons', 'Increasing number of valence electrons and decreasing atomic radius', 'Decreasing nuclear charge', 'option3', 'More valence electrons $\rightarrow$ denser electron sea. Smaller radius $\rightarrow$ stronger attraction. Example: W, Mo have very strong metallic bonds.', 'c_metallic_hydrogen_bonding', 2, 'JEE Mains Prep', 'approved'),
('Intramolecular hydrogen bonding occurs in', '$p$-nitrophenol', '$o$-nitrophenol', 'Ethanol', 'Water', 'option2', '$o$-nitrophenol has the OH and NO$_2$ groups close enough for intramolecular H-bonding. $p$-nitrophenol has intermolecular H-bonding.', 'c_metallic_hydrogen_bonding', 2, 'JEE Mains Prep', 'approved'),
('The boiling point order H$_2$O $>$ HF $>$ NH$_3$ is because', 'Water has the most extensive H-bonding network (each molecule can form 4 H-bonds)', 'HF has the strongest individual H-bond', 'NH$_3$ has no H-bonding', 'All have the same boiling point', 'option1', 'Water: 4 H-bonds per molecule (2 donors, 2 acceptors). HF: 2 per molecule. NH$_3$: limited by having only 1 lone pair.', 'c_metallic_hydrogen_bonding', 2, 'JEE Mains Prep', 'approved'),
('The density of ice is less than liquid water because', 'H-bonding in ice creates an open, cage-like crystal structure with empty spaces', 'Ice has weaker bonds', 'Water molecules are heavier in liquid form', 'Ice has no H-bonding', 'option1', 'In ice, each water molecule is tetrahedrally H-bonded to 4 neighbours, creating a spacious hexagonal lattice.', 'c_metallic_hydrogen_bonding', 2, 'JEE Mains Prep', 'approved'),
('Among Na, Mg, and Al, the metallic bond strength order is', 'Na $>$ Mg $>$ Al', 'Al $>$ Mg $>$ Na', 'Mg $>$ Al $>$ Na', 'All are equal', 'option2', 'Al: 3 valence electrons, smallest radius. Mg: 2 valence electrons. Na: 1 valence electron, largest radius. More electrons + smaller size $=$ stronger bonding.', 'c_metallic_hydrogen_bonding', 2, 'JEE Mains Prep', 'approved'),
('The band theory of metals explains electrical conductivity by', 'Ionic conduction', 'Overlapping of atomic orbitals forming continuous energy bands with partially filled states', 'Covalent bond breaking', 'Proton transfer', 'option2', 'In metals, the valence band and conduction band overlap (or the valence band is partially filled), allowing electron flow.', 'c_metallic_hydrogen_bonding', 2, 'JEE Mains Prep', 'approved'),
('$o$-nitrophenol has a lower boiling point than $p$-nitrophenol because', '$o$-nitrophenol has intramolecular H-bonding (reducing intermolecular H-bonding)', '$p$-nitrophenol has intramolecular H-bonding', '$o$-nitrophenol is lighter', 'They have the same boiling point', 'option1', 'Intramolecular H-bonding in $o$-nitrophenol satisfies the H-bond internally, reducing intermolecular association and lowering the boiling point.', 'c_metallic_hydrogen_bonding', 2, 'JEE Mains Prep', 'approved'),
('The H-bond energy is typically in the range', '$5$-$40\;\text{kJ/mol}$', '$100$-$400\;\text{kJ/mol}$', '$0.1$-$1\;\text{kJ/mol}$', '$500$-$1000\;\text{kJ/mol}$', 'option1', 'H-bonds are much weaker than covalent bonds ($150$-$400\;\text{kJ/mol}$) but stronger than van der Waals forces ($0.1$-$10\;\text{kJ/mol}$).', 'c_metallic_hydrogen_bonding', 3, 'JEE Mains Prep', 'approved'),
('The high specific heat capacity of water is due to', 'Covalent O-H bonds', 'Extensive hydrogen bonding requiring significant energy to disrupt', 'Low molecular mass', 'Metallic character', 'option2', 'Breaking H-bonds absorbs energy without raising temperature much, giving water its high specific heat ($4.18\;\text{J/g}\cdot\text{K}$).', 'c_metallic_hydrogen_bonding', 3, 'JEE Mains Prep', 'approved'),
('In the electron sea model, the cohesive energy of a metal depends on', 'The number of valence electrons, atomic radius, and crystal structure', 'Only the atomic number', 'Only the crystal structure', 'The colour of the metal', 'option1', 'Cohesive energy increases with more valence electrons (stronger electron sea), smaller radius (closer packing), and efficient crystal structures (FCC, HCP).', 'c_metallic_hydrogen_bonding', 3, 'JEE Mains Prep', 'approved'),
('DNA''s double helix structure is stabilized primarily by', 'Metallic bonding', 'Covalent bonds between bases', 'Hydrogen bonds between complementary base pairs', 'Ionic bonds', 'option3', 'A-T pairs have 2 H-bonds; G-C pairs have 3 H-bonds. These hold the two strands together.', 'c_metallic_hydrogen_bonding', 3, 'JEE Mains Prep', 'approved'),
('Among HF, HCl, HBr, HI, the boiling points follow the order', 'All are equal', 'HI $>$ HBr $>$ HCl $>$ HF', 'HF $>$ HCl $>$ HBr $>$ HI', 'HF $\gg$ HI $>$ HBr $>$ HCl', 'option4', 'HF has anomalously high bp due to H-bonding. For HCl, HBr, HI: bp increases with molecular mass (London forces). So HF $\gg$ HI $>$ HBr $>$ HCl.', 'c_metallic_hydrogen_bonding', 3, 'JEE Mains Prep', 'approved'),
('Transition metals generally have higher melting points than $s$-block metals because', 'They are non-metals', 'They are lighter', 'They have fewer electrons', 'They have more valence electrons (including $d$ electrons) contributing to metallic bonding', 'option4', 'Transition metals contribute both $s$ and $d$ electrons to the electron sea, resulting in stronger metallic bonds and higher melting points.', 'c_metallic_hydrogen_bonding', 3, 'JEE Mains Prep', 'approved'),
('The viscosity of glycerol is very high compared to ethanol because', 'Glycerol has 3 OH groups forming an extensive H-bonding network', 'Glycerol is ionic', 'Ethanol has stronger H-bonds', 'Glycerol has metallic bonds', 'option1', 'Glycerol (3 OH groups) forms many more intermolecular H-bonds than ethanol (1 OH), creating a viscous, syrupy liquid.', 'c_metallic_hydrogen_bonding', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_thermo_fundamentals (7 easy, 7 medium, 7 hard = 21)
-- System/surroundings, properties, state functions, processes
-- ============================================================
('A thermodynamic system is', 'Only the surroundings', 'The entire universe', 'The part of the universe under study', 'A vacuum', 'option3', 'The system is the specific part being studied. Everything else is the surroundings. System + surroundings = universe.', 'c_thermo_fundamentals', 1, 'JEE Mains Prep', 'approved'),
('An isolated system exchanges', 'Both energy and matter with surroundings', 'Energy but not matter', 'Neither energy nor matter', 'Only matter', 'option3', 'Isolated: no exchange. Closed: energy exchange only. Open: both energy and matter exchange.', 'c_thermo_fundamentals', 1, 'JEE Mains Prep', 'approved'),
('An extensive property depends on', 'The amount of substance in the system', 'Only temperature', 'Only pressure', 'Nothing', 'option1', 'Extensive: depends on quantity (mass, volume, enthalpy, entropy). Intensive: independent of quantity (T, P, density, molar quantities).', 'c_thermo_fundamentals', 1, 'JEE Mains Prep', 'approved'),
('Which of the following is an intensive property?', 'Volume', 'Mass', 'Temperature', 'Enthalpy', 'option3', 'Temperature does not change when the system is divided. Volume, mass, and enthalpy are extensive.', 'c_thermo_fundamentals', 1, 'JEE Mains Prep', 'approved'),
('A state function depends on', 'The path taken between two states', 'Only the initial and final states of the system', 'The rate of the process', 'The time taken', 'option2', 'State functions ($U$, $H$, $S$, $G$, $T$, $P$, $V$) depend only on the current state, not the path. Work and heat are NOT state functions.', 'c_thermo_fundamentals', 1, 'JEE Mains Prep', 'approved'),
('An isothermal process occurs at constant', 'Pressure', 'Volume', 'Temperature', 'Entropy', 'option3', 'Isothermal: $T = $ constant. Isobaric: $P = $ constant. Isochoric: $V = $ constant. Adiabatic: $q = 0$.', 'c_thermo_fundamentals', 1, 'JEE Mains Prep', 'approved'),
('In an adiabatic process', 'No heat is exchanged with the surroundings ($q = 0$)', 'Temperature is constant', 'Pressure is constant', 'Volume is constant', 'option1', 'Adiabatic: $q = 0$. Any energy change comes from work done on or by the system.', 'c_thermo_fundamentals', 1, 'JEE Mains Prep', 'approved'),
('Which of the following is NOT a state function?', 'Internal energy ($U$)', 'Enthalpy ($H$)', 'Work ($w$)', 'Entropy ($S$)', 'option3', 'Work and heat are path functions — their values depend on how the process is carried out.', 'c_thermo_fundamentals', 2, 'JEE Mains Prep', 'approved'),
('For an ideal gas undergoing isothermal expansion, $\Delta U$ is', 'Positive', 'Negative', 'Zero', 'Cannot be determined', 'option3', 'For an ideal gas, $U$ depends only on $T$. At constant $T$: $\Delta U = 0$.', 'c_thermo_fundamentals', 2, 'JEE Mains Prep', 'approved'),
('The sign convention in thermodynamics: work done BY the system is', 'Always negative', 'Positive (IUPAC convention: $w = -P_{ext}\Delta V$)', 'Zero', 'Undefined', 'option2', 'IUPAC: $w$ done by system is negative ($w = -P_{ext}\Delta V$ for expansion). Some textbooks use the opposite convention. In expansion, $\Delta V > 0$, $w < 0$ (system loses energy as work).', 'c_thermo_fundamentals', 2, 'JEE Mains Prep', 'approved'),
('A cyclic process returns the system to its initial state. For a cyclic process', '$q = 0$', '$\Delta U > 0$', '$\Delta U = 0$ and $q = -w$', '$w = 0$', 'option3', 'Since $U$ is a state function: $\Delta U_{cycle} = 0$. From the first law: $0 = q + w$, so $q = -w$.', 'c_thermo_fundamentals', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy $H$ is defined as', '$H = U - PV$', '$H = U + PV$', '$H = U/PV$', '$H = PV - U$', 'option2', '$H = U + PV$. At constant pressure: $\Delta H = q_P$ (heat exchanged at constant pressure).', 'c_thermo_fundamentals', 2, 'JEE Mains Prep', 'approved'),
('For an ideal gas, $\Delta H$ and $\Delta U$ are related by', '$\Delta H = \Delta U - \Delta n_g RT$', '$\Delta H = \Delta U + \Delta n_g RT$', '$\Delta H = \Delta U$', '$\Delta H = \Delta U + PV$', 'option2', '$\Delta H = \Delta U + \Delta(PV) = \Delta U + \Delta n_g RT$ where $\Delta n_g$ = change in moles of gas.', 'c_thermo_fundamentals', 2, 'JEE Mains Prep', 'approved'),
('The relationship between $C_P$ and $C_V$ for an ideal gas is', '$C_P - C_V = R$', '$C_P + C_V = R$', '$C_P/C_V = R$', '$C_P - C_V = 2R$', 'option1', '$C_P - C_V = R = 8.314\;\text{J/(mol}\cdot\text{K)}$. This is Mayer''s relation.', 'c_thermo_fundamentals', 2, 'JEE Mains Prep', 'approved'),
('For a reversible isothermal expansion of an ideal gas from $V_1$ to $V_2$, the work done is', '$w = 0$', '$w = nRT\ln(V_2/V_1)$', '$w = -P(V_2 - V_1)$', '$w = -nRT\ln(V_2/V_1)$', 'option4', '$w = -\int P\,dV = -nRT\int dV/V = -nRT\ln(V_2/V_1)$. Negative for expansion (work done by system).', 'c_thermo_fundamentals', 3, 'JEE Mains Prep', 'approved'),
('The work done in an irreversible expansion against constant external pressure $P_{ext}$ is', '$w = P_{ext}/\Delta V$', '$w = -nRT\ln(V_2/V_1)$', '$w = 0$', '$w = -P_{ext}\Delta V$', 'option4', 'Irreversible: $w = -P_{ext}(V_2 - V_1)$. This is always less (in magnitude) than reversible work.', 'c_thermo_fundamentals', 3, 'JEE Mains Prep', 'approved'),
('For free expansion of an ideal gas into vacuum', '$w = 0$, $q = 0$, $\Delta U = 0$, $\Delta T = 0$', '$w > 0$', '$\Delta T > 0$', '$q > 0$', 'option1', 'Free expansion: $P_{ext} = 0$, so $w = 0$. Adiabatic container: $q = 0$. First law: $\Delta U = 0$. For ideal gas: $\Delta T = 0$.', 'c_thermo_fundamentals', 3, 'JEE Mains Prep', 'approved'),
('$2\;\text{mol}$ of an ideal gas expands isothermally and reversibly at $300\;\text{K}$ from $10\;\text{L}$ to $20\;\text{L}$. The work done is ($R = 8.314\;\text{J/mol}\cdot\text{K}$)', '$-3.46\;\text{kJ}$', '$+3.46\;\text{kJ}$', '$-6.92\;\text{kJ}$', '$0$', 'option1', '$w = -nRT\ln(V_2/V_1) = -2 \times 8.314 \times 300 \times \ln 2 = -2 \times 8.314 \times 300 \times 0.693 = -3457\;\text{J} \approx -3.46\;\text{kJ}$.', 'c_thermo_fundamentals', 3, 'JEE Mains Prep', 'approved'),
('For an adiabatic process involving an ideal gas, $TV^{\gamma-1} = $ constant. If $\gamma = 5/3$ and the gas expands to double its volume, the temperature ratio $T_2/T_1$ is', '$2^{-2/3}$', '$2^{2/3}$', '$1/2$', '$2$', 'option1', '$T_1 V_1^{\gamma-1} = T_2 V_2^{\gamma-1}$. $T_2/T_1 = (V_1/V_2)^{\gamma-1} = (1/2)^{2/3} = 2^{-2/3}$.', 'c_thermo_fundamentals', 3, 'JEE Mains Prep', 'approved'),
('The maximum work is obtained from a process when it is carried out', 'Reversibly', 'Irreversibly', 'Adiabatically', 'At constant volume', 'option1', 'Reversible processes give maximum work because the system is always infinitesimally close to equilibrium.', 'c_thermo_fundamentals', 3, 'JEE Mains Prep', 'approved'),
('For a reaction at constant volume, the heat exchanged equals', '$\Delta U$', '$\Delta H$', '$\Delta G$', '$\Delta S$', 'option1', 'At constant $V$: $q_V = \Delta U$. At constant $P$: $q_P = \Delta H$.', 'c_thermo_fundamentals', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_first_law_hess (7 easy, 7 medium, 7 hard = 21)
-- First law, work, heat, internal energy, enthalpy, Hess''s law
-- ============================================================
('The first law of thermodynamics states that', 'Energy can be created but not destroyed', 'Energy of an isolated system is constant ($\Delta U = q + w$)', 'Entropy always increases', 'Heat flows from cold to hot', 'option2', 'First law: $\Delta U = q + w$. Energy is conserved — it can be converted between forms but not created or destroyed.', 'c_first_law_hess', 1, 'JEE Mains Prep', 'approved'),
('Hess''s law states that', 'The enthalpy change of a reaction depends on the path', 'The total enthalpy change is the same regardless of the route taken (if initial and final states are the same)', 'Entropy is always positive', 'All reactions are exothermic', 'option2', 'Hess''s law: $\Delta H$ is a state function, so the overall $\Delta H$ is the sum of $\Delta H$ values for individual steps.', 'c_first_law_hess', 1, 'JEE Mains Prep', 'approved'),
('An exothermic reaction has', '$\Delta H > 0$', '$\Delta H < 0$', '$\Delta H = 0$', '$\Delta S < 0$', 'option2', 'Exothermic: heat is released to surroundings. $\Delta H < 0$ (negative).', 'c_first_law_hess', 1, 'JEE Mains Prep', 'approved'),
('An endothermic reaction has', '$\Delta H < 0$', '$\Delta H > 0$', '$\Delta H = 0$', '$\Delta G > 0$', 'option2', 'Endothermic: heat is absorbed from surroundings. $\Delta H > 0$ (positive).', 'c_first_law_hess', 1, 'JEE Mains Prep', 'approved'),
('The heat capacity at constant pressure ($C_P$) is defined as', '$(\partial G/\partial T)_P$', '$(\partial U/\partial T)_V$', '$(\partial H/\partial T)_P$', '$(\partial S/\partial T)_P$', 'option3', '$C_P = (\partial H/\partial T)_P = q_P/\Delta T$. Similarly, $C_V = (\partial U/\partial T)_V$.', 'c_first_law_hess', 1, 'JEE Mains Prep', 'approved'),
('For an ideal gas at constant pressure, $q_P$ equals', '$\Delta U$', '$\Delta H$', '$w$', '$\Delta G$', 'option2', 'At constant pressure: $q_P = \Delta H$. This is why enthalpy is so useful in chemistry.', 'c_first_law_hess', 1, 'JEE Mains Prep', 'approved'),
('If a reaction can be expressed as the sum of two other reactions, then its $\Delta H$ is', 'The product of the individual $\Delta H$ values', 'The sum of the individual $\Delta H$ values', 'Zero', 'Undefined', 'option2', 'Hess''s law: $\Delta H_{overall} = \Delta H_1 + \Delta H_2 + ...$', 'c_first_law_hess', 1, 'JEE Mains Prep', 'approved'),
('Given: C(s) + O$_2$(g) $\to$ CO$_2$(g), $\Delta H = -393\;\text{kJ}$ and CO(g) + $\frac{1}{2}$O$_2$(g) $\to$ CO$_2$(g), $\Delta H = -283\;\text{kJ}$. The $\Delta H$ for C(s) + $\frac{1}{2}$O$_2$(g) $\to$ CO(g) is', '$+110\;\text{kJ}$', '$-676\;\text{kJ}$', '$-110\;\text{kJ}$', '$-283\;\text{kJ}$', 'option3', 'By Hess''s law: $\Delta H = -393 - (-283) = -393 + 283 = -110\;\text{kJ}$.', 'c_first_law_hess', 2, 'JEE Mains Prep', 'approved'),
('The standard enthalpy of formation ($\Delta_f H^\circ$) of an element in its standard state is', '$-1\;\text{kJ/mol}$', 'Zero', 'Positive', 'Negative', 'option2', 'By convention, $\Delta_f H^\circ$ of elements in their standard states (e.g., O$_2$(g), C(graphite), Fe(s)) is zero.', 'c_first_law_hess', 2, 'JEE Mains Prep', 'approved'),
('The standard enthalpy of reaction can be calculated from standard enthalpies of formation as', '$\Delta_r H^\circ = \sum \Delta_f H^\circ(\text{products}) - \sum \Delta_f H^\circ(\text{reactants})$', '$\Delta_r H^\circ = \sum \Delta_f H^\circ(\text{reactants}) - \sum \Delta_f H^\circ(\text{products})$', '$\Delta_r H^\circ = \sum \Delta_f H^\circ(\text{products}) + \sum \Delta_f H^\circ(\text{reactants})$', '$\Delta_r H^\circ = \sum \Delta_f H^\circ(\text{products}) \times \sum \Delta_f H^\circ(\text{reactants})$', 'option1', '$\Delta_r H^\circ = \sum n_p \Delta_f H^\circ_p - \sum n_r \Delta_f H^\circ_r$ (products minus reactants).', 'c_first_law_hess', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy of combustion of methane is $-890\;\text{kJ/mol}$. The heat released when $8\;\text{g}$ of CH$_4$ ($M = 16$) is burned is', '$890\;\text{kJ}$', '$445\;\text{kJ}$', '$1780\;\text{kJ}$', '$222.5\;\text{kJ}$', 'option2', '$n = 8/16 = 0.5\;\text{mol}$. Heat $= 0.5 \times 890 = 445\;\text{kJ}$.', 'c_first_law_hess', 2, 'JEE Mains Prep', 'approved'),
('Kirchhoff''s equation relates the variation of $\Delta H$ with temperature as', '$\Delta H_2 = \Delta H_1 + \Delta C_P(T_2 - T_1)$', '$\Delta H_2 = \Delta H_1 \times T_2/T_1$', '$\Delta H_2 = \Delta H_1 - \Delta C_P(T_2 - T_1)$', '$\Delta H$ does not change with temperature', 'option1', '$d(\Delta H)/dT = \Delta C_P$. Integrating: $\Delta H(T_2) = \Delta H(T_1) + \Delta C_P(T_2 - T_1)$.', 'c_first_law_hess', 2, 'JEE Mains Prep', 'approved'),
('For the reaction N$_2$(g) + 3H$_2$(g) $\to$ 2NH$_3$(g), $\Delta H = -92\;\text{kJ}$. The $\Delta U$ at $298\;\text{K}$ is ($R = 8.314\;\text{J/mol}\cdot\text{K}$)', '$-92\;\text{kJ}$', '$-97\;\text{kJ}$', '$-87\;\text{kJ}$', '$-82\;\text{kJ}$', 'option3', '$\Delta n_g = 2 - (1+3) = -2$. $\Delta H = \Delta U + \Delta n_g RT$. $-92 = \Delta U + (-2)(8.314 \times 10^{-3})(298)$. $-92 = \Delta U - 4.95$. $\Delta U = -87.05\;\text{kJ}$.', 'c_first_law_hess', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy of neutralization of a strong acid with a strong base is approximately', '$-100\;\text{kJ/mol}$', '$+57.1\;\text{kJ/mol}$', '$-13.7\;\text{kJ/mol}$', '$-57.1\;\text{kJ/mol}$', 'option4', 'Strong acid + strong base: H$^+$(aq) + OH$^-$(aq) $\to$ H$_2$O(l). $\Delta H \approx -57.1\;\text{kJ/mol}$ (constant, since both are fully ionized).', 'c_first_law_hess', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy of reaction can also be calculated from bond enthalpies as', '$\Delta H = \sum(\text{bonds broken}) - \sum(\text{bonds formed})$', '$\Delta H = \sum(\text{bonds formed}) - \sum(\text{bonds broken})$', '$\Delta H = \sum(\text{bonds broken}) + \sum(\text{bonds formed})$', '$\Delta H = \sum(\text{bonds broken}) \times \sum(\text{bonds formed})$', 'option1', 'Breaking bonds requires energy (positive). Forming bonds releases energy (negative). $\Delta H = \text{energy in} - \text{energy out}$.', 'c_first_law_hess', 3, 'JEE Mains Prep', 'approved'),
('The C-H bond enthalpy in methane is $416\;\text{kJ/mol}$. The enthalpy of atomization of CH$_4$ is', '$416\;\text{kJ}$', '$832\;\text{kJ}$', '$1664\;\text{kJ}$', '$208\;\text{kJ}$', 'option3', 'CH$_4$ has 4 C-H bonds. Atomization breaks all bonds: $\Delta H_{atom} = 4 \times 416 = 1664\;\text{kJ/mol}$.', 'c_first_law_hess', 3, 'JEE Mains Prep', 'approved'),
('The enthalpy of neutralization of a weak acid (e.g., CH$_3$COOH) with NaOH is less than $57.1\;\text{kJ/mol}$ because', 'Part of the energy is used to ionize the weak acid', 'Weak acids release more heat', 'NaOH is not fully ionized', 'The reaction does not occur', 'option1', 'Weak acid is not fully ionized. Some energy goes into ionizing it ($\Delta H_{ionization} > 0$), reducing the net heat released.', 'c_first_law_hess', 3, 'JEE Mains Prep', 'approved'),
('Using bond enthalpies: C-H $= 414$, C-C $= 347$, C=C $= 611$, H-H $= 436$, the $\Delta H$ for hydrogenation of ethene (C$_2$H$_4$ + H$_2 \to$ C$_2$H$_6$) is approximately', '$-62\;\text{kJ}$', '$+124\;\text{kJ}$', '$-250\;\text{kJ}$', '$-124\;\text{kJ}$', 'option4', 'Bonds broken: 1 C=C ($611$) + 1 H-H ($436$) $= 1047$. Bonds formed: 1 C-C ($347$) + 2 C-H ($2 \times 414 = 828$) $= 1175$. $\Delta H = 1047 - 1175 = -128 \approx -124\;\text{kJ}$.', 'c_first_law_hess', 3, 'JEE Mains Prep', 'approved'),
('The resonance energy of benzene can be estimated by comparing', 'The boiling points of benzene and cyclohexane', 'The experimental $\Delta H_{hydrogenation}$ of benzene with the calculated value for hypothetical cyclohexatriene', 'The molecular masses', 'The densities', 'option2', 'Calculated $\Delta H_{hyd}$ for 3 double bonds $\approx 3 \times (-120) = -360\;\text{kJ}$. Experimental $\approx -208\;\text{kJ}$. Resonance energy $\approx 152\;\text{kJ/mol}$.', 'c_first_law_hess', 3, 'JEE Mains Prep', 'approved'),
('The lattice enthalpy of NaCl calculated from the Born-Haber cycle is $788\;\text{kJ/mol}$. If the electron affinity of Cl were more negative (more exothermic), the lattice enthalpy would', 'Increase', 'Remain the same (lattice enthalpy is independent of EA)', 'Decrease', 'Become zero', 'option2', 'Lattice enthalpy is a property of the crystal structure and ionic charges/sizes. It does not change with EA. The Born-Haber cycle uses EA to calculate lattice enthalpy, but the lattice enthalpy itself is fixed.', 'c_first_law_hess', 3, 'JEE Mains Prep', 'approved'),
('For the reaction 2CO(g) + O$_2$(g) $\to$ 2CO$_2$(g), $\Delta H = -566\;\text{kJ}$. The $\Delta H$ for CO$_2$(g) $\to$ CO(g) + $\frac{1}{2}$O$_2$(g) is', '$-566\;\text{kJ}$', '$-283\;\text{kJ}$', '$+566\;\text{kJ}$', '$+283\;\text{kJ}$', 'option4', 'Reverse the reaction and halve it: $\Delta H = +566/2 = +283\;\text{kJ}$.', 'c_first_law_hess', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_enthalpies (7 easy, 7 medium, 7 hard = 21)
-- Various enthalpies: bond dissociation, combustion, formation, etc.
-- ============================================================
('The standard enthalpy of formation of a compound is the enthalpy change when', 'The compound is dissolved', 'The compound is decomposed', 'One mole of the compound is formed from its elements in their standard states', 'The compound is vaporized', 'option3', '$\Delta_f H^\circ$: formation of 1 mol from elements in standard states ($298\;\text{K}$, $1\;\text{bar}$).', 'c_enthalpies', 1, 'JEE Mains Prep', 'approved'),
('The enthalpy of combustion is always', 'Positive', 'Negative (exothermic)', 'Zero', 'Variable', 'option2', 'Combustion releases heat. $\Delta_{comb} H < 0$ always.', 'c_enthalpies', 1, 'JEE Mains Prep', 'approved'),
('Bond dissociation enthalpy is the energy required to', 'Form a bond', 'Break one mole of a specific bond in gaseous molecules', 'Ionize an atom', 'Melt a solid', 'option2', 'BDE: energy to homolytically break 1 mol of a specific bond: A-B(g) $\to$ A(g) + B(g). Always positive.', 'c_enthalpies', 1, 'JEE Mains Prep', 'approved'),
('The enthalpy of sublimation is the enthalpy change for', 'Solid $\to$ liquid', 'Liquid $\to$ gas', 'Gas $\to$ liquid', 'Solid $\to$ gas directly', 'option4', 'Sublimation: solid $\to$ gas. $\Delta_{sub}H = \Delta_{fus}H + \Delta_{vap}H$.', 'c_enthalpies', 1, 'JEE Mains Prep', 'approved'),
('The enthalpy of atomization of H$_2$(g) is', 'Zero', 'Half the bond dissociation enthalpy', 'Double the bond dissociation enthalpy', 'The same as the H-H bond dissociation enthalpy', 'option4', 'H$_2$(g) $\to$ 2H(g). This breaks one H-H bond. $\Delta_{atom}H = $ BDE(H-H) $= 436\;\text{kJ/mol}$.', 'c_enthalpies', 1, 'JEE Mains Prep', 'approved'),
('The enthalpy of solution is the enthalpy change when', 'Solvent evaporates', 'A solution is heated', 'A solution is frozen', 'One mole of solute dissolves in a large excess of solvent', 'option4', '$\Delta_{sol}H$ can be positive (endothermic, e.g., NH$_4$NO$_3$) or negative (exothermic, e.g., NaOH).', 'c_enthalpies', 1, 'JEE Mains Prep', 'approved'),
('The enthalpy of hydration is the enthalpy change when', 'Water is heated', 'Gaseous ions are surrounded by water molecules', 'Ice melts', 'Water evaporates', 'option2', '$\Delta_{hyd}H$: M$^{n+}$(g) $\to$ M$^{n+}$(aq). Always exothermic (negative). Smaller, more charged ions have more negative $\Delta_{hyd}H$.', 'c_enthalpies', 1, 'JEE Mains Prep', 'approved'),
('The enthalpy of solution of NaCl can be expressed as', '$\Delta_{sol}H = \Delta_{lattice}H - \Delta_{hyd}H$', '$\Delta_{sol}H = \Delta_{lattice}H + \Delta_{hyd}H$', '$\Delta_{sol}H = \Delta_{hyd}H - \Delta_{lattice}H$', '$\Delta_{sol}H = \Delta_{lattice}H \times \Delta_{hyd}H$', 'option2', 'Dissolution: break lattice (endothermic, $+$) then hydrate ions (exothermic, $-$). $\Delta_{sol}H = U_{lattice} + \Delta_{hyd}H$.', 'c_enthalpies', 2, 'JEE Mains Prep', 'approved'),
('The ionization enthalpy of Na is $496\;\text{kJ/mol}$. This means', '$496\;\text{kJ}$ is needed to remove one electron from 1 mol of gaseous Na atoms', 'Na releases $496\;\text{kJ}$ when ionized', 'Na gains an electron with $496\;\text{kJ}$', 'Na melts at $496\;\text{K}$', 'option1', 'IE: Na(g) $\to$ Na$^+$(g) + e$^-$. $\Delta H = +496\;\text{kJ/mol}$ (always endothermic).', 'c_enthalpies', 2, 'JEE Mains Prep', 'approved'),
('The electron gain enthalpy of Cl is $-349\;\text{kJ/mol}$. This means', 'Cl absorbs $349\;\text{kJ}$', 'Cl releases $349\;\text{kJ}$ when it gains an electron', 'Cl loses an electron', 'Cl is ionized', 'option2', 'Cl(g) + e$^-$ $\to$ Cl$^-$(g). $\Delta H = -349\;\text{kJ/mol}$ (exothermic — energy released).', 'c_enthalpies', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy of vaporization of water is $40.7\;\text{kJ/mol}$. The enthalpy of condensation is', '$+40.7\;\text{kJ/mol}$', '$-40.7\;\text{kJ/mol}$', '$0$', '$81.4\;\text{kJ/mol}$', 'option2', 'Condensation is the reverse of vaporization: $\Delta_{cond}H = -\Delta_{vap}H = -40.7\;\text{kJ/mol}$.', 'c_enthalpies', 2, 'JEE Mains Prep', 'approved'),
('The calorific value of a fuel is', 'The heat produced per gram (or per mole) of fuel on complete combustion', 'The melting point of the fuel', 'The density of the fuel', 'The boiling point of the fuel', 'option1', 'Higher calorific value means more energy per unit mass. H$_2$ has the highest ($142\;\text{kJ/g}$).', 'c_enthalpies', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy of formation of CO$_2$(g) is $-393.5\;\text{kJ/mol}$ and H$_2$O(l) is $-285.8\;\text{kJ/mol}$. The enthalpy of combustion of CH$_4$ (given $\Delta_f H^\circ$ of CH$_4$ $= -74.8\;\text{kJ/mol}$) is', '$-393.5\;\text{kJ/mol}$', '$+890.3\;\text{kJ/mol}$', '$-604.5\;\text{kJ/mol}$', '$-890.3\;\text{kJ/mol}$', 'option4', 'CH$_4$ + 2O$_2 \to$ CO$_2$ + 2H$_2$O. $\Delta H = [-393.5 + 2(-285.8)] - [-74.8 + 0] = -965.1 + 74.8 = -890.3\;\text{kJ}$.', 'c_enthalpies', 2, 'JEE Mains Prep', 'approved'),
('The mean bond enthalpy of C-H in methane is obtained by dividing the enthalpy of atomization of CH$_4$ by', '$2$', '$3$', '$4$', '$1$', 'option3', 'CH$_4$ has 4 C-H bonds. Mean BDE $= \Delta_{atom}H(\text{CH}_4)/4$. Note: individual C-H BDEs differ slightly.', 'c_enthalpies', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy of formation of HCl(g) is $-92.3\;\text{kJ/mol}$. The H-Cl bond dissociation enthalpy is approximately (given BDE of H$_2 = 436$, Cl$_2 = 242\;\text{kJ/mol}$)', '$184.6\;\text{kJ/mol}$', '$92.3\;\text{kJ/mol}$', '$339\;\text{kJ/mol}$', '$431\;\text{kJ/mol}$', 'option4', '$\frac{1}{2}$H$_2$ + $\frac{1}{2}$Cl$_2 \to$ HCl. $\Delta H = \frac{1}{2}(436) + \frac{1}{2}(242) - \text{BDE}(\text{HCl})$. $-92.3 = 218 + 121 - \text{BDE}$. BDE $= 339 + 92.3 = 431.3\;\text{kJ/mol}$.', 'c_enthalpies', 3, 'JEE Mains Prep', 'approved'),
('The second electron gain enthalpy of oxygen is positive because', 'O$^{2-}$ is more stable than O$^-$', 'Oxygen is too small', 'Oxygen has high electronegativity', 'Adding a second electron to the already negative O$^-$ ion requires energy to overcome repulsion', 'option4', 'O$^-$(g) + e$^-$ $\to$ O$^{2-}$(g). The incoming electron is repelled by the negative charge on O$^-$, making $\Delta H > 0$.', 'c_enthalpies', 3, 'JEE Mains Prep', 'approved'),
('The Born-Haber cycle for MgO involves which of the following steps?', 'Only combustion', 'Only sublimation and lattice enthalpy', 'Only ionization and electron affinity', 'Sublimation of Mg, 2 ionization energies of Mg, dissociation of O$_2$, 2 electron affinities of O, lattice enthalpy', 'option4', 'MgO involves Mg$^{2+}$ (2 IEs) and O$^{2-}$ (2 EAs, second is positive). All steps must be included.', 'c_enthalpies', 3, 'JEE Mains Prep', 'approved'),
('The enthalpy of dilution is the enthalpy change when', 'A gas condenses', 'A solid dissolves', 'A solution is diluted by adding more solvent', 'A liquid freezes', 'option3', '$\Delta_{dil}H$ is usually small for strong electrolytes but can be significant for concentrated solutions of H$_2$SO$_4$.', 'c_enthalpies', 3, 'JEE Mains Prep', 'approved'),
('The enthalpy of combustion of graphite is $-393.5\;\text{kJ/mol}$ and of diamond is $-395.4\;\text{kJ/mol}$. The enthalpy of transition C(graphite) $\to$ C(diamond) is', '$0$', '$-1.9\;\text{kJ/mol}$', '$+788.9\;\text{kJ/mol}$', '$+1.9\;\text{kJ/mol}$', 'option4', 'By Hess''s law: $\Delta H = -393.5 - (-395.4) = +1.9\;\text{kJ/mol}$. Diamond is slightly less stable than graphite.', 'c_enthalpies', 3, 'JEE Mains Prep', 'approved'),
('The integral enthalpy of solution differs from the differential enthalpy of solution in that', 'Integral is always zero', 'They are identical', 'Integral is for dissolving 1 mol in a specified amount of solvent; differential is for adding 1 mol to an already large solution', 'Differential is always positive', 'option3', 'Integral: total $\Delta H$ for dissolving in $n$ mol solvent. Differential (partial molar): $\Delta H$ for adding infinitesimal solute to a large solution.', 'c_enthalpies', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_second_law_spontaneity (7 easy, 7 medium, 7 hard = 21)
('The lattice enthalpy of an ionic compound can be experimentally determined using', 'Direct calorimetry', 'The Born-Haber cycle (indirectly, since lattice enthalpy cannot be measured directly)', 'Mass spectrometry', 'X-ray diffraction', 'option2', 'Lattice enthalpy cannot be measured directly. The Born-Haber cycle uses Hess''s law with measurable quantities (IE, EA, sublimation, dissociation, formation enthalpy) to calculate it indirectly.', 'c_enthalpies', 3, 'JEE Mains Prep', 'approved'),
-- Second law, spontaneity, entropy, Gibbs energy
-- ============================================================
('Entropy ($S$) is a measure of', 'The energy of a system', 'The disorder or randomness of a system', 'The temperature', 'The pressure', 'option2', 'Entropy quantifies the number of microstates (ways to arrange energy). Higher disorder $=$ higher entropy.', 'c_second_law_spontaneity', 1, 'JEE Mains Prep', 'approved'),
('The second law of thermodynamics states that', 'Energy is conserved', 'The entropy of the universe always increases for a spontaneous process', 'Entropy can decrease in an isolated system', 'All processes are reversible', 'option2', '$\Delta S_{universe} = \Delta S_{system} + \Delta S_{surroundings} > 0$ for spontaneous processes.', 'c_second_law_spontaneity', 1, 'JEE Mains Prep', 'approved'),
('For a spontaneous process at constant $T$ and $P$, the Gibbs free energy change is', '$\Delta G > 0$', '$\Delta G < 0$', '$\Delta G = 0$', '$\Delta G = \Delta H$', 'option2', '$\Delta G < 0$: spontaneous. $\Delta G = 0$: equilibrium. $\Delta G > 0$: non-spontaneous.', 'c_second_law_spontaneity', 1, 'JEE Mains Prep', 'approved'),
('The Gibbs free energy is defined as', '$G = U + PV$', '$G = H + TS$', '$G = U - TS$', '$G = H - TS$', 'option4', '$G = H - TS$. At constant $T$: $\Delta G = \Delta H - T\Delta S$.', 'c_second_law_spontaneity', 1, 'JEE Mains Prep', 'approved'),
('The entropy of a perfect crystal at absolute zero ($0\;\text{K}$) is', 'Maximum', 'Zero', 'Infinite', 'Negative', 'option2', 'Third law of thermodynamics: $S = 0$ at $T = 0\;\text{K}$ for a perfect crystal (only one microstate).', 'c_second_law_spontaneity', 1, 'JEE Mains Prep', 'approved'),
('Which process has a positive $\Delta S$?', 'Freezing of water', 'Condensation of steam', 'Dissolution of NaCl in water', 'Crystallization', 'option3', 'Dissolution increases disorder (ions spread out in solution). Freezing, condensation, and crystallization decrease disorder.', 'c_second_law_spontaneity', 1, 'JEE Mains Prep', 'approved'),
('A reaction with $\Delta H < 0$ and $\Delta S > 0$ is', 'Spontaneous only at high $T$', 'Non-spontaneous at all temperatures', 'Spontaneous at all temperatures', 'Spontaneous only at low $T$', 'option3', '$\Delta G = \Delta H - T\Delta S$. Both terms make $\Delta G$ negative: $\Delta G < 0$ always.', 'c_second_law_spontaneity', 1, 'JEE Mains Prep', 'approved'),
('A reaction with $\Delta H > 0$ and $\Delta S > 0$ is spontaneous', 'At all temperatures', 'At high temperatures only (when $T\Delta S > \Delta H$)', 'At low temperatures only', 'Never', 'option2', '$\Delta G = \Delta H - T\Delta S < 0$ when $T > \Delta H/\Delta S$. Entropy-driven at high $T$.', 'c_second_law_spontaneity', 2, 'JEE Mains Prep', 'approved'),
('A reaction with $\Delta H < 0$ and $\Delta S < 0$ is spontaneous', 'At all temperatures', 'At high temperatures', 'At low temperatures only (when $|\Delta H| > |T\Delta S|$)', 'Never', 'option3', '$\Delta G = \Delta H - T\Delta S < 0$ when $T < |\Delta H/\Delta S|$. Enthalpy-driven at low $T$.', 'c_second_law_spontaneity', 2, 'JEE Mains Prep', 'approved'),
('The entropy change for a reversible process at constant $T$ is', '$\Delta S = q_{irrev}/T$', '$\Delta S = q_{rev}/T$', '$\Delta S = T/q$', '$\Delta S = 0$', 'option2', '$\Delta S = q_{rev}/T$. For irreversible processes: $\Delta S > q_{irrev}/T$.', 'c_second_law_spontaneity', 2, 'JEE Mains Prep', 'approved'),
('The entropy change of the surroundings for an exothermic reaction ($\Delta H < 0$) at constant $T$ is', '$\Delta S_{surr} = T\Delta H$', '$\Delta S_{surr} = \Delta H/T$ (negative)', '$\Delta S_{surr} = 0$', '$\Delta S_{surr} = -\Delta H/T$ (positive)', 'option4', '$\Delta S_{surr} = -\Delta H_{sys}/T$. For exothermic ($\Delta H < 0$): $\Delta S_{surr} > 0$ (surroundings gain heat).', 'c_second_law_spontaneity', 2, 'JEE Mains Prep', 'approved'),
('For the melting of ice at $0°\text{C}$ and $1\;\text{atm}$, $\Delta G$ is', 'Negative', 'Positive', 'Zero (equilibrium)', 'Undefined', 'option3', 'At the melting point, solid and liquid are in equilibrium: $\Delta G = 0$.', 'c_second_law_spontaneity', 2, 'JEE Mains Prep', 'approved'),
('The standard entropy of vaporization of water at $100°\text{C}$ ($\Delta_{vap}H = 40.7\;\text{kJ/mol}$) is', '$109\;\text{J/(mol}\cdot\text{K)}$', '$40.7\;\text{J/(mol}\cdot\text{K)}$', '$373\;\text{J/(mol}\cdot\text{K)}$', '$0$', 'option1', 'At boiling point: $\Delta G = 0$, so $\Delta S = \Delta H/T = 40700/373 = 109\;\text{J/(mol}\cdot\text{K)}$.', 'c_second_law_spontaneity', 2, 'JEE Mains Prep', 'approved'),
('The entropy change for $n$ moles of an ideal gas expanding isothermally from $V_1$ to $V_2$ is', '$nR\ln(V_2/V_1)$', '$nR\ln(V_1/V_2)$', '$nC_V\ln(T_2/T_1)$', '$0$', 'option1', '$\Delta S = q_{rev}/T = nRT\ln(V_2/V_1)/T = nR\ln(V_2/V_1)$.', 'c_second_law_spontaneity', 2, 'JEE Mains Prep', 'approved'),
('For a reaction with $\Delta H = +100\;\text{kJ}$ and $\Delta S = +200\;\text{J/K}$, the temperature above which the reaction becomes spontaneous is', '$200\;\text{K}$', '$500\;\text{K}$', '$0.5\;\text{K}$', '$1000\;\text{K}$', 'option2', '$\Delta G = 0$ at $T = \Delta H/\Delta S = 100000/200 = 500\;\text{K}$. Above $500\;\text{K}$: $\Delta G < 0$.', 'c_second_law_spontaneity', 3, 'JEE Mains Prep', 'approved'),
('The Gibbs-Helmholtz equation relates $\Delta G$ to temperature as', '$\Delta G = \Delta H + T\Delta S$', '$[\partial(\Delta G/T)/\partial T]_P = -\Delta H/T^2$', '$\Delta G/T = \Delta H$', '$\partial\Delta G/\partial T = \Delta S$', 'option2', 'The Gibbs-Helmholtz equation: $[\partial(\Delta G/T)/\partial T]_P = -\Delta H/T^2$. Useful for predicting how $\Delta G$ changes with $T$.', 'c_second_law_spontaneity', 3, 'JEE Mains Prep', 'approved'),
('For a reaction at equilibrium', '$\Delta G = 0$ but $\Delta G^\circ$ may not be zero', '$\Delta G^\circ = 0$', '$\Delta H = 0$', '$\Delta S = 0$', 'option1', 'At equilibrium: $\Delta G = 0$. But $\Delta G^\circ = -RT\ln K$, which is zero only if $K = 1$.', 'c_second_law_spontaneity', 3, 'JEE Mains Prep', 'approved'),
('The entropy of the universe for an irreversible process is', 'Zero', 'Negative', 'Positive (increases)', 'Undefined', 'option3', '$\Delta S_{universe} > 0$ for all real (irreversible) processes. $\Delta S_{universe} = 0$ only for reversible processes.', 'c_second_law_spontaneity', 3, 'JEE Mains Prep', 'approved'),
('Trouton''s rule states that the entropy of vaporization of many liquids at their normal boiling point is approximately', '$85\;\text{J/(mol}\cdot\text{K)}$', '$40\;\text{J/(mol}\cdot\text{K)}$', '$150\;\text{J/(mol}\cdot\text{K)}$', '$8.314\;\text{J/(mol}\cdot\text{K)}$', 'option1', 'Trouton''s rule: $\Delta_{vap}S \approx 85\;\text{J/(mol}\cdot\text{K)}$ for non-associated liquids. Water ($109$) deviates due to H-bonding.', 'c_second_law_spontaneity', 3, 'JEE Mains Prep', 'approved'),
('The standard Gibbs energy of formation of an element in its standard state is', 'Positive', 'Negative', 'Zero', 'Undefined', 'option3', 'By convention, $\Delta_f G^\circ = 0$ for elements in their standard states (same as $\Delta_f H^\circ$).', 'c_second_law_spontaneity', 3, 'JEE Mains Prep', 'approved'),
('For the decomposition of CaCO$_3$: $\Delta H = +178\;\text{kJ}$, $\Delta S = +161\;\text{J/K}$. The decomposition becomes spontaneous above', '$1106\;\text{K}$ ($\approx 833°\text{C}$)', '$178\;\text{K}$', '$500\;\text{K}$', '$2000\;\text{K}$', 'option1', '$T = \Delta H/\Delta S = 178000/161 = 1106\;\text{K}$. Above this, $\Delta G < 0$.', 'c_second_law_spontaneity', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_gibbs_equilibrium (7 easy, 7 medium, 7 hard = 21)
-- Standard Gibbs energy change and equilibrium constant
-- ============================================================
('The relationship between standard Gibbs energy change and the equilibrium constant is', '$\Delta G^\circ = RT\ln K$', '$\Delta G^\circ = -RT\ln K$', '$\Delta G^\circ = -R\ln K$', '$\Delta G^\circ = K/RT$', 'option2', '$\Delta G^\circ = -RT\ln K = -2.303RT\log K$. Negative $\Delta G^\circ$ means $K > 1$ (products favoured).', 'c_gibbs_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('If $K > 1$ for a reaction, then $\Delta G^\circ$ is', 'Positive', 'Negative', 'Zero', 'Undefined', 'option2', '$\Delta G^\circ = -RT\ln K$. If $K > 1$: $\ln K > 0$, so $\Delta G^\circ < 0$ (products thermodynamically favoured).', 'c_gibbs_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('At equilibrium, the Gibbs free energy of the system is', 'Maximum', 'Minimum', 'Zero', 'Equal to enthalpy', 'option2', 'At constant $T$ and $P$, a system reaches equilibrium when $G$ is at its minimum value. $\Delta G = 0$ at equilibrium.', 'c_gibbs_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('If $\Delta G^\circ = 0$, the equilibrium constant $K$ equals', '$0$', '$1$', '$\infty$', '$-1$', 'option2', '$0 = -RT\ln K$. $\ln K = 0$. $K = 1$ (neither products nor reactants are favoured).', 'c_gibbs_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('The Gibbs energy change under non-standard conditions is given by', '$\Delta G = \Delta G^\circ \times Q$', '$\Delta G = \Delta G^\circ - RT\ln Q$', '$\Delta G = RT\ln Q$', '$\Delta G = \Delta G^\circ + RT\ln Q$', 'option4', '$\Delta G = \Delta G^\circ + RT\ln Q$ where $Q$ is the reaction quotient. At equilibrium: $Q = K$ and $\Delta G = 0$.', 'c_gibbs_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('A large negative $\Delta G^\circ$ indicates', 'The reaction goes nearly to completion ($K \gg 1$)', 'The reaction barely proceeds', 'Equilibrium favours reactants', 'The reaction is endothermic', 'option1', 'Large negative $\Delta G^\circ$ $\rightarrow$ large positive $\ln K$ $\rightarrow$ $K \gg 1$ $\rightarrow$ products strongly favoured.', 'c_gibbs_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('$\Delta G^\circ$ can be calculated from', '$\Delta G^\circ = \Delta H^\circ/T\Delta S^\circ$', '$\Delta G^\circ = \Delta H^\circ + T\Delta S^\circ$', '$\Delta G^\circ = T\Delta S^\circ - \Delta H^\circ$', '$\Delta G^\circ = \Delta H^\circ - T\Delta S^\circ$', 'option4', '$\Delta G^\circ = \Delta H^\circ - T\Delta S^\circ$ at standard conditions.', 'c_gibbs_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('For a reaction with $\Delta G^\circ = -5.7\;\text{kJ/mol}$ at $298\;\text{K}$, the equilibrium constant $K$ is approximately ($R = 8.314\;\text{J/mol}\cdot\text{K}$)', '$0.1$', '$100$', '$1$', '$10$', 'option4', '$\ln K = -\Delta G^\circ/(RT) = 5700/(8.314 \times 298) = 2.30$. $K = e^{2.30} \approx 10$.', 'c_gibbs_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('If $K = 10^{-3}$ at $298\;\text{K}$, the value of $\Delta G^\circ$ is approximately', '$+17.1\;\text{kJ/mol}$', '$-17.1\;\text{kJ/mol}$', '$+5.7\;\text{kJ/mol}$', '$-5.7\;\text{kJ/mol}$', 'option1', '$\Delta G^\circ = -2.303RT\log K = -2.303 \times 8.314 \times 298 \times (-3) = +17.1\;\text{kJ/mol}$.', 'c_gibbs_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The relationship between $K_p$ and $K_c$ is', '$K_p = K_c + RT$', '$K_p = K_c/(RT)^{\Delta n_g}$', '$K_p = K_c$', '$K_p = K_c(RT)^{\Delta n_g}$', 'option4', '$K_p = K_c(RT)^{\Delta n_g}$ where $\Delta n_g$ = moles of gaseous products $-$ moles of gaseous reactants.', 'c_gibbs_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('For the reaction N$_2$O$_4$(g) $\rightleftharpoons$ 2NO$_2$(g), $\Delta n_g = +1$. If $K_c = 4.6 \times 10^{-3}$ at $298\;\text{K}$, then $K_p$ is', '$4.6 \times 10^{-3}$', '$0.112$', '$1.88 \times 10^{-4}$', '$0.046$', 'option2', '$K_p = K_c(RT)^1 = 4.6 \times 10^{-3} \times 0.0821 \times 298 = 4.6 \times 10^{-3} \times 24.47 = 0.113$.', 'c_gibbs_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The van''t Hoff equation relating $K$ to temperature is', '$\ln(K_2/K_1) = (\Delta H^\circ/R)(1/T_2 - 1/T_1)$', '$\ln(K_2/K_1) = (\Delta H^\circ/R)(1/T_1 - 1/T_2)$', '$K_2/K_1 = \Delta H^\circ(T_2 - T_1)$', '$\ln K = -\Delta H^\circ/T$', 'option2', 'Van''t Hoff: $\ln(K_2/K_1) = (\Delta H^\circ/R)(1/T_1 - 1/T_2)$. For exothermic reactions, $K$ decreases with increasing $T$.', 'c_gibbs_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('For an exothermic reaction, increasing temperature causes $K$ to', 'Increase', 'Decrease', 'Remain the same', 'Become zero', 'option2', 'Exothermic: $\Delta H^\circ < 0$. Van''t Hoff equation shows $K$ decreases as $T$ increases (Le Chatelier: heat is a product).', 'c_gibbs_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('$\Delta G^\circ$ for the formation of water from H$_2$ and O$_2$ is $-237\;\text{kJ/mol}$ at $298\;\text{K}$. The equilibrium constant is', 'Extremely large ($\sim 10^{41}$)', 'Approximately $1$', 'Very small ($\sim 10^{-41}$)', 'Exactly $237$', 'option1', '$\log K = -\Delta G^\circ/(2.303RT) = 237000/(2.303 \times 8.314 \times 298) = 41.5$. $K \approx 10^{41.5}$. Reaction goes essentially to completion.', 'c_gibbs_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The standard Gibbs energy of reaction can be calculated from standard Gibbs energies of formation as', '$\Delta_r G^\circ = \sum \Delta_f G^\circ(\text{products}) + \sum \Delta_f G^\circ(\text{reactants})$', '$\Delta_r G^\circ = \sum \Delta_f G^\circ(\text{reactants}) - \sum \Delta_f G^\circ(\text{products})$', '$\Delta_r G^\circ = \sum \Delta_f G^\circ(\text{products}) - \sum \Delta_f G^\circ(\text{reactants})$', '$\Delta_r G^\circ = 0$ always', 'option3', 'Same pattern as $\Delta H$: products minus reactants.', 'c_gibbs_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('For an exothermic reaction with $K = 10^5$ at $300\;\text{K}$ and $\Delta H^\circ = -50\;\text{kJ/mol}$, the value of $K$ at $400\;\text{K}$ is approximately', '$\sim 10^1$', '$\sim 10^5$', '$\sim 10^7$', '$\sim 10^3$', 'option4', 'Using van''t Hoff: $\ln(K_2/K_1) = (\Delta H^\circ/R)(1/T_1 - 1/T_2) = (-50000/8.314)(1/300 - 1/400) = -5.01$. $K_2 = 10^5 \times e^{-5.01} \approx 670 \approx 10^3$.', 'c_gibbs_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('The coupling of a non-spontaneous reaction ($\Delta G_1 > 0$) with a highly spontaneous reaction ($\Delta G_2 \ll 0$) can make the overall process spontaneous if', 'Coupling never works', '$\Delta G_1 = 0$', '$\Delta G_2 = 0$', '$|\Delta G_2| > |\Delta G_1|$ so that $\Delta G_{total} < 0$', 'option4', 'Biological systems use ATP hydrolysis ($\Delta G^\circ = -30.5\;\text{kJ/mol}$) to drive non-spontaneous reactions by coupling.', 'c_gibbs_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('The electrochemical cell potential $E^\circ$ is related to $\Delta G^\circ$ by', '$\Delta G^\circ = -E^\circ/nF$', '$\Delta G^\circ = nFE^\circ$', '$\Delta G^\circ = -nFE^\circ$', '$\Delta G^\circ = nE^\circ/F$', 'option3', '$\Delta G^\circ = -nFE^\circ$ where $n$ = moles of electrons transferred, $F = 96485\;\text{C/mol}$.', 'c_gibbs_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('For a cell with $E^\circ = 1.1\;\text{V}$ and $n = 2$, the equilibrium constant at $298\;\text{K}$ is approximately', '$\sim 10^{5}$', '$\sim 10^{18}$', '$\sim 10^{37}$', '$\sim 10^{2}$', 'option3', '$\Delta G^\circ = -nFE^\circ = -2 \times 96485 \times 1.1 = -212267\;\text{J}$. $\log K = nFE^\circ/(2.303RT) = 212267/5706 = 37.2$. $K \approx 10^{37}$.', 'c_gibbs_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('The temperature dependence of $\Delta G^\circ$ is primarily governed by', 'The $-T\Delta S^\circ$ term (entropy contribution increases with temperature)', 'The $\Delta H^\circ$ term only', 'Neither $\Delta H$ nor $\Delta S$', 'The pressure', 'option1', '$\Delta G^\circ = \Delta H^\circ - T\Delta S^\circ$. As $T$ increases, the $T\Delta S^\circ$ term dominates, making entropy-driven reactions more favourable.', 'c_gibbs_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('If $\Delta G^\circ$ for a reaction is $-11.4\;\text{kJ/mol}$ at $298\;\text{K}$, the ratio of products to reactants at equilibrium is approximately', '$100:1$', '$10:1$', '$1:1$', '$1000:1$', 'option1', '$\log K = 11400/(2.303 \times 8.314 \times 298) = 11400/5706 = 2.0$. $K = 100$. Products are 100 times more concentrated than reactants.', 'c_gibbs_equilibrium', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_concentration_methods (7 easy, 7 medium, 7 hard = 21)
-- Molality, molarity, mole fraction, percentage
-- ============================================================
('Molarity is defined as', 'Mass of solute per litre', 'Moles of solute per kg of solvent', 'Moles of solute per litre of solution', 'Moles of solute per mole of solution', 'option3', 'Molarity $M = n_{solute}/V_{solution}$ (mol/L). It changes with temperature (volume changes).', 'c_concentration_methods', 1, 'JEE Mains Prep', 'approved'),
('Molality is defined as', 'Moles of solute per litre of solution', 'Moles of solute per kilogram of solvent', 'Grams of solute per litre', 'Volume of solute per volume of solution', 'option2', 'Molality $m = n_{solute}/m_{solvent}$ (mol/kg). Independent of temperature (mass doesn''t change with $T$).', 'c_concentration_methods', 1, 'JEE Mains Prep', 'approved'),
('The mole fraction of a component $A$ in a binary solution is', '$x_A = n_A/(n_A + n_B)$', '$x_A = n_A/n_B$', '$x_A = n_A \times n_B$', '$x_A = n_B/(n_A + n_B)$', 'option1', 'Mole fraction: $x_A + x_B = 1$. Dimensionless, temperature-independent.', 'c_concentration_methods', 1, 'JEE Mains Prep', 'approved'),
('A $10\%$ (w/w) solution of NaOH means', '$10\;\text{g}$ NaOH in $100\;\text{g}$ of water', '$10\;\text{g}$ NaOH in $100\;\text{mL}$ of solution', '$10\;\text{g}$ NaOH in $100\;\text{g}$ of solution', '$10\;\text{mol}$ NaOH in $100\;\text{mol}$ solution', 'option3', 'Weight/weight percentage: mass of solute per 100 g of solution.', 'c_concentration_methods', 1, 'JEE Mains Prep', 'approved'),
('Which concentration unit is independent of temperature?', 'Molarity', 'Molality', 'Volume percentage', 'Normality', 'option2', 'Molality uses mass of solvent (not volume), so it doesn''t change with temperature. Molarity and normality depend on volume.', 'c_concentration_methods', 1, 'JEE Mains Prep', 'approved'),
('Parts per million (ppm) is used for', 'Very dilute solutions', 'Very concentrated solutions', 'Pure substances', 'Gases only', 'option1', 'ppm $=$ (mass of solute / mass of solution) $\times 10^6$. Used for trace quantities (e.g., pollutants in water).', 'c_concentration_methods', 1, 'JEE Mains Prep', 'approved'),
('Normality is defined as', 'Moles per kg', 'Moles per litre', 'Number of gram equivalents of solute per litre of solution', 'Grams per litre', 'option3', '$N = $ gram equivalents / volume (L). $N = n \times M$ where $n$ is the $n$-factor.', 'c_concentration_methods', 1, 'JEE Mains Prep', 'approved'),
('The molarity of a solution containing $4\;\text{g}$ of NaOH ($M = 40$) in $250\;\text{mL}$ is', '$0.2\;\text{M}$', '$0.4\;\text{M}$', '$0.1\;\text{M}$', '$1.0\;\text{M}$', 'option2', '$n = 4/40 = 0.1\;\text{mol}$. $M = 0.1/0.25 = 0.4\;\text{M}$.', 'c_concentration_methods', 2, 'JEE Mains Prep', 'approved'),
('The molality of a solution prepared by dissolving $9\;\text{g}$ of glucose ($M = 180$) in $500\;\text{g}$ of water is', '$1.0\;\text{m}$', '$0.05\;\text{m}$', '$0.1\;\text{m}$', '$0.5\;\text{m}$', 'option3', '$n = 9/180 = 0.05\;\text{mol}$. $m = 0.05/0.5 = 0.1\;\text{mol/kg}$.', 'c_concentration_methods', 2, 'JEE Mains Prep', 'approved'),
('The mole fraction of ethanol in a solution containing $46\;\text{g}$ ethanol ($M = 46$) and $72\;\text{g}$ water ($M = 18$) is', '$0.50$', '$0.25$', '$0.20$', '$0.80$', 'option3', '$n_{eth} = 46/46 = 1$. $n_{water} = 72/18 = 4$. $x_{eth} = 1/(1+4) = 0.20$.', 'c_concentration_methods', 2, 'JEE Mains Prep', 'approved'),
('The relationship between molarity ($M$) and molality ($m$) for a solution of density $d$ (g/mL) and molar mass of solute $M_s$ is', '$m = M/d$', '$m = 1000M/(1000d - MM_s)$', '$m = Md$', '$m = M \times M_s$', 'option2', '$m = 1000M/(1000d - MM_s)$ where $d$ is density in g/mL and $M_s$ is molar mass of solute.', 'c_concentration_methods', 2, 'JEE Mains Prep', 'approved'),
('$500\;\text{mL}$ of $0.1\;\text{M}$ HCl is diluted to $1\;\text{L}$. The new molarity is', '$0.5\;\text{M}$', '$0.1\;\text{M}$', '$0.2\;\text{M}$', '$0.05\;\text{M}$', 'option4', '$M_1V_1 = M_2V_2$. $0.1 \times 500 = M_2 \times 1000$. $M_2 = 0.05\;\text{M}$.', 'c_concentration_methods', 2, 'JEE Mains Prep', 'approved'),
('The normality of $0.5\;\text{M}$ H$_2$SO$_4$ is', '$0.5\;\text{N}$', '$1.0\;\text{N}$', '$0.25\;\text{N}$', '$2.0\;\text{N}$', 'option2', 'H$_2$SO$_4$ is diprotic ($n$-factor $= 2$). $N = n \times M = 2 \times 0.5 = 1.0\;\text{N}$.', 'c_concentration_methods', 2, 'JEE Mains Prep', 'approved'),
('A solution has density $1.2\;\text{g/mL}$ and is $20\%$ (w/w) NaOH ($M = 40$). Its molarity is', '$6\;\text{M}$', '$3\;\text{M}$', '$12\;\text{M}$', '$0.6\;\text{M}$', 'option1', '$1\;\text{L}$ of solution $= 1200\;\text{g}$. NaOH $= 20\% \times 1200 = 240\;\text{g}$. $n = 240/40 = 6\;\text{mol}$. $M = 6\;\text{M}$.', 'c_concentration_methods', 2, 'JEE Mains Prep', 'approved'),
('The molality of a $10\%$ (w/w) urea ($M = 60$) solution is', '$0.167\;\text{m}$', '$1.67\;\text{m}$', '$1.85\;\text{m}$', '$10\;\text{m}$', 'option3', '$10\;\text{g}$ urea in $90\;\text{g}$ water. $n = 10/60 = 0.167\;\text{mol}$. $m = 0.167/0.09 = 1.85\;\text{mol/kg}$.', 'c_concentration_methods', 3, 'JEE Mains Prep', 'approved'),
('Concentrated H$_2$SO$_4$ is $98\%$ (w/w) with density $1.84\;\text{g/mL}$. Its molarity is approximately', '$9.2\;\text{M}$', '$18.4\;\text{M}$', '$36.8\;\text{M}$', '$1.84\;\text{M}$', 'option2', '$1\;\text{L} = 1840\;\text{g}$. H$_2$SO$_4 = 0.98 \times 1840 = 1803\;\text{g}$. $n = 1803/98 = 18.4\;\text{mol}$. $M = 18.4\;\text{M}$.', 'c_concentration_methods', 3, 'JEE Mains Prep', 'approved'),
('If $200\;\text{mL}$ of $0.5\;\text{M}$ NaOH is mixed with $300\;\text{mL}$ of $0.3\;\text{M}$ NaOH, the resulting molarity is', '$0.40\;\text{M}$', '$0.38\;\text{M}$', '$0.80\;\text{M}$', '$0.30\;\text{M}$', 'option2', 'Total moles $= 0.5 \times 0.2 + 0.3 \times 0.3 = 0.1 + 0.09 = 0.19$. Total volume $= 0.5\;\text{L}$. $M = 0.19/0.5 = 0.38\;\text{M}$.', 'c_concentration_methods', 3, 'JEE Mains Prep', 'approved'),
('The formality of a $0.1\;\text{M}$ NaCl solution is', '$0.2\;\text{F}$', '$0.1\;\text{F}$', '$0.05\;\text{F}$', 'Formality is not applicable', 'option2', 'Formality $=$ formula weights per litre. For NaCl (which dissociates): formality $= 0.1\;\text{F}$ (same as molarity for the formula unit).', 'c_concentration_methods', 3, 'JEE Mains Prep', 'approved'),
('The mass of KMnO$_4$ ($M = 158$) needed to prepare $500\;\text{mL}$ of $0.02\;\text{N}$ solution in acidic medium ($n$-factor $= 5$) is', '$0.316\;\text{g}$', '$1.58\;\text{g}$', '$0.158\;\text{g}$', '$3.16\;\text{g}$', 'option1', 'Equivalent mass $= 158/5 = 31.6$. Gram equivalents $= 0.02 \times 0.5 = 0.01$. Mass $= 0.01 \times 31.6 = 0.316\;\text{g}$.', 'c_concentration_methods', 3, 'JEE Mains Prep', 'approved'),
('The interconversion between mole fraction ($x_B$) and molality ($m$) for a solute $B$ in solvent $A$ ($M_A$ = molar mass of solvent) is', '$m = x_B/M_A$', '$m = x_B \times 1000/(x_A \times M_A)$', '$m = x_A/(x_B \times M_A)$', '$m = x_B \times M_A$', 'option2', '$m = n_B/(m_A\;\text{in kg}) = (x_B/(1-x_B)) \times (1000/M_A)$ for dilute solutions where $x_A \approx 1$.', 'c_concentration_methods', 3, 'JEE Mains Prep', 'approved'),
('A $2\;\text{M}$ aqueous solution of urea ($M = 60$) has density $1.05\;\text{g/mL}$. The molality is', '$2.15\;\text{m}$', '$2.0\;\text{m}$', '$1.90\;\text{m}$', '$2.50\;\text{m}$', 'option1', '$1\;\text{L}$ solution $= 1050\;\text{g}$. Urea $= 2 \times 60 = 120\;\text{g}$. Solvent $= 1050 - 120 = 930\;\text{g} = 0.93\;\text{kg}$. $m = 2/0.93 = 2.15\;\text{mol/kg}$.', 'c_concentration_methods', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_raoults_law (7 easy, 7 medium, 7 hard = 21)
-- Vapour pressure, Raoult''s law, ideal/non-ideal solutions
-- ============================================================
('Raoult''s law states that the partial vapour pressure of a component in a solution is', 'Proportional to the mass of the component', 'Independent of composition', 'Always equal to the pure vapour pressure', 'Equal to the mole fraction of the component times its pure vapour pressure', 'option4', '$P_A = x_A P_A^\circ$ where $x_A$ is the mole fraction and $P_A^\circ$ is the vapour pressure of pure $A$.', 'c_raoults_law', 1, 'JEE Mains Prep', 'approved'),
('An ideal solution obeys Raoult''s law', 'Only at high concentrations', 'Over the entire range of composition', 'Only at low concentrations', 'Never', 'option2', 'Ideal solutions obey Raoult''s law at all compositions. $\Delta H_{mix} = 0$, $\Delta V_{mix} = 0$.', 'c_raoults_law', 1, 'JEE Mains Prep', 'approved'),
('The vapour pressure of a solution is always _____ than the vapour pressure of the pure solvent (for a non-volatile solute).', 'Higher', 'Lower', 'The same', 'Double', 'option2', 'Adding a non-volatile solute lowers the vapour pressure: $P = x_{solvent} P^\circ < P^\circ$ (since $x_{solvent} < 1$).', 'c_raoults_law', 1, 'JEE Mains Prep', 'approved'),
('An example of an ideal solution is', 'Ethanol + water', 'Benzene + toluene', 'Acetone + chloroform', 'HCl + water', 'option2', 'Benzene and toluene have similar structures and intermolecular forces, forming a nearly ideal solution.', 'c_raoults_law', 1, 'JEE Mains Prep', 'approved'),
('A solution showing positive deviation from Raoult''s law has', 'Weaker solute-solvent interactions than pure component interactions', 'Stronger solute-solvent interactions', 'No intermolecular forces', 'Identical interactions', 'option1', 'Positive deviation: A-B interactions weaker than A-A and B-B. Molecules escape more easily. $P_{total} > P_{ideal}$.', 'c_raoults_law', 1, 'JEE Mains Prep', 'approved'),
('A solution showing negative deviation from Raoult''s law has', 'Weaker solute-solvent interactions', 'Stronger solute-solvent interactions than pure component interactions', 'No interactions', 'Identical interactions', 'option2', 'Negative deviation: A-B interactions stronger than A-A and B-B. Molecules are held more tightly. $P_{total} < P_{ideal}$.', 'c_raoults_law', 1, 'JEE Mains Prep', 'approved'),
('The relative lowering of vapour pressure for a dilute solution of a non-volatile solute is', '$(P - P^\circ)/P = x_{solute}$', '$(P^\circ - P)/P^\circ = x_{solvent}$', '$P/P^\circ = x_{solute}$', '$(P^\circ - P)/P^\circ = x_{solute}$', 'option4', 'Relative lowering $= (P^\circ - P)/P^\circ = 1 - x_{solvent} = x_{solute}$ (Raoult''s law).', 'c_raoults_law', 1, 'JEE Mains Prep', 'approved'),
('An example of a solution with positive deviation is', 'Acetone + chloroform', 'Ethanol + water', 'Chloroform + diethyl ether', 'HNO$_3$ + water', 'option2', 'Ethanol-water: H-bonding between ethanol molecules is disrupted. Vapour pressure is higher than ideal.', 'c_raoults_law', 2, 'JEE Mains Prep', 'approved'),
('An example of a solution with negative deviation is', 'Ethanol + water', 'Acetone + chloroform', 'Benzene + toluene', 'Carbon disulfide + acetone', 'option2', 'Acetone-chloroform: H-bonding forms between C=O of acetone and C-H of CHCl$_3$. Stronger A-B interaction $\rightarrow$ negative deviation.', 'c_raoults_law', 2, 'JEE Mains Prep', 'approved'),
('For a solution with positive deviation, the azeotrope formed is', 'A minimum boiling azeotrope', 'A maximum boiling azeotrope', 'No azeotrope forms', 'A zeotrope', 'option1', 'Positive deviation $\rightarrow$ higher vapour pressure $\rightarrow$ lower boiling point $\rightarrow$ minimum boiling azeotrope (e.g., ethanol-water at $95.6\%$).', 'c_raoults_law', 2, 'JEE Mains Prep', 'approved'),
('For a solution with negative deviation, the azeotrope formed is', 'A minimum boiling azeotrope', 'A maximum boiling azeotrope', 'No azeotrope', 'A eutectic mixture', 'option2', 'Negative deviation $\rightarrow$ lower vapour pressure $\rightarrow$ higher boiling point $\rightarrow$ maximum boiling azeotrope (e.g., HCl-water at $20.2\%$).', 'c_raoults_law', 2, 'JEE Mains Prep', 'approved'),
('The vapour pressure of pure water at $25°\text{C}$ is $23.8\;\text{mmHg}$. The vapour pressure of a solution with mole fraction of water $= 0.9$ is', '$21.42\;\text{mmHg}$', '$23.8\;\text{mmHg}$', '$26.4\;\text{mmHg}$', '$2.38\;\text{mmHg}$', 'option1', '$P = x_{water} \times P^\circ = 0.9 \times 23.8 = 21.42\;\text{mmHg}$.', 'c_raoults_law', 2, 'JEE Mains Prep', 'approved'),
('For an ideal solution of two volatile liquids $A$ and $B$, the total vapour pressure is', '$P = P_A^\circ + P_B^\circ$', '$P = x_A P_A^\circ + x_B P_B^\circ$', '$P = x_A P_B^\circ + x_B P_A^\circ$', '$P = (P_A^\circ \times P_B^\circ)/(x_A + x_B)$', 'option2', 'Dalton''s law + Raoult''s law: $P_{total} = x_A P_A^\circ + x_B P_B^\circ = P_B^\circ + (P_A^\circ - P_B^\circ)x_A$ (linear in $x_A$).', 'c_raoults_law', 2, 'JEE Mains Prep', 'approved'),
('The composition of vapour above an ideal solution is given by', '$y_A = x_A P_A^\circ / P_{total}$', '$y_A = x_A$', '$y_A = P_A^\circ / P_{total}$', '$y_A = x_B P_A^\circ$', 'option1', 'Dalton''s law: $y_A = P_A/P_{total} = x_A P_A^\circ/P_{total}$. The vapour is enriched in the more volatile component.', 'c_raoults_law', 2, 'JEE Mains Prep', 'approved'),
('For a solution with $\Delta H_{mix} > 0$ and $\Delta V_{mix} > 0$, the deviation from Raoult''s law is', 'Positive', 'Negative', 'Zero (ideal)', 'Cannot be determined', 'option1', '$\Delta H_{mix} > 0$ (endothermic mixing) and $\Delta V_{mix} > 0$ (volume expansion) indicate weaker A-B interactions $\rightarrow$ positive deviation.', 'c_raoults_law', 3, 'JEE Mains Prep', 'approved'),
('Two liquids $A$ ($P_A^\circ = 100\;\text{mmHg}$) and $B$ ($P_B^\circ = 300\;\text{mmHg}$) form an ideal solution. At $x_A = 0.4$, the mole fraction of $A$ in the vapour phase is', '$0.182$', '$0.4$', '$0.6$', '$0.818$', 'option1', '$P_A = 0.4 \times 100 = 40$. $P_B = 0.6 \times 300 = 180$. $P_{total} = 220$. $y_A = 40/220 = 0.182$.', 'c_raoults_law', 3, 'JEE Mains Prep', 'approved'),
('An azeotrope cannot be separated by simple distillation because', 'The mixture is a compound', 'The components are chemically bonded', 'The boiling point is too high', 'The liquid and vapour have the same composition at the azeotropic point', 'option4', 'At the azeotropic composition, liquid and vapour have identical composition, so distillation cannot change the ratio.', 'c_raoults_law', 3, 'JEE Mains Prep', 'approved'),
('Henry''s law states that the solubility of a gas in a liquid is', 'Directly proportional to the partial pressure of the gas above the solution', 'Inversely proportional to pressure', 'Independent of pressure', 'Proportional to temperature', 'option1', '$P = K_H x_{gas}$ where $K_H$ is Henry''s law constant. Higher pressure $\rightarrow$ more gas dissolves.', 'c_raoults_law', 3, 'JEE Mains Prep', 'approved'),
('Henry''s law is a special case of Raoult''s law applicable to', 'The solute in a dilute solution', 'The solvent in a dilute solution', 'Concentrated solutions', 'Ideal solutions only', 'option1', 'For dilute solutions: solvent obeys Raoult''s law ($P_A = x_A P_A^\circ$) and solute obeys Henry''s law ($P_B = K_H x_B$).', 'c_raoults_law', 3, 'JEE Mains Prep', 'approved'),
('The Henry''s law constant $K_H$ for O$_2$ in water is much larger than for CO$_2$. This means', 'Solubility is independent of $K_H$', 'O$_2$ is more soluble', 'Both are equally soluble', 'O$_2$ is less soluble than CO$_2$ in water at the same partial pressure', 'option4', '$x = P/K_H$. Larger $K_H$ means smaller $x$ (less soluble) at the same pressure. CO$_2$ reacts with water, increasing its effective solubility.', 'c_raoults_law', 3, 'JEE Mains Prep', 'approved'),
('The vapour pressure of a binary ideal solution varies linearly with mole fraction when plotted as $P_{total}$ vs $x_A$. However, the plot of $P_{total}$ vs $y_A$ (vapour composition) is', 'Also linear', 'A curve (non-linear)', 'A horizontal line', 'A vertical line', 'option2', '$P_{total}$ vs $y_A$ is non-linear because $y_A = x_A P_A^\circ/P_{total}$ introduces a non-linear relationship. The $P$-$y$ curve is always below the $P$-$x$ line.', 'c_raoults_law', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_colligative_properties (7 easy, 7 medium, 7 hard = 21)
-- Vapour pressure lowering, FPD, BPE, osmotic pressure
-- ============================================================
('Colligative properties depend on', 'The nature of the solute', 'The number of solute particles in solution', 'The colour of the solution', 'The mass of the solute only', 'option2', 'Colligative: depends on the count of solute particles, not their identity. Examples: VP lowering, BPE, FPD, osmotic pressure.', 'c_colligative_properties', 1, 'JEE Mains Prep', 'approved'),
('Boiling point elevation ($\Delta T_b$) is given by', '$\Delta T_b = K_b \times m$', '$\Delta T_b = K_b / m$', '$\Delta T_b = K_b \times M$', '$\Delta T_b = m / K_b$', 'option1', '$\Delta T_b = K_b m$ where $K_b$ is the ebullioscopic constant and $m$ is molality.', 'c_colligative_properties', 1, 'JEE Mains Prep', 'approved'),
('Freezing point depression ($\Delta T_f$) is given by', '$\Delta T_f = K_f / m$', '$\Delta T_f = K_f \times m$', '$\Delta T_f = K_f \times M$', '$\Delta T_f = m / K_f$', 'option2', '$\Delta T_f = K_f m$ where $K_f$ is the cryoscopic constant.', 'c_colligative_properties', 1, 'JEE Mains Prep', 'approved'),
('Osmotic pressure ($\pi$) of a dilute solution is given by', '$\pi = MRT$', '$\pi = mRT$', '$\pi = nRT/V$ (equivalent to $\pi = CRT$)', 'Both option1 and option3', 'option4', '$\pi = CRT$ where $C$ is molarity. Also $\pi = nRT/V$. Both are equivalent for dilute solutions.', 'c_colligative_properties', 1, 'JEE Mains Prep', 'approved'),
('Osmosis is the flow of', 'Solute from dilute to concentrated solution', 'Solvent from dilute to concentrated solution through a semipermeable membrane', 'Solvent from concentrated to dilute', 'Both solute and solvent', 'option2', 'Osmosis: solvent moves from lower solute concentration to higher through a semipermeable membrane.', 'c_colligative_properties', 1, 'JEE Mains Prep', 'approved'),
('Reverse osmosis is used for', 'Water purification (desalination)', 'Heating water', 'Freezing water', 'Boiling water', 'option1', 'Applying pressure greater than osmotic pressure forces solvent through the membrane, leaving solute behind.', 'c_colligative_properties', 1, 'JEE Mains Prep', 'approved'),
('Among the colligative properties, the most accurate for determining molar mass is', 'Boiling point elevation', 'Freezing point depression', 'Osmotic pressure', 'Vapour pressure lowering', 'option3', 'Osmotic pressure is measurable even for very dilute solutions and at room temperature, giving the most accurate molar mass.', 'c_colligative_properties', 1, 'JEE Mains Prep', 'approved'),
('A solution of $6\;\text{g}$ of urea ($M = 60$) in $500\;\text{g}$ of water ($K_f = 1.86\;\text{K}\cdot\text{kg/mol}$) has freezing point depression', '$3.72\;\text{K}$', '$0.186\;\text{K}$', '$1.86\;\text{K}$', '$0.372\;\text{K}$', 'option4', '$m = (6/60)/0.5 = 0.2\;\text{mol/kg}$. $\Delta T_f = 1.86 \times 0.2 = 0.372\;\text{K}$.', 'c_colligative_properties', 2, 'JEE Mains Prep', 'approved'),
('The osmotic pressure of a $0.1\;\text{M}$ glucose solution at $300\;\text{K}$ is ($R = 0.0821\;\text{L}\cdot\text{atm/mol}\cdot\text{K}$)', '$24.6\;\text{atm}$', '$2.46\;\text{atm}$', '$0.246\;\text{atm}$', '$246\;\text{atm}$', 'option2', '$\pi = MRT = 0.1 \times 0.0821 \times 300 = 2.463\;\text{atm}$.', 'c_colligative_properties', 2, 'JEE Mains Prep', 'approved'),
('A $0.1\;\text{m}$ solution of NaCl (complete dissociation) has a freezing point depression _____ that of $0.1\;\text{m}$ glucose.', 'Equal to', 'Approximately twice', 'Approximately half', 'Three times', 'option2', 'NaCl $\to$ Na$^+$ + Cl$^-$ (2 particles). $i = 2$. $\Delta T_f = i K_f m = 2 \times K_f \times 0.1$, which is twice that of glucose ($i = 1$).', 'c_colligative_properties', 2, 'JEE Mains Prep', 'approved'),
('The boiling point of a solution is always _____ than the boiling point of the pure solvent.', 'Lower', 'Higher', 'The same', 'Unpredictable', 'option2', 'Adding a non-volatile solute lowers vapour pressure, requiring a higher temperature to reach atmospheric pressure (BPE).', 'c_colligative_properties', 2, 'JEE Mains Prep', 'approved'),
('The freezing point of a solution is always _____ than the freezing point of the pure solvent.', 'Higher', 'Lower', 'The same', 'Unpredictable', 'option2', 'Solute particles disrupt the crystal lattice formation, requiring a lower temperature to freeze (FPD).', 'c_colligative_properties', 2, 'JEE Mains Prep', 'approved'),
('The molar mass of a non-volatile solute can be determined from BPE using', '$M_s = K_b \times w_s \times 1000/(w_{solvent} \times \Delta T_b)$', '$M_s = \Delta T_b/(K_b \times m)$', '$M_s = K_b/\Delta T_b$', '$M_s = w_s \times \Delta T_b/K_b$', 'option1', '$\Delta T_b = K_b m = K_b \times (w_s/M_s)/(w_{solvent}/1000)$. Solving: $M_s = K_b w_s \times 1000/(w_{solvent} \Delta T_b)$.', 'c_colligative_properties', 2, 'JEE Mains Prep', 'approved'),
('An isotonic solution has', 'Maximum osmotic pressure', 'Zero osmotic pressure', 'The same osmotic pressure as another solution', 'The same boiling point as water', 'option3', 'Isotonic: equal osmotic pressure. No net flow of solvent between isotonic solutions separated by a membrane.', 'c_colligative_properties', 2, 'JEE Mains Prep', 'approved'),
('$3\;\text{g}$ of a non-electrolyte solute dissolved in $100\;\text{g}$ of water lowers the freezing point by $0.93\;\text{K}$ ($K_f = 1.86$). The molar mass of the solute is', '$30\;\text{g/mol}$', '$60\;\text{g/mol}$', '$120\;\text{g/mol}$', '$90\;\text{g/mol}$', 'option2', '$M = K_f \times w_s \times 1000/(w_{solvent} \times \Delta T_f) = 1.86 \times 3 \times 1000/(100 \times 0.93) = 5580/93 = 60\;\text{g/mol}$.', 'c_colligative_properties', 3, 'JEE Mains Prep', 'approved'),
('A $0.1\;\text{m}$ solution of K$_2$SO$_4$ (complete dissociation) has $\Delta T_f$ equal to', '$4 \times K_f \times 0.1$', '$2 \times K_f \times 0.1$', '$K_f \times 0.1$', '$3 \times K_f \times 0.1$', 'option4', 'K$_2$SO$_4 \to$ 2K$^+$ + SO$_4^{2-}$ (3 ions). $i = 3$. $\Delta T_f = 3 K_f \times 0.1$.', 'c_colligative_properties', 3, 'JEE Mains Prep', 'approved'),
('Among $0.1\;\text{m}$ solutions of glucose, NaCl, CaCl$_2$, and AlCl$_3$, the one with the lowest freezing point is', 'Glucose', 'NaCl', 'CaCl$_2$', 'AlCl$_3$', 'option4', '$i$ values: glucose (1), NaCl (2), CaCl$_2$ (3), AlCl$_3$ (4). Highest $i$ gives largest $\Delta T_f$ and lowest freezing point.', 'c_colligative_properties', 3, 'JEE Mains Prep', 'approved'),
('The ebullioscopic constant $K_b$ is related to the properties of the solvent by', '$K_b = T_b/\Delta_{vap}H$', '$K_b = \Delta_{vap}H/(RT_b^2)$', '$K_b = RT_b^2 M_{solvent}/(1000 \Delta_{vap}H)$', '$K_b = R/T_b$', 'option3', '$K_b = RT_b^2 M_1/(1000 \Delta_{vap}H)$ where $T_b$ is the boiling point and $M_1$ is the molar mass of the solvent.', 'c_colligative_properties', 3, 'JEE Mains Prep', 'approved'),
('A solution of $1.8\;\text{g}$ of a solute in $100\;\text{g}$ of benzene ($K_f = 5.12$) freezes at $4.85°\text{C}$ (pure benzene freezes at $5.5°\text{C}$). The molar mass of the solute is', '$71\;\text{g/mol}$', '$142\;\text{g/mol}$', '$284\;\text{g/mol}$', '$180\;\text{g/mol}$', 'option2', '$\Delta T_f = 5.5 - 4.85 = 0.65\;\text{K}$. $M = 5.12 \times 1.8 \times 1000/(100 \times 0.65) = 9216/65 = 141.8 \approx 142\;\text{g/mol}$.', 'c_colligative_properties', 3, 'JEE Mains Prep', 'approved'),
('Abnormal molar mass (lower than expected) is observed when the solute', 'Associates in solution', 'Dissociates in solution', 'Does not dissolve', 'Evaporates', 'option2', 'Dissociation increases the number of particles, increasing colligative effect, giving a lower calculated molar mass.', 'c_colligative_properties', 3, 'JEE Mains Prep', 'approved'),
('Abnormal molar mass (higher than expected) is observed when the solute', 'Dissociates in solution', 'Associates in solution', 'Is volatile', 'Reacts with solvent', 'option2', 'Association decreases the number of particles, decreasing colligative effect, giving a higher calculated molar mass (e.g., acetic acid in benzene).', 'c_colligative_properties', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_vant_hoff_factor (7 easy, 7 medium, 7 hard = 21)
-- van''t Hoff factor, abnormal molar mass
-- ============================================================
('The van''t Hoff factor $i$ is defined as', 'The ratio of observed colligative property to the calculated (normal) colligative property', 'The equilibrium constant', 'The rate constant', 'The mole fraction', 'option1', '$i = $ observed colligative property / calculated colligative property $= $ normal molar mass / observed molar mass.', 'c_vant_hoff_factor', 1, 'JEE Mains Prep', 'approved'),
('For a non-electrolyte (no dissociation or association), $i$ equals', '$0$', '$1$', '$2$', '$0.5$', 'option2', 'No change in number of particles: $i = 1$. Colligative properties are normal.', 'c_vant_hoff_factor', 1, 'JEE Mains Prep', 'approved'),
('For NaCl (complete dissociation), the van''t Hoff factor is', '$1$', '$2$', '$3$', '$0.5$', 'option2', 'NaCl $\to$ Na$^+$ + Cl$^-$. 1 formula unit gives 2 ions. $i = 2$.', 'c_vant_hoff_factor', 1, 'JEE Mains Prep', 'approved'),
('For CaCl$_2$ (complete dissociation), $i$ equals', '$1$', '$2$', '$3$', '$4$', 'option3', 'CaCl$_2 \to$ Ca$^{2+}$ + 2Cl$^-$. 3 ions per formula unit. $i = 3$.', 'c_vant_hoff_factor', 1, 'JEE Mains Prep', 'approved'),
('When $i > 1$, the solute undergoes', 'Association', 'Dissociation', 'No change', 'Evaporation', 'option2', '$i > 1$: more particles than expected $\rightarrow$ dissociation. $i < 1$: fewer particles $\rightarrow$ association.', 'c_vant_hoff_factor', 1, 'JEE Mains Prep', 'approved'),
('When $i < 1$, the solute undergoes', 'Dissociation', 'Association', 'Complete ionization', 'Sublimation', 'option2', '$i < 1$: fewer particles than expected. Molecules combine (associate) to form larger aggregates.', 'c_vant_hoff_factor', 1, 'JEE Mains Prep', 'approved'),
('The modified colligative property equations with the van''t Hoff factor are', '$\Delta T_f = K_f m + i$', '$\Delta T_b = K_b m/i$', '$\pi = MRT/i$', '$\Delta T_b = i K_b m$, $\Delta T_f = i K_f m$, $\pi = i MRT$', 'option4', 'All colligative properties are multiplied by $i$ to account for dissociation or association.', 'c_vant_hoff_factor', 1, 'JEE Mains Prep', 'approved'),
('For a weak electrolyte AB that dissociates as AB $\rightleftharpoons$ A$^+$ + B$^-$ with degree of dissociation $\alpha$, the van''t Hoff factor is', '$i = \alpha$', '$i = 1 - \alpha$', '$i = 2\alpha$', '$i = 1 + \alpha$', 'option4', 'Initially 1 mol AB. At equilibrium: $(1-\alpha)$ AB + $\alpha$ A$^+$ + $\alpha$ B$^-$ $= 1 + \alpha$ total. $i = 1 + \alpha$.', 'c_vant_hoff_factor', 2, 'JEE Mains Prep', 'approved'),
('For a solute that dimerizes (2A $\rightleftharpoons$ A$_2$) with degree of association $\alpha$, the van''t Hoff factor is', '$i = 1 - \alpha/2$', '$i = 1 + \alpha$', '$i = 1 - \alpha$', '$i = 2\alpha$', 'option1', 'Initially 1 mol A. At equilibrium: $(1-\alpha)$ A + $\alpha/2$ A$_2$ $= 1 - \alpha/2$ total. $i = 1 - \alpha/2$.', 'c_vant_hoff_factor', 2, 'JEE Mains Prep', 'approved'),
('A $0.1\;\text{m}$ NaCl solution ($i = 1.85$) has $\Delta T_f$ ($K_f = 1.86$) of', '$0.186\;\text{K}$', '$0.344\;\text{K}$', '$0.372\;\text{K}$', '$0.558\;\text{K}$', 'option2', '$\Delta T_f = i K_f m = 1.85 \times 1.86 \times 0.1 = 0.344\;\text{K}$.', 'c_vant_hoff_factor', 2, 'JEE Mains Prep', 'approved'),
('Acetic acid in benzene has $i = 0.5$. This indicates', 'Complete dissociation', 'Dimerization (association into pairs)', 'No change', 'Trimerization', 'option2', '$i = 0.5 < 1$: association. $i = 1 - \alpha/2 = 0.5$ gives $\alpha = 1$ (complete dimerization). 2CH$_3$COOH $\rightleftharpoons$ (CH$_3$COOH)$_2$.', 'c_vant_hoff_factor', 2, 'JEE Mains Prep', 'approved'),
('For K$_3$[Fe(CN)$_6$] (complete dissociation), $i$ equals', '$2$', '$3$', '$4$', '$5$', 'option3', 'K$_3$[Fe(CN)$_6$] $\to$ 3K$^+$ + [Fe(CN)$_6$]$^{3-}$. 4 ions total. $i = 4$.', 'c_vant_hoff_factor', 2, 'JEE Mains Prep', 'approved'),
('The degree of dissociation of a weak electrolyte A$_n$B$_m$ (giving $n$ A$^{m+}$ and $m$ B$^{n-}$) in terms of $i$ is', '$\alpha = (i + 1)/(n + m)$', '$\alpha = i - 1$', '$\alpha = (i - 1)/(n + m - 1)$', '$\alpha = i/(n + m)$', 'option3', 'General formula: $i = 1 + (n + m - 1)\alpha$. Solving: $\alpha = (i - 1)/(n + m - 1)$.', 'c_vant_hoff_factor', 2, 'JEE Mains Prep', 'approved'),
('If the observed molar mass of benzoic acid in benzene is $244\;\text{g/mol}$ (actual $M = 122$), the van''t Hoff factor is', '$1$', '$2$', '$0.5$', '$0.25$', 'option3', '$i = M_{normal}/M_{observed} = 122/244 = 0.5$. Benzoic acid dimerizes in benzene.', 'c_vant_hoff_factor', 2, 'JEE Mains Prep', 'approved'),
('A $0.01\;\text{M}$ solution of K$_2$SO$_4$ has an osmotic pressure of $0.66\;\text{atm}$ at $300\;\text{K}$. The van''t Hoff factor is ($R = 0.0821$)', '$2$', '$3$', '$1$', '$2.68$', 'option4', '$\pi = iMRT$. $0.66 = i \times 0.01 \times 0.0821 \times 300$. $i = 0.66/0.2463 = 2.68$.', 'c_vant_hoff_factor', 3, 'JEE Mains Prep', 'approved'),
('For a tribasic acid H$_3$A that is $60\%$ dissociated, the van''t Hoff factor is', '$4.0$', '$1.6$', '$3.4$', '$2.8$', 'option4', 'H$_3$A $\to$ 3H$^+$ + A$^{3-}$ ($n + m = 4$). $i = 1 + (4-1)(0.6) = 1 + 1.8 = 2.8$.', 'c_vant_hoff_factor', 3, 'JEE Mains Prep', 'approved'),
('The observed boiling point elevation of a $0.1\;\text{m}$ BaCl$_2$ solution is $0.145\;\text{K}$ ($K_b = 0.52$). The degree of dissociation is', '$0.90$', '$0.50$', '$1.0$', '$0.45$', 'option1', '$i = \Delta T_b/(K_b m) = 0.145/(0.52 \times 0.1) = 0.145/0.052 = 2.79$. BaCl$_2 \to$ Ba$^{2+}$ + 2Cl$^-$ ($n+m = 3$). $\alpha = (2.79 - 1)/(3 - 1) = 1.79/2 = 0.895 \approx 0.90$.', 'c_vant_hoff_factor', 3, 'JEE Mains Prep', 'approved'),
('For a solute that trimerizes (3A $\rightleftharpoons$ A$_3$) with $\alpha = 0.9$, the van''t Hoff factor is', '$0.1$', '$0.7$', '$1.0$', '$0.4$', 'option4', '$i = 1 - \alpha + \alpha/3 = 1 - 0.9 + 0.3 = 0.4$. Or: $i = 1 - \alpha(1 - 1/n) = 1 - 0.9(1 - 1/3) = 1 - 0.6 = 0.4$.', 'c_vant_hoff_factor', 3, 'JEE Mains Prep', 'approved'),
('If $i = 2.5$ for a salt A$_2$B$_3$ in solution, the degree of dissociation is', '$0.75$', '$0.5$', '$0.25$', '$0.375$', 'option4', 'A$_2$B$_3 \to$ 2A$^{3+}$ + 3B$^{2-}$ ($n + m = 5$). $i = 1 + (5-1)\alpha$. $2.5 = 1 + 4\alpha$. $\alpha = 1.5/4 = 0.375$.', 'c_vant_hoff_factor', 3, 'JEE Mains Prep', 'approved'),
('A $0.01\;\text{M}$ solution of a salt XY$_3$ shows $\Delta T_f = 0.062\;\text{K}$ ($K_f = 1.86$). The van''t Hoff factor and degree of dissociation are', '$i = 2.0$, $\alpha = 0.33$', '$i = 3.33$, $\alpha = 0.78$', '$i = 4.0$, $\alpha = 1.0$', '$i = 1.0$, $\alpha = 0$', 'option2', '$i = 0.062/(1.86 \times 0.01) = 3.33$. XY$_3 \to$ X$^{3+}$ + 3Y$^-$ ($n+m = 4$). $\alpha = (3.33 - 1)/3 = 0.78$.', 'c_vant_hoff_factor', 3, 'JEE Mains Prep', 'approved'),
('Two solutions — $0.1\;\text{m}$ urea and $0.05\;\text{m}$ NaCl (fully dissociated) — are separated by a semipermeable membrane. The net flow of water is', 'From NaCl to urea (NaCl has higher osmotic pressure)', 'From urea to NaCl', 'No flow (isotonic)', 'Cannot be determined', 'option3', 'Urea: $i \times m = 1 \times 0.1 = 0.1$. NaCl: $i \times m = 2 \times 0.05 = 0.1$. Equal effective molality $\rightarrow$ isotonic $\rightarrow$ no net flow.', 'c_vant_hoff_factor', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_dynamic_equilibrium (7 easy, 7 medium, 7 hard = 21)
-- Meaning of equilibrium, dynamic equilibrium concept
-- ============================================================
('At dynamic equilibrium', 'All reactions have stopped', 'The rates of forward and reverse reactions are equal', 'Only the forward reaction occurs', 'Concentrations are zero', 'option2', 'Dynamic equilibrium: both forward and reverse reactions continue, but at equal rates, so net concentrations remain constant.', 'c_dynamic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('At equilibrium, the concentrations of reactants and products', 'Are always equal', 'Are constant but not necessarily equal', 'Are always zero', 'Keep changing', 'option2', 'Equilibrium concentrations depend on $K$ and initial conditions. They are constant but generally not equal.', 'c_dynamic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('Equilibrium can be reached from', 'Only the forward direction', 'Only the reverse direction', 'Either direction (forward or reverse)', 'Neither direction', 'option3', 'The same equilibrium state is reached regardless of whether we start with reactants, products, or a mixture.', 'c_dynamic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('A system at equilibrium is disturbed by adding more reactant. According to Le Chatelier''s principle, the equilibrium will', 'Shift towards products', 'Shift towards reactants', 'Not change', 'Collapse', 'option1', 'Adding reactant increases $Q < K$, so the system shifts forward to restore equilibrium.', 'c_dynamic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('Equilibrium is possible only in', 'Open systems', 'Closed systems', 'Isolated systems only', 'Any system', 'option2', 'Chemical equilibrium requires a closed system (no exchange of matter) so that concentrations can stabilize.', 'c_dynamic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('The equilibrium constant $K$ for a reaction depends on', 'Catalyst', 'Concentration', 'Pressure', 'Temperature only', 'option4', '$K$ depends only on temperature. It is independent of initial concentrations, pressure changes, or catalysts.', 'c_dynamic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('A catalyst affects equilibrium by', 'Shifting it towards products', 'Shifting it towards reactants', 'Increasing $K$', 'Helping the system reach equilibrium faster without changing $K$', 'option4', 'A catalyst speeds up both forward and reverse reactions equally. It does not change $K$ or equilibrium position.', 'c_dynamic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('The reaction quotient $Q$ is calculated using', 'Equilibrium concentrations', 'Initial or any non-equilibrium concentrations', 'Only product concentrations', 'Only reactant concentrations', 'option2', '$Q$ has the same expression as $K$ but uses current (not necessarily equilibrium) concentrations.', 'c_dynamic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('If $Q < K$, the reaction will', 'Proceed in the forward direction', 'Proceed in the reverse direction', 'Be at equilibrium', 'Stop completely', 'option1', '$Q < K$: too few products relative to equilibrium. Reaction shifts forward to increase products.', 'c_dynamic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('If $Q > K$, the reaction will', 'Proceed in the forward direction', 'Proceed in the reverse direction', 'Be at equilibrium', 'Not occur', 'option2', '$Q > K$: too many products. Reaction shifts backward to consume products and form reactants.', 'c_dynamic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('For the reaction $2\text{SO}_2 + \text{O}_2 \rightleftharpoons 2\text{SO}_3$, increasing pressure at constant temperature', 'Shifts equilibrium towards SO$_3$ (fewer moles of gas)', 'Shifts towards SO$_2$ and O$_2$', 'Has no effect', 'Changes $K$', 'option1', '$\Delta n_g = 2 - 3 = -1$. Increasing pressure favours the side with fewer gas moles (products).', 'c_dynamic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('For the reaction N$_2$(g) + O$_2$(g) $\rightleftharpoons$ 2NO(g), a change in pressure at constant temperature', 'Shifts equilibrium right', 'Shifts equilibrium left', 'Has no effect on equilibrium ($\Delta n_g = 0$)', 'Changes $K$', 'option3', '$\Delta n_g = 2 - 2 = 0$. Equal moles on both sides, so pressure change has no effect.', 'c_dynamic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('Adding an inert gas at constant volume to an equilibrium mixture', 'Shifts equilibrium right', 'Shifts equilibrium left', 'Has no effect on equilibrium', 'Increases $K$', 'option3', 'At constant volume, adding inert gas increases total pressure but does not change partial pressures of reactants/products. No shift.', 'c_dynamic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('Adding an inert gas at constant pressure to a gaseous equilibrium', 'Has no effect', 'Shifts equilibrium towards the side with more moles of gas', 'Shifts towards fewer moles', 'Changes $K$', 'option2', 'At constant $P$, adding inert gas increases volume, effectively decreasing partial pressures. Equilibrium shifts towards more moles of gas.', 'c_dynamic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('For an exothermic reaction at equilibrium, increasing temperature', 'Shifts equilibrium towards reactants (reverse direction) and decreases $K$', 'Shifts towards products', 'Has no effect', 'Increases $K$', 'option1', 'Le Chatelier: heat is a "product" for exothermic reactions. Adding heat shifts equilibrium backward. $K$ decreases.', 'c_dynamic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('For an endothermic reaction, increasing temperature', 'Decreases $K$', 'Increases $K$ and shifts equilibrium towards products', 'Has no effect on $K$', 'Stops the reaction', 'option2', 'Heat is a "reactant" for endothermic reactions. Adding heat shifts forward. $K$ increases with $T$.', 'c_dynamic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('The equilibrium constant for the reverse reaction is', '$K^2$', '$K$', '$1/K$ (reciprocal of the forward $K$)', '$-K$', 'option3', 'If $K_{forward} = K$, then $K_{reverse} = 1/K$.', 'c_dynamic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('If a reaction is multiplied by a factor $n$, the new equilibrium constant is', '$K + n$', '$nK$', '$K/n$', '$K^n$', 'option4', 'Multiplying the equation by $n$ raises $K$ to the power $n$: $K_{new} = K^n$.', 'c_dynamic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('For two consecutive reactions with equilibrium constants $K_1$ and $K_2$, the overall $K$ is', '$K_1 + K_2$', '$K_1 \times K_2$', '$K_1/K_2$', '$K_1 - K_2$', 'option2', 'When reactions are added, their $K$ values multiply: $K_{overall} = K_1 \times K_2$.', 'c_dynamic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('At equilibrium, the Gibbs free energy of the reaction mixture is at a minimum. This means', '$\Delta G = 0$ but $\Delta G^\circ$ may be non-zero', '$\Delta G^\circ = 0$', '$\Delta H = 0$', '$\Delta S = 0$', 'option1', '$\Delta G = \Delta G^\circ + RT\ln Q$. At equilibrium: $Q = K$ and $\Delta G = 0$. But $\Delta G^\circ = -RT\ln K \neq 0$ unless $K = 1$.', 'c_dynamic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('The degree of dissociation of PCl$_5$ at equilibrium increases with', 'Increasing pressure', 'Decreasing pressure (or increasing volume)', 'Adding a catalyst', 'Decreasing temperature (exothermic dissociation)', 'option2', 'PCl$_5 \rightleftharpoons$ PCl$_3$ + Cl$_2$ ($\Delta n_g = +1$). Lower pressure favours more moles of gas, increasing dissociation.', 'c_dynamic_equilibrium', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_physical_equilibria (7 easy, 7 medium, 7 hard = 21)
-- Physical equilibria: solid-liquid, liquid-gas, Henry''s law
-- ============================================================
('An example of a physical equilibrium is', 'Combustion of methane', 'Ice $\rightleftharpoons$ water at $0°\text{C}$', 'Rusting of iron', 'Neutralization of acid and base', 'option2', 'Ice-water at $0°\text{C}$ is a physical equilibrium — both phases coexist with equal rates of melting and freezing.', 'c_physical_equilibria', 1, 'JEE Mains Prep', 'approved'),
('The vapour pressure of a liquid at a given temperature is', 'Zero', 'The atmospheric pressure', 'The pressure of the liquid', 'The pressure exerted by the vapour in equilibrium with the liquid', 'option4', 'At equilibrium, the rate of evaporation equals the rate of condensation. The pressure of the vapour at this point is the vapour pressure.', 'c_physical_equilibria', 1, 'JEE Mains Prep', 'approved'),
('A liquid boils when its vapour pressure equals', 'Zero', 'The atmospheric (external) pressure', 'Twice the atmospheric pressure', 'Half the atmospheric pressure', 'option2', 'Boiling occurs when vapour pressure $= P_{external}$. At $1\;\text{atm}$: normal boiling point.', 'c_physical_equilibria', 1, 'JEE Mains Prep', 'approved'),
('Henry''s law relates the solubility of a gas to', 'Temperature only', 'The partial pressure of the gas above the solution', 'The volume of the solution', 'The colour of the gas', 'option2', '$P = K_H x$ or $C = k_H P$. Solubility of a gas is directly proportional to its partial pressure.', 'c_physical_equilibria', 1, 'JEE Mains Prep', 'approved'),
('The solubility of gases in liquids generally _____ with increasing temperature.', 'Increases', 'Decreases', 'Remains constant', 'First increases then decreases', 'option2', 'Dissolution of gas is exothermic. By Le Chatelier, increasing $T$ shifts equilibrium towards less dissolution.', 'c_physical_equilibria', 1, 'JEE Mains Prep', 'approved'),
('The solid-liquid equilibrium at the melting point means', 'Only melting occurs', 'Only freezing occurs', 'Rates of melting and freezing are equal', 'No change occurs', 'option3', 'At the melting point, solid and liquid coexist. Rate of melting $=$ rate of freezing.', 'c_physical_equilibria', 1, 'JEE Mains Prep', 'approved'),
('The Clausius-Clapeyron equation relates', 'Vapour pressure to temperature', 'Concentration to time', 'Volume to pressure', 'Mass to energy', 'option1', '$\ln(P_2/P_1) = (\Delta_{vap}H/R)(1/T_1 - 1/T_2)$. Describes how vapour pressure changes with temperature.', 'c_physical_equilibria', 1, 'JEE Mains Prep', 'approved'),
('The vapour pressure of water at $100°\text{C}$ is', '$760\;\text{mmHg}$ ($1\;\text{atm}$)', '$380\;\text{mmHg}$', '$1520\;\text{mmHg}$', '$100\;\text{mmHg}$', 'option1', 'Water boils at $100°\text{C}$ when $P_{vap} = P_{atm} = 760\;\text{mmHg}$.', 'c_physical_equilibria', 2, 'JEE Mains Prep', 'approved'),
('At higher altitudes, water boils at a temperature _____ $100°\text{C}$ because', 'Above; pressure is higher', 'Below; atmospheric pressure is lower', 'Exactly at; altitude doesn''t matter', 'Below; gravity is weaker', 'option2', 'Lower atmospheric pressure at altitude means vapour pressure equals $P_{atm}$ at a lower temperature.', 'c_physical_equilibria', 2, 'JEE Mains Prep', 'approved'),
('A pressure cooker works by', 'Adding a catalyst', 'Decreasing the pressure', 'Increasing the pressure above the liquid, raising the boiling point', 'Removing water vapour', 'option3', 'Higher internal pressure $\rightarrow$ higher boiling point $\rightarrow$ food cooks at higher temperature $\rightarrow$ faster cooking.', 'c_physical_equilibria', 2, 'JEE Mains Prep', 'approved'),
('The distribution law (Nernst distribution law) states that at constant temperature, the ratio of concentrations of a solute in two immiscible solvents is', 'Constant ($K_D = C_1/C_2$)', 'Variable', 'Always $1$', 'Zero', 'option1', '$K_D = C_1/C_2$ (partition coefficient). Valid when the solute has the same molecular form in both solvents.', 'c_physical_equilibria', 2, 'JEE Mains Prep', 'approved'),
('The effect of pressure on the melting point of ice is', 'Melting point becomes $0\;\text{K}$', 'Increasing pressure raises the melting point', 'No effect', 'Increasing pressure lowers the melting point (anomalous behaviour of water)', 'option4', 'Water expands on freezing ($V_{solid} > V_{liquid}$). By Le Chatelier, increasing pressure favours the denser phase (liquid), lowering the melting point.', 'c_physical_equilibria', 2, 'JEE Mains Prep', 'approved'),
('The solubility of CO$_2$ in water increases when', 'Temperature increases', 'Pressure of CO$_2$ above the solution increases', 'The solution is heated', 'A catalyst is added', 'option2', 'Henry''s law: $C \propto P$. Higher partial pressure of CO$_2$ increases its solubility (carbonated drinks are pressurized).', 'c_physical_equilibria', 2, 'JEE Mains Prep', 'approved'),
('The phase rule ($F = C - P + 2$) for the ice-water-vapour triple point gives degrees of freedom', '$1$', '$0$ (invariant point)', '$2$', '$3$', 'option2', '$C = 1$ (water), $P = 3$ (solid, liquid, gas). $F = 1 - 3 + 2 = 0$. The triple point is fixed at $273.16\;\text{K}$, $611\;\text{Pa}$.', 'c_physical_equilibria', 2, 'JEE Mains Prep', 'approved'),
('Using the Clausius-Clapeyron equation, if $\Delta_{vap}H = 40.7\;\text{kJ/mol}$ for water, the vapour pressure at $110°\text{C}$ relative to $100°\text{C}$ ($760\;\text{mmHg}$) is approximately', '$1520\;\text{mmHg}$', '$760\;\text{mmHg}$', '$500\;\text{mmHg}$', '$1075\;\text{mmHg}$', 'option4', '$\ln(P_2/760) = (40700/8.314)(1/373 - 1/383) = 4894 \times 7.0 \times 10^{-5} = 0.343$. $P_2 = 760 \times e^{0.343} = 760 \times 1.41 = 1072 \approx 1075\;\text{mmHg}$.', 'c_physical_equilibria', 3, 'JEE Mains Prep', 'approved'),
('The phase diagram of water shows that the solid-liquid boundary has a negative slope because', 'Ice is less dense than water (volume decreases on melting)', 'Ice is denser than water', 'Water has no triple point', 'The diagram is wrong', 'option1', 'Negative slope: increasing pressure favours the denser phase (liquid water). This is anomalous — most substances have positive slope.', 'c_physical_equilibria', 3, 'JEE Mains Prep', 'approved'),
('The critical temperature of a gas is the temperature above which', 'The gas cannot be liquefied regardless of pressure', 'The gas always liquefies', 'The gas becomes a solid', 'The gas becomes a plasma', 'option1', 'Above $T_c$: no amount of pressure can liquefy the gas. The distinction between liquid and gas phases disappears.', 'c_physical_equilibria', 3, 'JEE Mains Prep', 'approved'),
('For the equilibrium H$_2$O(l) $\rightleftharpoons$ H$_2$O(g), the equilibrium constant $K_p$ equals', 'The vapour pressure of water at that temperature', '$1$', 'The atmospheric pressure', 'Zero', 'option1', 'For a pure liquid in equilibrium with its vapour: $K_p = P_{H_2O}$ (the vapour pressure at that temperature).', 'c_physical_equilibria', 3, 'JEE Mains Prep', 'approved'),
('The solubility of a gas that reacts with the solvent (e.g., NH$_3$ in water) is', 'Exactly as predicted', 'Lower than predicted', 'Much higher than predicted by Henry''s law', 'Zero', 'option3', 'NH$_3$ reacts with water (NH$_3$ + H$_2$O $\rightleftharpoons$ NH$_4^+$ + OH$^-$), removing dissolved NH$_3$ and driving more dissolution.', 'c_physical_equilibria', 3, 'JEE Mains Prep', 'approved'),
('The number of degrees of freedom for water at its normal boiling point ($100°\text{C}$, $1\;\text{atm}$) is', '$0$', '$1$', '$2$', '$3$', 'option2', '$C = 1$, $P = 2$ (liquid + gas). $F = 1 - 2 + 2 = 1$. One degree of freedom (either $T$ or $P$ can vary, but not independently).', 'c_physical_equilibria', 3, 'JEE Mains Prep', 'approved'),
('The supercritical fluid state exists', 'Below the triple point', 'Above both the critical temperature and critical pressure', 'Only at absolute zero', 'At the normal boiling point', 'option2', 'Supercritical fluids have properties intermediate between liquid and gas. Used in extraction (e.g., supercritical CO$_2$).', 'c_physical_equilibria', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_chemical_equilibrium_law (7 easy, 7 medium, 7 hard = 21)
-- Law of chemical equilibrium, K expressions, Le Chatelier
-- ============================================================
('For the reaction $a\text{A} + b\text{B} \rightleftharpoons c\text{C} + d\text{D}$, the equilibrium constant $K_c$ is', '$[\text{A}]^a[\text{B}]^b/([\text{C}]^c[\text{D}]^d)$', '$[\text{C}]^c[\text{D}]^d/([\text{A}]^a[\text{B}]^b)$', '$([\text{C}] + [\text{D}])/([\text{A}] + [\text{B}])$', '$[\text{C}][\text{D}]/([\text{A}][\text{B}])$', 'option2', '$K_c = [\text{C}]^c[\text{D}]^d/([\text{A}]^a[\text{B}]^b)$. Products over reactants, each raised to stoichiometric coefficients.', 'c_chemical_equilibrium_law', 1, 'JEE Mains Prep', 'approved'),
('Pure solids and pure liquids are excluded from the equilibrium expression because', 'They do not participate in the reaction', 'Their concentrations (activities) are constant and equal to $1$', 'They have zero concentration', 'They are always in excess', 'option2', 'The activity of a pure solid or liquid is $1$ by convention. Their concentrations do not change during the reaction.', 'c_chemical_equilibrium_law', 1, 'JEE Mains Prep', 'approved'),
('A large value of $K$ ($K \gg 1$) indicates that at equilibrium', 'The reaction has not occurred', 'Reactants predominate', 'Neither predominates', 'Products predominate', 'option4', '$K \gg 1$: numerator (products) $\gg$ denominator (reactants). Equilibrium lies far to the right.', 'c_chemical_equilibrium_law', 1, 'JEE Mains Prep', 'approved'),
('A small value of $K$ ($K \ll 1$) indicates that at equilibrium', 'Products predominate', 'Reactants predominate', 'The reaction is complete', 'Equilibrium cannot be reached', 'option2', '$K \ll 1$: reactants $\gg$ products. Equilibrium lies far to the left.', 'c_chemical_equilibrium_law', 1, 'JEE Mains Prep', 'approved'),
('Le Chatelier''s principle states that if a system at equilibrium is disturbed, it will', 'Shift to amplify the disturbance', 'Remain unchanged', 'Shift to counteract the disturbance and re-establish equilibrium', 'Decompose', 'option3', 'The system adjusts to partially oppose the change imposed on it.', 'c_chemical_equilibrium_law', 1, 'JEE Mains Prep', 'approved'),
('For the equilibrium CaCO$_3$(s) $\rightleftharpoons$ CaO(s) + CO$_2$(g), $K_p$ equals', '$1/P_{\text{CO}_2}$', '$P_{\text{CaO}} \times P_{\text{CO}_2}$', '$P_{\text{CO}_2}$', '$P_{\text{CO}_2}^2$', 'option3', 'Pure solids excluded. $K_p = P_{\text{CO}_2}$ only.', 'c_chemical_equilibrium_law', 1, 'JEE Mains Prep', 'approved'),
('The units of $K_c$ depend on', 'The stoichiometry of the reaction ($\Delta n$)', 'Temperature only', 'Pressure only', '$K_c$ is always dimensionless', 'option1', '$K_c$ has units of $(\text{mol/L})^{\Delta n}$ where $\Delta n = $ (sum of product coefficients) $-$ (sum of reactant coefficients).', 'c_chemical_equilibrium_law', 1, 'JEE Mains Prep', 'approved'),
('For N$_2$(g) + 3H$_2$(g) $\rightleftharpoons$ 2NH$_3$(g), if $[\text{N}_2] = 1$, $[\text{H}_2] = 3$, $[\text{NH}_3] = 2$ at equilibrium, $K_c$ is', '$9/2$', '$27/4$', '$2/9$', '$4/27$', 'option4', '$K_c = [NH_3]^2/([N_2][H_2]^3) = 4/(1 \times 27) = 4/27$.', 'c_chemical_equilibrium_law', 2, 'JEE Mains Prep', 'approved'),
('For the reaction H$_2$(g) + I$_2$(g) $\rightleftharpoons$ 2HI(g), $K_c = 50$ at $448°\text{C}$. If we start with $1\;\text{mol}$ each of H$_2$ and I$_2$ in a $1\;\text{L}$ vessel, the equilibrium concentration of HI is approximately', '$0.44\;\text{M}$', '$1.56\;\text{M}$', '$2.0\;\text{M}$', '$0.78\;\text{M}$', 'option2', 'Let $x$ mol of H$_2$ react. $K_c = (2x)^2/((1-x)(1-x)) = 4x^2/(1-x)^2 = 50$. $2x/(1-x) = \sqrt{50} = 7.07$. $2x = 7.07 - 7.07x$. $9.07x = 7.07$. $x = 0.78$. $[\text{HI}] = 2(0.78) = 1.56\;\text{M}$.', 'c_chemical_equilibrium_law', 2, 'JEE Mains Prep', 'approved'),
('For the reaction PCl$_5$(g) $\rightleftharpoons$ PCl$_3$(g) + Cl$_2$(g), if the degree of dissociation is $\alpha$ at total pressure $P$, then $K_p$ is', '$P\alpha$', '$\alpha P$', '$\alpha^2/(1 + \alpha)$', '$\alpha^2 P/(1 - \alpha^2)$', 'option4', 'At equilibrium: PCl$_5 = 1-\alpha$, PCl$_3 = \alpha$, Cl$_2 = \alpha$. Total $= 1 + \alpha$. $K_p = (\alpha/(1+\alpha))P \times (\alpha/(1+\alpha))P / ((1-\alpha)/(1+\alpha))P = \alpha^2 P/(1-\alpha^2)$.', 'c_chemical_equilibrium_law', 2, 'JEE Mains Prep', 'approved'),
('Removing a product from an equilibrium mixture causes the equilibrium to', 'Not change', 'Shift towards reactants', 'Shift towards more product formation (forward)', 'Increase $K$', 'option3', 'Removing product decreases $Q$ below $K$. System shifts forward to restore equilibrium.', 'c_chemical_equilibrium_law', 2, 'JEE Mains Prep', 'approved'),
('For the Haber process N$_2$ + 3H$_2$ $\rightleftharpoons$ 2NH$_3$ ($\Delta H = -92\;\text{kJ}$), the conditions that favour maximum NH$_3$ yield are', 'Low pressure and high temperature', 'High pressure and low temperature', 'Low pressure and low temperature', 'High pressure and high temperature', 'option2', 'High $P$: shifts towards fewer moles (products). Low $T$: favours exothermic direction (forward). But kinetically, low $T$ is slow, so a compromise ($\sim 500°\text{C}$, $200\;\text{atm}$, Fe catalyst) is used.', 'c_chemical_equilibrium_law', 2, 'JEE Mains Prep', 'approved'),
('The equilibrium constant $K_c$ for 2SO$_2$ + O$_2$ $\rightleftharpoons$ 2SO$_3$ is $K$. For SO$_3$ $\rightleftharpoons$ SO$_2$ + $\frac{1}{2}$O$_2$, $K_c$ is', '$1/\sqrt{K}$', '$\sqrt{K}$', '$1/K$', '$K^2$', 'option1', 'Reverse and halve: $K_{new} = (1/K)^{1/2} = 1/\sqrt{K}$.', 'c_chemical_equilibrium_law', 2, 'JEE Mains Prep', 'approved'),
('$K_p$ and $K_c$ are equal when', '$\Delta n_g = 1$', '$\Delta n_g = 0$', '$T = 0$', 'Always', 'option2', '$K_p = K_c(RT)^{\Delta n_g}$. When $\Delta n_g = 0$: $(RT)^0 = 1$, so $K_p = K_c$.', 'c_chemical_equilibrium_law', 2, 'JEE Mains Prep', 'approved'),
('For the reaction 2NO$_2$(g) $\rightleftharpoons$ N$_2$O$_4$(g), $K_p = 0.98\;\text{atm}^{-1}$ at $25°\text{C}$. If the total pressure is $2\;\text{atm}$, the degree of association is approximately', '$0.50$', '$0.82$', '$0.95$', '$0.33$', 'option2', 'Let $\alpha$ = degree of association. Start with 1 mol NO$_2$. At eq: NO$_2 = 1-\alpha$, N$_2$O$_4 = \alpha/2$. Total $= 1 - \alpha/2$. $K_p = ((\alpha/2)/(1-\alpha/2)) \times (1/P) / (((1-\alpha)/(1-\alpha/2))^2 \times P)$. This is complex. Using $K_p = x_{N_2O_4}/(x_{NO_2}^2 P) = (\alpha/2)/((1-\alpha)^2 P/(1-\alpha/2))$. Solving numerically with $P = 2$: $\alpha \approx 0.82$.', 'c_chemical_equilibrium_law', 3, 'JEE Mains Prep', 'approved'),
('The equilibrium constant for the dissolution of AgCl(s) in water is called', 'The formation constant', 'The dissociation constant', 'The solubility product ($K_{sp}$)', 'The rate constant', 'option3', 'AgCl(s) $\rightleftharpoons$ Ag$^+$(aq) + Cl$^-$(aq). $K_{sp} = [\text{Ag}^+][\text{Cl}^-]$ (pure solid excluded).', 'c_chemical_equilibrium_law', 3, 'JEE Mains Prep', 'approved'),
('For the Contact process: 2SO$_2$ + O$_2$ $\rightleftharpoons$ 2SO$_3$, $K_c = 4.0 \times 10^{24}$ at $25°\text{C}$. This extremely large $K$ means', 'The reaction barely proceeds', 'The reaction essentially goes to completion at $25°\text{C}$', 'Equilibrium favours reactants', '$K$ has no significance', 'option2', '$K \gg 1$: products overwhelmingly favoured. The reaction is thermodynamically very favourable at $25°\text{C}$ (but kinetically slow without catalyst).', 'c_chemical_equilibrium_law', 3, 'JEE Mains Prep', 'approved'),
('In a $1\;\text{L}$ vessel, $1\;\text{mol}$ PCl$_5$ is heated. At equilibrium, $0.4\;\text{mol}$ Cl$_2$ is formed. $K_c$ is', '$0.667$', '$0.4$', '$0.16$', '$0.267$', 'option4', 'PCl$_5 \rightleftharpoons$ PCl$_3$ + Cl$_2$. Cl$_2 = 0.4$, PCl$_3 = 0.4$, PCl$_5 = 0.6$. $K_c = 0.4 \times 0.4/0.6 = 0.16/0.6 = 0.267$.', 'c_chemical_equilibrium_law', 3, 'JEE Mains Prep', 'approved'),
('For the equilibrium N$_2$O$_4$(g) $\rightleftharpoons$ 2NO$_2$(g), $K_p = 0.5\;\text{atm}$ at a certain temperature. The percentage dissociation at $1\;\text{atm}$ total pressure is approximately', '$67\%$', '$50\%$', '$25\%$', '$33\%$', 'option4', '$K_p = 4\alpha^2 P/(1-\alpha^2)$. $0.5 = 4\alpha^2/(1-\alpha^2)$. $0.5 - 0.5\alpha^2 = 4\alpha^2$. $4.5\alpha^2 = 0.5$. $\alpha = \sqrt{1/9} = 1/3 = 33\%$.', 'c_chemical_equilibrium_law', 3, 'JEE Mains Prep', 'approved'),
('If the volume of the container is doubled for the equilibrium PCl$_5$(g) $\rightleftharpoons$ PCl$_3$(g) + Cl$_2$(g), the degree of dissociation', 'Increases', 'Decreases', 'Remains the same', 'Becomes zero', 'option1', 'Doubling volume halves pressure. $\Delta n_g = +1$: lower pressure favours more moles (forward). Dissociation increases.', 'c_chemical_equilibrium_law', 3, 'JEE Mains Prep', 'approved'),
('For the reaction A(g) $\rightleftharpoons$ 2B(g), $K_c = 4$ in a $1\;\text{L}$ vessel. If $1\;\text{mol}$ of A is taken initially, the equilibrium concentration of B is', '$2\;\text{M}$', '$\approx 1.24\;\text{M}$', '$0.5\;\text{M}$', '$4\;\text{M}$', 'option2', 'Let $x$ mol A dissociate. $K_c = (2x)^2/(1-x) = 4x^2/(1-x) = 4$. $4x^2 = 4 - 4x$. $x^2 + x - 1 = 0$. $x = (-1 + \sqrt{5})/2 = 0.618$. $[\text{B}] = 2(0.618) = 1.236 \approx 1.24\;\text{M}$.', 'c_chemical_equilibrium_law', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_ionic_equilibrium (7 easy, 7 medium, 7 hard = 21)
-- Weak/strong electrolytes, acids/bases (Arrhenius, BL, Lewis)
-- ============================================================
('A strong electrolyte is one that', 'Partially dissociates in water', 'Completely dissociates into ions in water', 'Does not dissolve in water', 'Conducts electricity only when solid', 'option2', 'Strong electrolytes (NaCl, HCl, NaOH) dissociate completely. Weak electrolytes (CH$_3$COOH, NH$_3$) dissociate partially.', 'c_ionic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('According to the Arrhenius theory, an acid is a substance that', 'Donates protons', 'Produces H$^+$ ions in aqueous solution', 'Accepts electron pairs', 'Produces OH$^-$ ions', 'option2', 'Arrhenius acid: produces H$^+$ (H$_3$O$^+$) in water. Arrhenius base: produces OH$^-$ in water.', 'c_ionic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('According to the Bronsted-Lowry theory, an acid is', 'An electron pair acceptor', 'A proton acceptor', 'An electron pair donor', 'A proton donor', 'option4', 'BL acid: donates H$^+$. BL base: accepts H$^+$. Broader than Arrhenius (works in non-aqueous solvents).', 'c_ionic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('A Lewis acid is', 'A proton donor', 'An electron pair acceptor', 'An electron pair donor', 'A proton acceptor', 'option2', 'Lewis acid: accepts an electron pair (e.g., BF$_3$, AlCl$_3$, H$^+$). Lewis base: donates an electron pair (e.g., NH$_3$, H$_2$O).', 'c_ionic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('The conjugate base of H$_2$O is', 'H$_3$O$^+$', 'OH$^-$', 'O$^{2-}$', 'H$_2$', 'option2', 'H$_2$O donates a proton to become OH$^-$ (its conjugate base). H$_2$O accepts a proton to become H$_3$O$^+$ (conjugate acid).', 'c_ionic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('The conjugate acid of NH$_3$ is', 'NH$_2^-$', 'NH$_4^+$', 'N$_2$H$_4$', 'NH$_2$OH', 'option2', 'NH$_3$ + H$^+ \to$ NH$_4^+$. NH$_4^+$ is the conjugate acid of NH$_3$.', 'c_ionic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('Water is amphoteric because it can act as', 'Only an acid', 'Only a base', 'Both an acid and a base', 'Neither acid nor base', 'option3', 'H$_2$O + H$_2$O $\rightleftharpoons$ H$_3$O$^+$ + OH$^-$. Water acts as both proton donor and acceptor.', 'c_ionic_equilibrium', 1, 'JEE Mains Prep', 'approved'),
('The dissociation constant $K_a$ of acetic acid ($K_a = 1.8 \times 10^{-5}$) indicates it is', 'A strong acid', 'A weak acid', 'A strong base', 'A neutral substance', 'option2', 'Small $K_a$ means very little dissociation. Acetic acid is a weak acid.', 'c_ionic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The relationship between $K_a$ and $K_b$ for a conjugate acid-base pair is', '$K_a + K_b = K_w$', '$K_a \times K_b = K_w$', '$K_a/K_b = K_w$', '$K_a \times K_b = 1$', 'option2', '$K_a \times K_b = K_w = 10^{-14}$ at $25°\text{C}$. Stronger acid $\rightarrow$ weaker conjugate base.', 'c_ionic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The degree of dissociation $\alpha$ of a weak acid (concentration $c$, dissociation constant $K_a$) is', '$\alpha = \sqrt{K_a/c}$ (for $\alpha \ll 1$)', '$\alpha = K_a \times c$', '$\alpha = c/K_a$', '$\alpha = K_a^2/c$', 'option1', 'Ostwald dilution law: $K_a = c\alpha^2/(1-\alpha) \approx c\alpha^2$ for $\alpha \ll 1$. $\alpha = \sqrt{K_a/c}$.', 'c_ionic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('Among HCl, H$_2$SO$_4$, CH$_3$COOH, and HCN, the weak acids are', 'HCl and H$_2$SO$_4$', 'CH$_3$COOH and HCN', 'All four', 'None', 'option2', 'HCl and H$_2$SO$_4$ are strong acids (complete dissociation). CH$_3$COOH and HCN are weak (partial dissociation).', 'c_ionic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('BF$_3$ is a Lewis acid because', 'It donates protons', 'It has an incomplete octet and can accept an electron pair', 'It produces H$^+$ in water', 'It has lone pairs', 'option2', 'B in BF$_3$ has only 6 electrons (electron-deficient). It accepts a lone pair from Lewis bases like NH$_3$.', 'c_ionic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The stronger the acid, the _____ its conjugate base.', 'Stronger', 'Weaker', 'Same strength', 'More acidic', 'option2', 'Strong acid $\rightarrow$ very weak conjugate base (e.g., HCl is strong, Cl$^-$ is a very weak base).', 'c_ionic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The levelling effect of water means that', 'Water has no effect on acid strength', 'All acids are weak in water', 'Water makes acids stronger', 'All strong acids appear equally strong in water because water is a strong enough base to deprotonate them completely', 'option4', 'In water, HCl, HBr, HI, HClO$_4$ all appear equally strong. To differentiate, use a weaker base solvent (e.g., glacial acetic acid).', 'c_ionic_equilibrium', 2, 'JEE Mains Prep', 'approved'),
('The $K_a$ of HF is $6.8 \times 10^{-4}$. The $K_b$ of F$^-$ is', '$6.8 \times 10^{-4}$', '$1.47 \times 10^{-11}$', '$1.47 \times 10^{-10}$', '$10^{-14}$', 'option2', '$K_b = K_w/K_a = 10^{-14}/(6.8 \times 10^{-4}) = 1.47 \times 10^{-11}$.', 'c_ionic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('The degree of dissociation of $0.1\;\text{M}$ acetic acid ($K_a = 1.8 \times 10^{-5}$) is', '$13.4\%$', '$1.34\%$', '$0.134\%$', '$4.24\%$', 'option2', '$\alpha = \sqrt{K_a/c} = \sqrt{1.8 \times 10^{-5}/0.1} = \sqrt{1.8 \times 10^{-4}} = 0.0134 = 1.34\%$.', 'c_ionic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('On dilution, the degree of dissociation of a weak electrolyte', 'Remains constant', 'Decreases', 'Increases', 'Becomes zero', 'option3', '$\alpha = \sqrt{K_a/c}$. As $c$ decreases (dilution), $\alpha$ increases. At infinite dilution, $\alpha \to 1$.', 'c_ionic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('Among H$_2$O, NH$_3$, and HF, the order of acid strength in the gas phase is', 'HF $>$ H$_2$O $>$ NH$_3$', 'NH$_3$ $>$ H$_2$O $>$ HF', 'H$_2$O $>$ HF $>$ NH$_3$', 'All are equally acidic', 'option1', 'In gas phase, acid strength follows bond strength and electronegativity: HF is the strongest acid (most electronegative atom).', 'c_ionic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('The $K_a$ values of H$_2$CO$_3$ are $K_{a1} = 4.3 \times 10^{-7}$ and $K_{a2} = 4.7 \times 10^{-11}$. The fact that $K_{a2} \ll K_{a1}$ is because', 'Removing a proton from the already negative HCO$_3^-$ ion is much harder', 'CO$_3^{2-}$ is more stable', 'H$_2$CO$_3$ is a strong acid', 'The second dissociation is exothermic', 'option1', 'The second proton must be removed from a negatively charged species (HCO$_3^-$), which strongly resists further deprotonation.', 'c_ionic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('AlCl$_3$ acts as a Lewis acid in Friedel-Crafts reactions because', 'It donates protons', 'Al has an empty orbital that can accept an electron pair from Cl$^-$', 'It produces OH$^-$', 'It is a Bronsted acid', 'option2', 'AlCl$_3$ + Cl$^-$ $\to$ AlCl$_4^-$. Al accepts the lone pair from Cl$^-$, generating the electrophile (e.g., R$^+$ or RCO$^+$).', 'c_ionic_equilibrium', 3, 'JEE Mains Prep', 'approved'),
('Hard and soft acids and bases (HSAB) theory predicts that', 'All acids prefer hard bases', 'Hard acids prefer soft bases', 'Hard acids prefer hard bases and soft acids prefer soft bases', 'HSAB has no predictive power', 'option3', 'HSAB (Pearson): hard-hard and soft-soft combinations are more stable. E.g., H$^+$ (hard) prefers F$^-$ (hard); Ag$^+$ (soft) prefers I$^-$ (soft).', 'c_ionic_equilibrium', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_ph_buffers_solubility (7 easy, 7 medium, 7 hard = 21)
-- pH, buffers, common ion effect, hydrolysis, Ksp
-- ============================================================
('The pH of a solution is defined as', '$\text{pH} = 1/[\text{H}^+]$', '$\text{pH} = \log[\text{H}^+]$', '$\text{pH} = [\text{H}^+]$', '$\text{pH} = -\log[\text{H}^+]$', 'option4', '$\text{pH} = -\log_{10}[\text{H}^+]$. Lower pH = more acidic. pH 7 = neutral at $25°\text{C}$.', 'c_ph_buffers_solubility', 1, 'JEE Mains Prep', 'approved'),
('The pH of pure water at $25°\text{C}$ is', '$0$', '$7$', '$14$', '$1$', 'option2', '$K_w = [\text{H}^+][\text{OH}^-] = 10^{-14}$. $[\text{H}^+] = 10^{-7}$. pH $= 7$.', 'c_ph_buffers_solubility', 1, 'JEE Mains Prep', 'approved'),
('A buffer solution resists changes in', 'Volume', 'pH upon addition of small amounts of acid or base', 'Temperature', 'Colour', 'option2', 'Buffers maintain nearly constant pH. Acidic buffer: weak acid + its salt. Basic buffer: weak base + its salt.', 'c_ph_buffers_solubility', 1, 'JEE Mains Prep', 'approved'),
('The common ion effect causes the solubility of a sparingly soluble salt to', 'Increase', 'Decrease', 'Remain the same', 'Become infinite', 'option2', 'Adding a common ion shifts the dissolution equilibrium backward (Le Chatelier), decreasing solubility.', 'c_ph_buffers_solubility', 1, 'JEE Mains Prep', 'approved'),
('The solubility product ($K_{sp}$) of AgCl is $1.8 \times 10^{-10}$. This means', 'AgCl is very soluble', 'AgCl is sparingly soluble', 'AgCl does not dissolve at all', 'AgCl is a strong electrolyte', 'option2', 'Very small $K_{sp}$ indicates very low solubility. $[\text{Ag}^+][\text{Cl}^-] = 1.8 \times 10^{-10}$ at saturation.', 'c_ph_buffers_solubility', 1, 'JEE Mains Prep', 'approved'),
('The pH of $0.01\;\text{M}$ HCl (strong acid) is', '$1$', '$2$', '$3$', '$0$', 'option2', 'HCl fully dissociates: $[\text{H}^+] = 0.01 = 10^{-2}$. pH $= 2$.', 'c_ph_buffers_solubility', 1, 'JEE Mains Prep', 'approved'),
('The pH of $0.1\;\text{M}$ NaOH (strong base) is', '$1$', '$13$', '$7$', '$14$', 'option2', '$[\text{OH}^-] = 0.1$. pOH $= 1$. pH $= 14 - 1 = 13$.', 'c_ph_buffers_solubility', 1, 'JEE Mains Prep', 'approved'),
('The Henderson-Hasselbalch equation for an acidic buffer is', '$\text{pH} = \text{p}K_a + \log([\text{salt}]/[\text{acid}])$', '$\text{pH} = \text{p}K_a - \log([\text{salt}]/[\text{acid}])$', '$\text{pH} = \text{p}K_a + \log([\text{acid}]/[\text{salt}])$', '$\text{pH} = \text{p}K_b + \log([\text{salt}]/[\text{base}])$', 'option1', '$\text{pH} = \text{p}K_a + \log([\text{A}^-]/[\text{HA}])$. When $[\text{salt}] = [\text{acid}]$: pH $= \text{p}K_a$.', 'c_ph_buffers_solubility', 2, 'JEE Mains Prep', 'approved'),
('The pH of a buffer containing $0.1\;\text{M}$ CH$_3$COOH and $0.1\;\text{M}$ CH$_3$COONa ($\text{p}K_a = 4.74$) is', '$2.37$', '$7.0$', '$9.26$', '$4.74$', 'option4', '$\text{pH} = \text{p}K_a + \log(0.1/0.1) = 4.74 + 0 = 4.74$.', 'c_ph_buffers_solubility', 2, 'JEE Mains Prep', 'approved'),
('The solubility of AgCl ($K_{sp} = 1.8 \times 10^{-10}$) in pure water is', '$1.8 \times 10^{-10}\;\text{M}$', '$1.34 \times 10^{-5}\;\text{M}$', '$1.8 \times 10^{-5}\;\text{M}$', '$0.9 \times 10^{-5}\;\text{M}$', 'option2', 'AgCl $\to$ Ag$^+$ + Cl$^-$. $s^2 = K_{sp}$. $s = \sqrt{1.8 \times 10^{-10}} = 1.34 \times 10^{-5}\;\text{M}$.', 'c_ph_buffers_solubility', 2, 'JEE Mains Prep', 'approved'),
('The pH of $0.1\;\text{M}$ acetic acid ($K_a = 1.8 \times 10^{-5}$) is approximately', '$2.87$', '$4.74$', '$1.0$', '$5.0$', 'option1', '$[\text{H}^+] = \sqrt{K_a \times c} = \sqrt{1.8 \times 10^{-5} \times 0.1} = \sqrt{1.8 \times 10^{-6}} = 1.34 \times 10^{-3}$. pH $= 2.87$.', 'c_ph_buffers_solubility', 2, 'JEE Mains Prep', 'approved'),
('Hydrolysis of the salt of a strong acid and weak base (e.g., NH$_4$Cl) gives a solution that is', 'Neutral (pH $= 7$)', 'Basic (pH $> 7$)', 'Acidic (pH $< 7$)', 'Depends on concentration', 'option3', 'NH$_4^+$ hydrolyzes: NH$_4^+$ + H$_2$O $\rightleftharpoons$ NH$_3$ + H$_3$O$^+$. Produces H$^+$, making solution acidic.', 'c_ph_buffers_solubility', 2, 'JEE Mains Prep', 'approved'),
('Hydrolysis of the salt of a weak acid and strong base (e.g., CH$_3$COONa) gives a solution that is', 'Acidic', 'Basic (pH $> 7$)', 'Neutral', 'Strongly acidic', 'option2', 'CH$_3$COO$^-$ + H$_2$O $\rightleftharpoons$ CH$_3$COOH + OH$^-$. Produces OH$^-$, making solution basic.', 'c_ph_buffers_solubility', 2, 'JEE Mains Prep', 'approved'),
('The pH of a salt of strong acid and strong base (e.g., NaCl) is', '$< 7$', '$> 7$', '$= 7$', 'Variable', 'option3', 'Neither Na$^+$ nor Cl$^-$ hydrolyzes. Solution is neutral, pH $= 7$.', 'c_ph_buffers_solubility', 2, 'JEE Mains Prep', 'approved'),
('The solubility of PbCl$_2$ ($K_{sp} = 1.6 \times 10^{-5}$) in pure water is', '$1.6 \times 10^{-2}\;\text{M}$', '$2.0 \times 10^{-2}\;\text{M}$', '$1.0 \times 10^{-2}\;\text{M}$', '$4.0 \times 10^{-2}\;\text{M}$', 'option1', 'PbCl$_2 \to$ Pb$^{2+}$ + 2Cl$^-$. $K_{sp} = s(2s)^2 = 4s^3$. $s = (K_{sp}/4)^{1/3} = (4 \times 10^{-6})^{1/3} = 1.59 \times 10^{-2}\;\text{M}$.', 'c_ph_buffers_solubility', 3, 'JEE Mains Prep', 'approved'),
('A buffer of pH $5.0$ can be prepared using acetic acid ($\text{p}K_a = 4.74$) and sodium acetate in the ratio $[\text{salt}]/[\text{acid}]$ of', '$1.82$', '$0.55$', '$1.0$', '$10$', 'option1', '$5.0 = 4.74 + \log([\text{salt}]/[\text{acid}])$. $\log([\text{salt}]/[\text{acid}]) = 0.26$. Ratio $= 10^{0.26} = 1.82$.', 'c_ph_buffers_solubility', 3, 'JEE Mains Prep', 'approved'),
('The pH of $0.1\;\text{M}$ NH$_4$Cl ($K_b$ of NH$_3 = 1.8 \times 10^{-5}$) is approximately', '$4.74$', '$8.87$', '$7.0$', '$5.13$', 'option4', '$K_h = K_w/K_b = 10^{-14}/(1.8 \times 10^{-5}) = 5.56 \times 10^{-10}$. $[\text{H}^+] = \sqrt{K_h \times c} = \sqrt{5.56 \times 10^{-11}} = 7.45 \times 10^{-6}$. pH $= 5.13$.', 'c_ph_buffers_solubility', 3, 'JEE Mains Prep', 'approved'),
('Will a precipitate of AgCl form if $0.001\;\text{M}$ AgNO$_3$ is mixed with $0.001\;\text{M}$ NaCl? ($K_{sp}$ of AgCl $= 1.8 \times 10^{-10}$)', 'No, because $Q < K_{sp}$', 'Yes, because the ionic product $Q > K_{sp}$', 'Cannot be determined', 'Only at high temperature', 'option2', 'After mixing (equal volumes): $[\text{Ag}^+] = [\text{Cl}^-] = 0.0005\;\text{M}$. $Q = 0.0005^2 = 2.5 \times 10^{-7} \gg K_{sp}$. Precipitate forms.', 'c_ph_buffers_solubility', 3, 'JEE Mains Prep', 'approved'),
('The solubility of Ag$_2$CrO$_4$ ($K_{sp} = 1.1 \times 10^{-12}$) in $0.1\;\text{M}$ AgNO$_3$ is approximately', '$6.5 \times 10^{-5}\;\text{M}$', '$1.1 \times 10^{-10}\;\text{M}$', '$1.1 \times 10^{-12}\;\text{M}$', '$1.05 \times 10^{-4}\;\text{M}$', 'option2', 'Ag$_2$CrO$_4 \to$ 2Ag$^+$ + CrO$_4^{2-}$. In $0.1\;\text{M}$ AgNO$_3$: $[\text{Ag}^+] \approx 0.1$. $K_{sp} = (0.1)^2 \times s$. $s = 1.1 \times 10^{-12}/0.01 = 1.1 \times 10^{-10}\;\text{M}$. Drastically reduced by common ion.', 'c_ph_buffers_solubility', 3, 'JEE Mains Prep', 'approved'),
('The pH of a solution obtained by mixing $50\;\text{mL}$ of $0.1\;\text{M}$ HCl with $50\;\text{mL}$ of $0.1\;\text{M}$ NaOH is', '$7$', '$1$', '$13$', '$0$', 'option1', 'Equal moles of strong acid and strong base: complete neutralization. Resulting solution is NaCl (neutral). pH $= 7$.', 'c_ph_buffers_solubility', 3, 'JEE Mains Prep', 'approved'),
('The pH of a solution obtained by mixing $50\;\text{mL}$ of $0.1\;\text{M}$ HCl with $30\;\text{mL}$ of $0.1\;\text{M}$ NaOH is', '$1.9$', '$2.0$', '$1.6$', '$7.0$', 'option3', 'Excess HCl $= 0.005 - 0.003 = 0.002\;\text{mol}$ in $80\;\text{mL}$. $[\text{H}^+] = 0.002/0.08 = 0.025\;\text{M}$. pH $= -\log(0.025) = 1.60$.', 'c_ph_buffers_solubility', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_redox_oxidation_number (7 easy, 7 medium, 7 hard = 21)
-- Oxidation/reduction, redox reactions, oxidation number
-- ============================================================
('Oxidation is defined as', 'Gain of electrons', 'Loss of electrons (or increase in oxidation number)', 'Gain of protons', 'Loss of oxygen', 'option2', 'Oxidation: loss of electrons, increase in oxidation state. Reduction: gain of electrons, decrease in oxidation state.', 'c_redox_oxidation_number', 1, 'JEE Mains Prep', 'approved'),
('Reduction is defined as', 'Loss of electrons', 'Gain of electrons (or decrease in oxidation number)', 'Loss of hydrogen', 'Gain of oxygen', 'option2', 'Reduction: gain of electrons. The substance that gets reduced is the oxidizing agent.', 'c_redox_oxidation_number', 1, 'JEE Mains Prep', 'approved'),
('The oxidation number of oxygen in most compounds is', '$+2$', '$-1$', '$-2$', '$0$', 'option3', 'O is $-2$ in most compounds. Exceptions: peroxides ($-1$), OF$_2$ ($+2$), superoxides ($-1/2$).', 'c_redox_oxidation_number', 1, 'JEE Mains Prep', 'approved'),
('The oxidation number of hydrogen in most compounds is', '$-1$', '$+1$', '$0$', '$+2$', 'option2', 'H is $+1$ in most compounds. Exception: metal hydrides (NaH, CaH$_2$) where H is $-1$.', 'c_redox_oxidation_number', 1, 'JEE Mains Prep', 'approved'),
('In a redox reaction, the substance that gets oxidized is called', 'The oxidizing agent', 'The reducing agent', 'The catalyst', 'The product', 'option2', 'The substance oxidized (loses electrons) is the reducing agent. It reduces the other substance.', 'c_redox_oxidation_number', 1, 'JEE Mains Prep', 'approved'),
('The oxidation number of an element in its free (uncombined) state is', '$+1$', '$-1$', '$0$', 'Variable', 'option3', 'Free elements: O$_2$, N$_2$, Fe, Na all have oxidation number $= 0$.', 'c_redox_oxidation_number', 1, 'JEE Mains Prep', 'approved'),
('A disproportionation reaction is one where', 'Only oxidation occurs', 'Two different elements are oxidized', 'No change in oxidation state occurs', 'The same element is both oxidized and reduced', 'option4', 'Example: 2H$_2$O$_2 \to$ 2H$_2$O + O$_2$. Oxygen in H$_2$O$_2$ ($-1$) is both oxidized to $0$ and reduced to $-2$.', 'c_redox_oxidation_number', 1, 'JEE Mains Prep', 'approved'),
('The oxidation number of Mn in KMnO$_4$ is', '$+4$', '$+6$', '$+7$', '$+2$', 'option3', 'K $(+1)$ + Mn $(x)$ + 4O $(-2)$ $= 0$. $1 + x - 8 = 0$. $x = +7$.', 'c_redox_oxidation_number', 2, 'JEE Mains Prep', 'approved'),
('The oxidation number of Cr in K$_2$Cr$_2$O$_7$ is', '$+3$', '$+6$', '$+7$', '$+12$', 'option2', '2K $(+1)$ + 2Cr $(x)$ + 7O $(-2)$ $= 0$. $2 + 2x - 14 = 0$. $x = +6$.', 'c_redox_oxidation_number', 2, 'JEE Mains Prep', 'approved'),
('In the reaction Zn + CuSO$_4 \to$ ZnSO$_4$ + Cu, the reducing agent is', 'Cu', 'Zn', 'SO$_4^{2-}$', 'CuSO$_4$', 'option2', 'Zn is oxidized ($0 \to +2$): it is the reducing agent. Cu$^{2+}$ is reduced ($+2 \to 0$): it is the oxidizing agent.', 'c_redox_oxidation_number', 2, 'JEE Mains Prep', 'approved'),
('The oxidation number of S in Na$_2$S$_2$O$_3$ (sodium thiosulfate) is', '$+4$', '$+2$', '$+6$', '$-2$', 'option2', '2Na $(+1)$ + 2S $(x)$ + 3O $(-2)$ $= 0$. $2 + 2x - 6 = 0$. $x = +2$.', 'c_redox_oxidation_number', 2, 'JEE Mains Prep', 'approved'),
('In the half-reaction MnO$_4^-$ + 8H$^+$ + 5e$^- \to$ Mn$^{2+}$ + 4H$_2$O, the $n$-factor of KMnO$_4$ in acidic medium is', '$3$', '$5$', '$2$', '$7$', 'option2', 'Mn goes from $+7$ to $+2$: change of 5 electrons per Mn atom. $n$-factor $= 5$.', 'c_redox_oxidation_number', 2, 'JEE Mains Prep', 'approved'),
('Which of the following is a comproportionation reaction?', '2H$_2$O$_2 \to$ 2H$_2$O + O$_2$', 'Ag$^+$ + Ag$^{3+} \to$ 2Ag$^{2+}$', 'Zn + Cu$^{2+} \to$ Zn$^{2+}$ + Cu', 'Fe + Cl$_2 \to$ FeCl$_2$', 'option2', 'Comproportionation: two different oxidation states of the same element combine to form one intermediate state. Opposite of disproportionation.', 'c_redox_oxidation_number', 2, 'JEE Mains Prep', 'approved'),
('The equivalent mass of KMnO$_4$ in acidic medium ($n$-factor $= 5$) is', '$158/2 = 79$', '$158$', '$158/3 = 52.7$', '$158/5 = 31.6$', 'option4', 'Equivalent mass $= M/n = 158/5 = 31.6\;\text{g/eq}$.', 'c_redox_oxidation_number', 2, 'JEE Mains Prep', 'approved'),
('In the reaction 3Cu + 8HNO$_3$(dilute) $\to$ 3Cu(NO$_3$)$_2$ + 2NO + 4H$_2$O, the oxidizing agent is', 'Cu', 'HNO$_3$', 'NO', 'H$_2$O', 'option2', 'N in HNO$_3$ ($+5$) is reduced to N in NO ($+2$). HNO$_3$ is the oxidizing agent.', 'c_redox_oxidation_number', 3, 'JEE Mains Prep', 'approved'),
('The oxidation number of Fe in Fe$_3$O$_4$ is', '$+2$ only', '$+3$ only', '$+8/3$ (average of $+2$ and $+3$)', '$+4$', 'option3', 'Fe$_3$O$_4$ = FeO$\cdot$Fe$_2$O$_3$. One Fe is $+2$, two are $+3$. Average $= (2 + 3 + 3)/3 = 8/3$.', 'c_redox_oxidation_number', 3, 'JEE Mains Prep', 'approved'),
('Balance the reaction: MnO$_4^-$ + C$_2$O$_4^{2-}$ + H$^+ \to$ Mn$^{2+}$ + CO$_2$ + H$_2$O. The coefficient of MnO$_4^-$ is', '$5$', '$2$', '$3$', '$1$', 'option2', 'MnO$_4^-$: 5e$^-$ gained. C$_2$O$_4^{2-}$: 2e$^-$ lost. LCM $= 10$. 2MnO$_4^-$ + 5C$_2$O$_4^{2-}$ + 16H$^+ \to$ 2Mn$^{2+}$ + 10CO$_2$ + 8H$_2$O.', 'c_redox_oxidation_number', 3, 'JEE Mains Prep', 'approved'),
('The $n$-factor of K$_2$Cr$_2$O$_7$ in acidic medium is', '$3$', '$6$', '$2$', '$12$', 'option2', 'Cr$_2$O$_7^{2-}$ + 14H$^+$ + 6e$^- \to$ 2Cr$^{3+}$ + 7H$_2$O. 6 electrons per formula unit. $n = 6$.', 'c_redox_oxidation_number', 3, 'JEE Mains Prep', 'approved'),
('In the reaction 2KMnO$_4$ + 3H$_2$SO$_4$ + 5H$_2$C$_2$O$_4 \to$ K$_2$SO$_4$ + 2MnSO$_4$ + 10CO$_2$ + 8H$_2$O, the molar ratio of KMnO$_4$ to H$_2$C$_2$O$_4$ is', '$1:1$', '$5:2$', '$2:5$', '$1:5$', 'option3', 'From the balanced equation: 2 mol KMnO$_4$ reacts with 5 mol oxalic acid.', 'c_redox_oxidation_number', 3, 'JEE Mains Prep', 'approved'),
('The oxidation states of S in H$_2$SO$_4$, H$_2$SO$_3$, H$_2$S, and Na$_2$S$_2$O$_3$ are respectively', '$+4, +6, -2, +2$', '$+6, +4, -2, +6$', '$+6, +4, -2, +2$', '$+6, +4, +2, -2$', 'option3', 'H$_2$SO$_4$: $+6$. H$_2$SO$_3$: $+4$. H$_2$S: $-2$. Na$_2$S$_2$O$_3$: $+2$.', 'c_redox_oxidation_number', 3, 'JEE Mains Prep', 'approved'),
('The number of moles of KMnO$_4$ required to oxidize $1\;\text{mol}$ of Fe$^{2+}$ to Fe$^{3+}$ in acidic medium is', '$1$', '$1/5$', '$5$', '$2/5$', 'option2', 'Fe$^{2+} \to$ Fe$^{3+}$: 1e$^-$ lost. KMnO$_4$: 5e$^-$ gained. 1 mol KMnO$_4$ oxidizes 5 mol Fe$^{2+}$. So $1/5$ mol KMnO$_4$ per mol Fe$^{2+}$.', 'c_redox_oxidation_number', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_conductance (7 easy, 7 medium, 7 hard = 21)
-- Electrolytic/metallic conduction, molar conductivity, Kohlrausch
-- ============================================================
('Electrolytic conduction is due to the movement of', 'Electrons', 'Ions', 'Protons only', 'Neutrons', 'option2', 'In electrolytes, current is carried by the movement of cations towards cathode and anions towards anode.', 'c_conductance', 1, 'JEE Mains Prep', 'approved'),
('Metallic conduction is due to the movement of', 'Ions', 'Free (delocalized) electrons', 'Protons', 'Molecules', 'option2', 'In metals, the electron sea carries current. No chemical change occurs during metallic conduction.', 'c_conductance', 1, 'JEE Mains Prep', 'approved'),
('The conductivity ($\kappa$) of an electrolyte solution is the reciprocal of', 'Conductance', 'Resistivity', 'Resistance', 'Molar conductivity', 'option2', '$\kappa = 1/\rho$ where $\rho$ is resistivity. $\kappa$ has units of S/cm or S/m.', 'c_conductance', 1, 'JEE Mains Prep', 'approved'),
('Molar conductivity ($\Lambda_m$) is defined as', '$\Lambda_m = \kappa/c$ (conductivity divided by molar concentration)', 'Conductivity times concentration', 'Resistance times volume', 'Current divided by voltage', 'option1', '$\Lambda_m = \kappa \times 1000/c$ (in S$\cdot$cm$^2$/mol) where $c$ is in mol/L.', 'c_conductance', 1, 'JEE Mains Prep', 'approved'),
('On dilution, the molar conductivity of an electrolyte', 'Decreases', 'Increases', 'Remains constant', 'Becomes zero', 'option2', 'Dilution increases the degree of dissociation (for weak electrolytes) and reduces interionic interactions (for strong), increasing $\Lambda_m$.', 'c_conductance', 1, 'JEE Mains Prep', 'approved'),
('Kohlrausch''s law states that at infinite dilution, the molar conductivity of an electrolyte is', 'Zero', 'The sum of the individual ionic conductivities of its cation and anion', 'Equal to the conductivity', 'Infinite', 'option2', '$\Lambda_m^\circ = \nu_+ \lambda_+^\circ + \nu_- \lambda_-^\circ$ where $\nu$ are stoichiometric coefficients and $\lambda^\circ$ are limiting ionic conductivities.', 'c_conductance', 1, 'JEE Mains Prep', 'approved'),
('The conductivity of electrolytic solutions _____ with increasing temperature.', 'Decreases', 'Increases', 'Remains constant', 'First increases then decreases', 'option2', 'Higher temperature increases ionic mobility and degree of dissociation, increasing conductivity. (Opposite of metals.)','c_conductance', 1, 'JEE Mains Prep', 'approved'),
('The cell constant of a conductivity cell is', '$1/(l \times A)$', '$A/l$', '$l \times A$', '$l/A$ (length/area)', 'option4', 'Cell constant $G^* = l/A$ (cm$^{-1}$). $\kappa = G^* \times$ conductance.', 'c_conductance', 2, 'JEE Mains Prep', 'approved'),
('For strong electrolytes, the variation of $\Lambda_m$ with concentration follows', '$\Lambda_m = \Lambda_m^\circ - A\sqrt{c}$ (Debye-Huckel-Onsager equation)', '$\Lambda_m = \Lambda_m^\circ + Ac$', '$\Lambda_m = \Lambda_m^\circ/c$', '$\Lambda_m$ is constant', 'option1', 'Strong electrolytes: $\Lambda_m$ decreases linearly with $\sqrt{c}$. Extrapolation to $c = 0$ gives $\Lambda_m^\circ$.', 'c_conductance', 2, 'JEE Mains Prep', 'approved'),
('For weak electrolytes, $\Lambda_m^\circ$ cannot be obtained by extrapolation because', 'The curve is linear', '$\Lambda_m$ is constant', 'Weak electrolytes do not conduct', 'The $\Lambda_m$ vs $\sqrt{c}$ curve rises steeply at low concentrations', 'option4', 'Weak electrolytes show a sharp increase in $\Lambda_m$ at very low $c$ (due to increasing dissociation), making extrapolation unreliable. Kohlrausch''s law is used instead.', 'c_conductance', 2, 'JEE Mains Prep', 'approved'),
('The degree of dissociation of a weak electrolyte can be calculated from conductivity as', '$\alpha = \Lambda_m^\circ/\Lambda_m$', '$\alpha = \Lambda_m/\Lambda_m^\circ$', '$\alpha = \Lambda_m \times \Lambda_m^\circ$', '$\alpha = 1 - \Lambda_m/\Lambda_m^\circ$', 'option2', '$\alpha = \Lambda_m/\Lambda_m^\circ$. At infinite dilution, $\alpha = 1$ and $\Lambda_m = \Lambda_m^\circ$.', 'c_conductance', 2, 'JEE Mains Prep', 'approved'),
('Using Kohlrausch''s law, $\Lambda_m^\circ$ of CH$_3$COOH can be calculated from', '$\Lambda_m^\circ(\text{CH}_3\text{COONa}) + \Lambda_m^\circ(\text{HCl}) - \Lambda_m^\circ(\text{NaCl})$', '$\Lambda_m^\circ(\text{CH}_3\text{COONa}) + \Lambda_m^\circ(\text{NaCl})$', '$\Lambda_m^\circ(\text{HCl}) - \Lambda_m^\circ(\text{NaCl})$', '$\Lambda_m^\circ(\text{CH}_3\text{COONa}) \times \Lambda_m^\circ(\text{HCl})$', 'option1', '$\Lambda_m^\circ(\text{CH}_3\text{COOH}) = \lambda^\circ(\text{CH}_3\text{COO}^-) + \lambda^\circ(\text{H}^+) = [\Lambda_m^\circ(\text{CH}_3\text{COONa}) - \lambda^\circ(\text{Na}^+)] + [\Lambda_m^\circ(\text{HCl}) - \lambda^\circ(\text{Cl}^-)] + \lambda^\circ(\text{Na}^+) + \lambda^\circ(\text{Cl}^-)$... Simplifies to the given expression.', 'c_conductance', 2, 'JEE Mains Prep', 'approved'),
('The transport number of an ion is', 'The resistance of the ion', 'The total current', 'The fraction of total current carried by that ion', 'The charge of the ion', 'option3', '$t_+ + t_- = 1$. Faster ions carry a larger fraction of the current.', 'c_conductance', 2, 'JEE Mains Prep', 'approved'),
('The ion with the highest limiting molar conductivity in aqueous solution is', 'Na$^+$', 'K$^+$', 'H$^+$', 'Li$^+$', 'option3', 'H$^+$ ($\lambda^\circ = 349.8\;\text{S}\cdot\text{cm}^2/\text{mol}$) has anomalously high conductivity due to the Grotthuss (proton hopping) mechanism.', 'c_conductance', 2, 'JEE Mains Prep', 'approved'),
('The $\Lambda_m^\circ$ of NaCl is $126.5$, NaOH is $248.1$, and HCl is $425.9\;\text{S}\cdot\text{cm}^2/\text{mol}$. The $\Lambda_m^\circ$ of NaOH is verified as', '$\lambda^\circ(\text{Na}^+) + \lambda^\circ(\text{OH}^-)$', '$\Lambda_m^\circ(\text{NaCl}) + \Lambda_m^\circ(\text{HCl})$', 'Cannot be calculated', '$\Lambda_m^\circ(\text{NaCl}) - \Lambda_m^\circ(\text{HCl})$', 'option1', '$\Lambda_m^\circ(\text{NaOH}) = \lambda^\circ(\text{Na}^+) + \lambda^\circ(\text{OH}^-)$. This is a direct application of Kohlrausch''s law.', 'c_conductance', 3, 'JEE Mains Prep', 'approved'),
('The $K_a$ of acetic acid can be determined from conductivity measurements using', '$K_a = c\alpha^2/(1-\alpha)$ where $\alpha = \Lambda_m/\Lambda_m^\circ$', '$K_a = \Lambda_m/c$', '$K_a = c/\Lambda_m$', '$K_a = \Lambda_m^\circ/c$', 'option1', 'Measure $\Lambda_m$ at concentration $c$. Calculate $\alpha = \Lambda_m/\Lambda_m^\circ$. Then $K_a = c\alpha^2/(1-\alpha)$.', 'c_conductance', 3, 'JEE Mains Prep', 'approved'),
('The molar conductivity of $0.001\;\text{M}$ acetic acid is $49.5\;\text{S}\cdot\text{cm}^2/\text{mol}$ and $\Lambda_m^\circ = 390.5$. The degree of dissociation is', '$7.89$', '$0.50$', '$0.013$', '$0.127$', 'option4', '$\alpha = 49.5/390.5 = 0.127 = 12.7\%$.', 'c_conductance', 3, 'JEE Mains Prep', 'approved'),
('OH$^-$ has the second highest ionic conductivity (after H$^+$) because', 'It also moves by a proton-transfer (Grotthuss) mechanism in reverse', 'It is very small', 'It has high charge', 'It does not move', 'option1', 'OH$^-$ ($\lambda^\circ = 198\;\text{S}\cdot\text{cm}^2/\text{mol}$) moves by proton hopping in reverse: water molecules pass protons to OH$^-$.', 'c_conductance', 3, 'JEE Mains Prep', 'approved'),
('The conductivity of a $0.02\;\text{M}$ KCl solution is $0.00277\;\text{S/cm}$. The molar conductivity is', '$138.5\;\text{S}\cdot\text{cm}^2/\text{mol}$', '$13.85\;\text{S}\cdot\text{cm}^2/\text{mol}$', '$1385\;\text{S}\cdot\text{cm}^2/\text{mol}$', '$0.1385\;\text{S}\cdot\text{cm}^2/\text{mol}$', 'option1', '$\Lambda_m = \kappa \times 1000/c = 0.00277 \times 1000/0.02 = 138.5\;\text{S}\cdot\text{cm}^2/\text{mol}$.', 'c_conductance', 3, 'JEE Mains Prep', 'approved'),
('Among Li$^+$, Na$^+$, K$^+$, and Cs$^+$, the order of ionic conductivity in aqueous solution is', 'Li$^+ >$ Na$^+ >$ K$^+ >$ Cs$^+$', 'Cs$^+ >$ K$^+ >$ Na$^+ >$ Li$^+$', 'All are equal', 'K$^+ >$ Na$^+ >$ Cs$^+ >$ Li$^+$', 'option2', 'Smaller bare ions have larger hydrated radii (more water molecules). Li$^+$ is most hydrated and slowest. Cs$^+$ is least hydrated and fastest.', 'c_conductance', 3, 'JEE Mains Prep', 'approved'),
('The Debye-Huckel-Onsager equation $\Lambda_m = \Lambda_m^\circ - (A + B\Lambda_m^\circ)\sqrt{c}$ accounts for', 'The decrease in molar conductivity of strong electrolytes due to interionic attractions', 'The increase in conductivity with dilution', 'Weak electrolyte dissociation', 'Temperature effects only', 'option1', 'The constants $A$ (electrophoretic effect) and $B$ (relaxation effect) quantify how interionic forces reduce ion mobility at finite concentrations.', 'c_conductance', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_electrochemical_cells (7 easy, 7 medium, 7 hard = 21)
-- Electrolytic/Galvanic cells, electrode potentials, emf
-- ============================================================
('In a galvanic (voltaic) cell, chemical energy is converted to', 'Heat energy', 'Electrical energy', 'Light energy', 'Mechanical energy', 'option2', 'Galvanic cells use spontaneous redox reactions to generate electricity. Electrolytic cells do the reverse.', 'c_electrochemical_cells', 1, 'JEE Mains Prep', 'approved'),
('In a galvanic cell, oxidation occurs at the', 'Cathode', 'Anode', 'Salt bridge', 'External wire', 'option2', 'Anode: oxidation (AN-OX). Cathode: reduction (RED-CAT). Electrons flow from anode to cathode externally.', 'c_electrochemical_cells', 1, 'JEE Mains Prep', 'approved'),
('The standard electrode potential is measured against', 'A copper electrode', 'The Standard Hydrogen Electrode (SHE), assigned $E^\circ = 0\;\text{V}$', 'A silver electrode', 'A platinum electrode in acid', 'option2', 'SHE: Pt | H$_2$(1 atm) | H$^+$(1 M). $E^\circ = 0.00\;\text{V}$ by convention.', 'c_electrochemical_cells', 1, 'JEE Mains Prep', 'approved'),
('The salt bridge in a galvanic cell', 'Allows electron flow', 'Maintains electrical neutrality by allowing ion flow between half-cells', 'Generates electricity', 'Stores energy', 'option2', 'The salt bridge (KCl or KNO$_3$ in agar) allows ion migration to prevent charge buildup, completing the circuit.', 'c_electrochemical_cells', 1, 'JEE Mains Prep', 'approved'),
('The EMF of a cell is', 'The resistance of the cell', 'The current through the cell', 'The potential difference between the two electrodes when no current flows', 'The charge stored', 'option3', '$E_{cell} = E_{cathode} - E_{anode}$. Measured under zero-current conditions (using a potentiometer).', 'c_electrochemical_cells', 1, 'JEE Mains Prep', 'approved'),
('In an electrolytic cell, the external source of electricity drives', 'A spontaneous reaction', 'A non-spontaneous reaction', 'No reaction', 'Only oxidation', 'option2', 'Electrolysis forces a non-spontaneous reaction ($\Delta G > 0$) using external electrical energy.', 'c_electrochemical_cells', 1, 'JEE Mains Prep', 'approved'),
('A more negative standard reduction potential means the species is', 'A stronger oxidizing agent', 'A stronger reducing agent', 'Inert', 'A weaker reducing agent', 'option2', 'More negative $E^\circ_{red}$: harder to reduce, easier to oxidize. The metal is a stronger reducing agent (e.g., Li: $-3.04\;\text{V}$).', 'c_electrochemical_cells', 1, 'JEE Mains Prep', 'approved'),
('The standard cell potential for the Daniel cell Zn|Zn$^{2+}$||Cu$^{2+}$|Cu ($E^\circ_{\text{Zn}} = -0.76\;\text{V}$, $E^\circ_{\text{Cu}} = +0.34\;\text{V}$) is', '$-1.10\;\text{V}$', '$+1.10\;\text{V}$', '$+0.42\;\text{V}$', '$-0.42\;\text{V}$', 'option2', '$E^\circ_{cell} = E^\circ_{cathode} - E^\circ_{anode} = 0.34 - (-0.76) = +1.10\;\text{V}$.', 'c_electrochemical_cells', 2, 'JEE Mains Prep', 'approved'),
('Faraday''s first law of electrolysis states that the mass deposited is proportional to', 'The voltage applied', 'The quantity of electricity passed ($m = ZIt$)', 'The temperature', 'The concentration of the electrolyte', 'option2', '$m = ZIt = (M \times I \times t)/(n \times F)$ where $Z$ is the electrochemical equivalent.', 'c_electrochemical_cells', 2, 'JEE Mains Prep', 'approved'),
('The amount of charge required to deposit $1\;\text{mol}$ of a monovalent metal is', '$9648\;\text{C}$', '$48242\;\text{C}$', '$192970\;\text{C}$', '$96485\;\text{C}$ ($1\;\text{F}$)', 'option4', '$1\;\text{F} = 96485\;\text{C/mol}$ of electrons. For monovalent: $1\;\text{F}$ deposits $1\;\text{mol}$.', 'c_electrochemical_cells', 2, 'JEE Mains Prep', 'approved'),
('The charge required to deposit $1\;\text{mol}$ of Cu from CuSO$_4$ solution is', '$1\;\text{F}$', '$2\;\text{F}$', '$3\;\text{F}$', '$0.5\;\text{F}$', 'option2', 'Cu$^{2+}$ + 2e$^- \to$ Cu. 2 moles of electrons per mole of Cu. Charge $= 2\;\text{F}$.', 'c_electrochemical_cells', 2, 'JEE Mains Prep', 'approved'),
('In the electrochemical series, the metal that can displace Cu from CuSO$_4$ solution is', 'Ag ($E^\circ = +0.80\;\text{V}$)', 'Au ($E^\circ = +1.50\;\text{V}$)', 'Fe ($E^\circ = -0.44\;\text{V}$)', 'Pt', 'option3', 'Fe has more negative $E^\circ$ than Cu ($+0.34\;\text{V}$). Fe is a stronger reducing agent and can displace Cu.', 'c_electrochemical_cells', 2, 'JEE Mains Prep', 'approved'),
('During electrolysis of aqueous NaCl, the products at cathode and anode are', 'Na and Cl$_2$', 'H$_2$ and Cl$_2$', 'Na and O$_2$', 'H$_2$ and O$_2$', 'option2', 'Cathode: H$_2$O is reduced (H$_2$ evolved) because $E^\circ$ of H$_2$O reduction $> E^\circ$ of Na$^+$ reduction. Anode: Cl$^-$ is oxidized to Cl$_2$.', 'c_electrochemical_cells', 2, 'JEE Mains Prep', 'approved'),
('The mass of Ag deposited by passing $0.5\;\text{F}$ through AgNO$_3$ solution is ($M_{\text{Ag}} = 108$)', '$54\;\text{g}$', '$108\;\text{g}$', '$27\;\text{g}$', '$216\;\text{g}$', 'option1', 'Ag$^+$ + e$^- \to$ Ag. $0.5\;\text{F} = 0.5\;\text{mol}$ electrons deposits $0.5\;\text{mol}$ Ag $= 54\;\text{g}$.', 'c_electrochemical_cells', 2, 'JEE Mains Prep', 'approved'),
('A current of $2\;\text{A}$ is passed through CuSO$_4$ solution for $1\;\text{hour}$. The mass of Cu deposited is ($M = 63.5$)', '$4.74\;\text{g}$', '$2.37\;\text{g}$', '$1.19\;\text{g}$', '$63.5\;\text{g}$', 'option2', 'Charge $= 2 \times 3600 = 7200\;\text{C}$. Moles of e$^- = 7200/96485 = 0.0746$. Cu$^{2+}$ needs 2e$^-$: mol Cu $= 0.0373$. Mass $= 0.0373 \times 63.5 = 2.37\;\text{g}$.', 'c_electrochemical_cells', 3, 'JEE Mains Prep', 'approved'),
('The standard cell potential must be positive for a galvanic cell because', '$\Delta G^\circ = -nFE^\circ < 0$ requires $E^\circ > 0$ for spontaneity', '$E^\circ$ is always positive', 'Negative $E^\circ$ means no reaction', 'Convention only', 'option1', 'Spontaneous: $\Delta G^\circ < 0$. Since $\Delta G^\circ = -nFE^\circ$: $E^\circ$ must be positive.', 'c_electrochemical_cells', 3, 'JEE Mains Prep', 'approved'),
('During electrolysis of dilute H$_2$SO$_4$ with Pt electrodes, the products are', 'H$_2$ at cathode and O$_2$ at anode', 'SO$_2$ at anode', 'H$_2$ at anode and O$_2$ at cathode', 'No reaction', 'option1', 'Cathode: 2H$^+$ + 2e$^- \to$ H$_2$. Anode: 2H$_2$O $\to$ O$_2$ + 4H$^+$ + 4e$^-$. Net: electrolysis of water.', 'c_electrochemical_cells', 3, 'JEE Mains Prep', 'approved'),
('The overpotential is', 'The extra voltage needed beyond the thermodynamic value to drive an electrode reaction at a practical rate', 'The cell potential', 'The standard potential', 'Zero for all reactions', 'option1', 'Overpotential arises from kinetic barriers (activation energy for electron transfer). It is especially significant for gas evolution (H$_2$, O$_2$).', 'c_electrochemical_cells', 3, 'JEE Mains Prep', 'approved'),
('In a concentration cell, the EMF arises from', 'Different temperatures', 'Different metals', 'Different concentrations of the same electrolyte in the two half-cells', 'Different solvents', 'option3', 'Same electrodes, different concentrations. EMF $= (RT/nF)\ln(c_1/c_2)$. Drives towards equalization of concentrations.', 'c_electrochemical_cells', 3, 'JEE Mains Prep', 'approved'),
('Faraday''s second law states that when the same quantity of electricity is passed through different electrolytes, the masses deposited are proportional to', 'Their volumes', 'Their atomic numbers', 'Their densities', 'Their equivalent weights', 'option4', '$m_1/m_2 = E_1/E_2$ where $E$ is the equivalent weight ($M/n$).', 'c_electrochemical_cells', 3, 'JEE Mains Prep', 'approved'),
('The efficiency of an electrolytic process is often less than $100\%$ because of', 'Temperature effects only', 'Perfect conversion', 'No losses ever occur', 'Side reactions, overpotential, and resistance losses', 'option4', 'Side reactions (e.g., H$_2$ evolution instead of metal deposition), ohmic losses in the electrolyte, and overpotential all reduce efficiency.', 'c_electrochemical_cells', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_nernst_gibbs (7 easy, 7 medium, 7 hard = 21)
-- Nernst equation, cell potential and Gibbs energy
-- ============================================================
('The Nernst equation relates the cell potential to', 'Temperature only', 'The concentrations of reactants and products', 'The mass of electrodes', 'The volume of solution', 'option2', '$E = E^\circ - (RT/nF)\ln Q$. Cell potential depends on concentrations through the reaction quotient $Q$.', 'c_nernst_gibbs', 1, 'JEE Mains Prep', 'approved'),
('The Nernst equation at $25°\text{C}$ can be written as', '$E = E^\circ - (RT/F)\ln Q$', '$E = E^\circ + (0.0592/n)\log Q$', '$E = E^\circ - (0.0592/n)\log Q$', '$E = E^\circ - 0.0592\log Q$', 'option3', 'At $298\;\text{K}$: $E = E^\circ - (0.0592/n)\log Q$ (using $2.303RT/F = 0.0592\;\text{V}$).', 'c_nernst_gibbs', 1, 'JEE Mains Prep', 'approved'),
('The relationship between $\Delta G^\circ$ and $E^\circ$ is', '$\Delta G^\circ = -E^\circ/nF$', '$\Delta G^\circ = nFE^\circ$', '$\Delta G^\circ = -nFE^\circ$', '$\Delta G^\circ = nE^\circ/F$', 'option3', '$\Delta G^\circ = -nFE^\circ$. Positive $E^\circ$ gives negative $\Delta G^\circ$ (spontaneous).', 'c_nernst_gibbs', 1, 'JEE Mains Prep', 'approved'),
('A dry cell (Leclanche cell) uses', 'Cu and Zn electrodes', 'Zn anode and MnO$_2$/C cathode with NH$_4$Cl paste', 'Pb and PbO$_2$ electrodes', 'Li anode', 'option2', 'Dry cell: Zn case (anode), carbon rod surrounded by MnO$_2$ (cathode), NH$_4$Cl paste electrolyte. EMF $\approx 1.5\;\text{V}$.', 'c_nernst_gibbs', 1, 'JEE Mains Prep', 'approved'),
('A lead-acid battery (car battery) uses', 'Li and graphite', 'Zn and Cu electrodes', 'Pb anode and PbO$_2$ cathode in H$_2$SO$_4$', 'Ni and Cd', 'option3', 'Lead-acid: Pb | H$_2$SO$_4$ | PbO$_2$. EMF $\approx 2\;\text{V}$ per cell. Rechargeable.', 'c_nernst_gibbs', 1, 'JEE Mains Prep', 'approved'),
('A fuel cell converts', 'Chemical energy of a fuel directly to electrical energy', 'Electrical energy to chemical energy', 'Heat to electricity via steam', 'Nuclear energy to electricity', 'option1', 'H$_2$-O$_2$ fuel cell: 2H$_2$ + O$_2 \to$ 2H$_2$O. High efficiency ($\sim 70\%$), clean (only water produced).', 'c_nernst_gibbs', 1, 'JEE Mains Prep', 'approved'),
('At equilibrium, the cell potential $E$ is', 'Maximum', 'Zero', 'Equal to $E^\circ$', 'Negative', 'option2', 'At equilibrium: $\Delta G = 0$, so $E = 0$. The cell is "dead" — no more current flows.', 'c_nernst_gibbs', 1, 'JEE Mains Prep', 'approved'),
('For the cell Zn|Zn$^{2+}$(0.01 M)||Cu$^{2+}$(1 M)|Cu, the cell potential at $25°\text{C}$ ($E^\circ = 1.10\;\text{V}$, $n = 2$) is', '$1.041\;\text{V}$', '$1.10\;\text{V}$', '$1.159\;\text{V}$', '$0.80\;\text{V}$', 'option3', '$E = 1.10 - (0.0592/2)\log(0.01/1) = 1.10 - 0.0296 \times (-2) = 1.10 + 0.059 = 1.159\;\text{V}$.', 'c_nernst_gibbs', 2, 'JEE Mains Prep', 'approved'),
('The equilibrium constant $K$ for a cell with $E^\circ = 0.59\;\text{V}$ and $n = 2$ at $25°\text{C}$ is', '$\sim 10^{10}$', '$\sim 10^{20}$', '$\sim 10^{5}$', '$\sim 10^{2}$', 'option2', '$\log K = nE^\circ/0.0592 = 2 \times 0.59/0.0592 = 19.9$. $K \approx 10^{20}$.', 'c_nernst_gibbs', 2, 'JEE Mains Prep', 'approved'),
('The $\Delta G^\circ$ for the Daniel cell ($E^\circ = 1.10\;\text{V}$, $n = 2$) is', '$-424\;\text{kJ/mol}$', '$+212\;\text{kJ/mol}$', '$-106\;\text{kJ/mol}$', '$-212\;\text{kJ/mol}$', 'option4', '$\Delta G^\circ = -nFE^\circ = -2 \times 96485 \times 1.10 = -212267\;\text{J} = -212\;\text{kJ/mol}$.', 'c_nernst_gibbs', 2, 'JEE Mains Prep', 'approved'),
('In a Ni-Cd rechargeable battery, the overall reaction during discharge is', 'Zn + MnO$_2 \to$ ZnO + Mn$_2$O$_3$', 'Pb + PbO$_2 \to$ 2PbSO$_4$', 'Cd + 2NiOOH + 2H$_2$O $\to$ Cd(OH)$_2$ + 2Ni(OH)$_2$', '2H$_2$ + O$_2 \to$ 2H$_2$O', 'option3', 'Ni-Cd: Cd anode, NiOOH cathode, KOH electrolyte. EMF $\approx 1.25\;\text{V}$. Rechargeable.', 'c_nernst_gibbs', 2, 'JEE Mains Prep', 'approved'),
('The temperature coefficient of EMF ($dE/dT$) is related to the entropy change by', '$\Delta S = -nF(dE/dT)$', '$\Delta S = nF(dE/dT)$', '$\Delta S = dE/dT$', '$\Delta S = nFE/T$', 'option2', 'From $\Delta G = -nFE$ and $(\partial\Delta G/\partial T)_P = -\Delta S$: $\Delta S = nF(dE/dT)$.', 'c_nernst_gibbs', 2, 'JEE Mains Prep', 'approved'),
('The enthalpy change of a cell reaction can be calculated from', '$\Delta H = -nF[E - T(dE/dT)]$', '$\Delta H = -nFE$', '$\Delta H = nFE$', '$\Delta H = -nFT$', 'option1', '$\Delta G = \Delta H - T\Delta S = -nFE$. $\Delta S = nF(dE/dT)$. $\Delta H = -nFE + TnF(dE/dT) = -nF[E - T(dE/dT)]$.', 'c_nernst_gibbs', 2, 'JEE Mains Prep', 'approved'),
('If $dE/dT = 0$ for a cell, then', '$\Delta H = \Delta G = -nFE$ (the reaction is purely enthalpic)', '$\Delta S = 0$ and $\Delta H \neq \Delta G$', '$\Delta H = 0$', 'The cell does not work', 'option1', 'When $dE/dT = 0$: $\Delta S = 0$ and $\Delta H = -nFE = \Delta G$. No entropy contribution.', 'c_nernst_gibbs', 2, 'JEE Mains Prep', 'approved'),
('A hydrogen-oxygen fuel cell operating at $25°\text{C}$ has $E^\circ = 1.23\;\text{V}$. The maximum electrical work per mole of H$_2$ is', '$-237\;\text{kJ}$', '$-474\;\text{kJ}$', '$-118\;\text{kJ}$', '$-286\;\text{kJ}$', 'option1', '$w_{max} = \Delta G^\circ = -nFE^\circ = -2 \times 96485 \times 1.23 = -237\;\text{kJ}$. This is the Gibbs energy, not the enthalpy ($-286\;\text{kJ}$).', 'c_nernst_gibbs', 3, 'JEE Mains Prep', 'approved'),
('For a concentration cell Ag|Ag$^+$(0.001 M)||Ag$^+$(0.1 M)|Ag, the EMF at $25°\text{C}$ is', '$0.0592\;\text{V}$', '$0.118\;\text{V}$', '$0.0296\;\text{V}$', '$0\;\text{V}$', 'option2', '$E = (0.0592/1)\log(0.1/0.001) = 0.0592 \times 2 = 0.118\;\text{V}$.', 'c_nernst_gibbs', 3, 'JEE Mains Prep', 'approved'),
('The corrosion of iron is an electrochemical process where', 'Fe is oxidized at anodic spots and O$_2$ is reduced at cathodic spots', 'Fe is reduced', 'O$_2$ is oxidized', 'No electrons are transferred', 'option1', 'Anode: Fe $\to$ Fe$^{2+}$ + 2e$^-$. Cathode: O$_2$ + 2H$_2$O + 4e$^- \to$ 4OH$^-$. Fe$^{2+}$ + OH$^-$ eventually forms rust (Fe$_2$O$_3 \cdot x$H$_2$O).', 'c_nernst_gibbs', 3, 'JEE Mains Prep', 'approved'),
('Cathodic protection of iron involves', 'Coating with a less reactive metal', 'Coating iron with a more reactive metal (e.g., Zn) that corrodes preferentially', 'Heating the iron', 'Painting only', 'option2', 'Zn (more negative $E^\circ$) acts as a sacrificial anode, protecting Fe. This is galvanization.', 'c_nernst_gibbs', 3, 'JEE Mains Prep', 'approved'),
('The Nernst equation predicts that the cell potential becomes zero when', '$Q = 0$', '$Q = K$ (equilibrium)', '$Q = 1$', '$Q = \infty$', 'option2', '$E = E^\circ - (RT/nF)\ln Q = 0$ when $Q = K$ (since $E^\circ = (RT/nF)\ln K$).', 'c_nernst_gibbs', 3, 'JEE Mains Prep', 'approved'),
('The standard electrode potential of Cu$^{2+}$/Cu is $+0.34\;\text{V}$ and Ag$^+$/Ag is $+0.80\;\text{V}$. In a cell Cu|Cu$^{2+}$||Ag$^+$|Ag, the $\Delta G^\circ$ is', '$-178\;\text{kJ}$', '$+88.9\;\text{kJ}$', '$-44.5\;\text{kJ}$', '$-88.9\;\text{kJ}$', 'option4', '$E^\circ = 0.80 - 0.34 = 0.46\;\text{V}$. $n = 2$. $\Delta G^\circ = -2 \times 96485 \times 0.46 = -88.8\;\text{kJ}$.', 'c_nernst_gibbs', 3, 'JEE Mains Prep', 'approved'),
('The lithium-ion battery is preferred for portable electronics because', 'Li is cheap', 'Li has the most negative $E^\circ$ ($-3.04\;\text{V}$), giving high cell voltage, and Li is very light', 'Li batteries are not rechargeable', 'Li is the heaviest metal', 'option2', 'Li: lightest metal + most negative $E^\circ$ = highest energy density (Wh/kg). Rechargeable via intercalation chemistry.', 'c_nernst_gibbs', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_rate_factors (7 easy, 7 medium, 7 hard = 21)
-- Rate of reaction, factors affecting rate, order, molecularity
-- ============================================================
('The rate of a chemical reaction is defined as', 'The activation energy', 'The equilibrium constant', 'The change in concentration of a reactant or product per unit time', 'The enthalpy change', 'option3', 'Rate $= -d[\text{R}]/dt = +d[\text{P}]/dt$ (negative for reactants, positive for products).', 'c_rate_factors', 1, 'JEE Mains Prep', 'approved'),
('The rate of a reaction generally increases with', 'Decreasing temperature', 'Increasing temperature', 'Decreasing concentration', 'Adding an inert gas', 'option2', 'Higher temperature increases molecular kinetic energy, leading to more effective collisions.', 'c_rate_factors', 1, 'JEE Mains Prep', 'approved'),
('A catalyst increases the rate of a reaction by', 'Increasing the activation energy', 'Providing an alternative pathway with lower activation energy', 'Changing the equilibrium constant', 'Increasing the enthalpy of reaction', 'option2', 'Catalysts lower $E_a$ by providing a different mechanism. They do not change $\Delta H$ or $K$.', 'c_rate_factors', 1, 'JEE Mains Prep', 'approved'),
('The order of a reaction is', 'Always equal to the sum of stoichiometric coefficients', 'Determined experimentally from the rate law', 'Always a whole number', 'The same as molecularity', 'option2', 'Order is experimental. It can be zero, fractional, or negative. It need not match stoichiometry.', 'c_rate_factors', 1, 'JEE Mains Prep', 'approved'),
('The molecularity of an elementary reaction is', 'The number of reacting species (molecules, atoms, ions) in that step', 'The order of the reaction', 'Always determined experimentally', 'The number of products', 'option1', 'Molecularity: theoretical, always a positive integer (1 = unimolecular, 2 = bimolecular, 3 = termolecular). Only for elementary steps.', 'c_rate_factors', 1, 'JEE Mains Prep', 'approved'),
('For the reaction $2\text{A} + \text{B} \to \text{C}$, the rate can be expressed as', '$-2\frac{d[\text{A}]}{dt} = -\frac{d[\text{B}]}{dt}$', '$-\frac{d[\text{A}]}{dt} = -\frac{d[\text{B}]}{dt}$', '$\frac{d[\text{A}]}{dt} = \frac{d[\text{C}]}{dt}$', '$-\frac{1}{2}\frac{d[\text{A}]}{dt} = -\frac{d[\text{B}]}{dt} = \frac{d[\text{C}]}{dt}$', 'option4', 'Rate $= -\frac{1}{2}\frac{d[\text{A}]}{dt} = -\frac{d[\text{B}]}{dt} = \frac{d[\text{C}]}{dt}$. Divide by stoichiometric coefficients.', 'c_rate_factors', 1, 'JEE Mains Prep', 'approved'),
('Factors that affect the rate of a reaction include', 'Concentration, temperature, catalyst, and surface area', 'Only temperature', 'Only concentration', 'Only the catalyst', 'option1', 'All four factors influence rate. For heterogeneous reactions, surface area is also important.', 'c_rate_factors', 1, 'JEE Mains Prep', 'approved'),
('For the rate law $r = k[\text{A}]^2[\text{B}]$, the overall order is', '$2$', '$3$', '$1$', '$4$', 'option2', 'Overall order $= 2 + 1 = 3$. Order w.r.t. A is 2, w.r.t. B is 1.', 'c_rate_factors', 2, 'JEE Mains Prep', 'approved'),
('A reaction with rate law $r = k$ (independent of concentration) is', 'First order', 'Zero order', 'Second order', 'Third order', 'option2', 'Zero order: rate is constant, independent of reactant concentration.', 'c_rate_factors', 2, 'JEE Mains Prep', 'approved'),
('The units of the rate constant $k$ for a first-order reaction are', '$\text{mol}^{-1}\text{L}\;\text{s}^{-1}$', '$\text{s}^{-1}$', '$\text{mol}^{-2}\text{L}^2\;\text{s}^{-1}$', '$\text{mol}\;\text{L}^{-1}\;\text{s}^{-1}$', 'option2', 'For $n$th order: units of $k = (\text{mol/L})^{1-n}\text{s}^{-1}$. First order ($n = 1$): $\text{s}^{-1}$.', 'c_rate_factors', 2, 'JEE Mains Prep', 'approved'),
('The rate-determining step in a multi-step reaction is', 'The fastest step', 'The slowest step', 'The last step', 'The first step always', 'option2', 'The slowest elementary step limits the overall rate, like the narrowest part of a funnel.', 'c_rate_factors', 2, 'JEE Mains Prep', 'approved'),
('Molecularity greater than $3$ is rare because', 'The probability of simultaneous collision of more than 3 molecules is extremely low', 'It violates conservation laws', 'It is forbidden by quantum mechanics', 'It always gives zero rate', 'option1', 'Termolecular reactions are already rare. Four-body collisions are statistically negligible.', 'c_rate_factors', 2, 'JEE Mains Prep', 'approved'),
('The pseudo-first-order reaction is one where', 'A second-order reaction appears first-order because one reactant is in large excess', 'The reaction is truly first order', 'The reaction has no order', 'Both reactants are in equal concentration', 'option1', 'Example: hydrolysis of ester in excess water. $r = k''[\text{ester}]$ where $k'' = k[\text{H}_2\text{O}]$ (constant).', 'c_rate_factors', 2, 'JEE Mains Prep', 'approved'),
('The initial rate method determines the order by', 'Measuring the temperature', 'Measuring the rate at equilibrium', 'Measuring the rate at the very beginning of the reaction for different initial concentrations', 'Measuring the activation energy', 'option3', 'Compare initial rates with different $[A]_0$. If doubling $[A]$ doubles rate: first order in A. If it quadruples: second order.', 'c_rate_factors', 2, 'JEE Mains Prep', 'approved'),
('For a reaction A $\to$ products, doubling $[\text{A}]$ quadruples the rate. The order w.r.t. A is', '$1$', '$2$', '$3$', '$0$', 'option2', 'Rate $\propto [\text{A}]^n$. $4 = 2^n$. $n = 2$ (second order).', 'c_rate_factors', 3, 'JEE Mains Prep', 'approved'),
('For a complex reaction, the rate law is determined by', 'The stoichiometry of the overall reaction', 'The mechanism (specifically the rate-determining step)', 'The enthalpy change', 'The equilibrium constant', 'option2', 'The rate law reflects the mechanism, not the overall stoichiometry. Only for elementary reactions does order equal molecularity.', 'c_rate_factors', 3, 'JEE Mains Prep', 'approved'),
('The reaction 2NO + O$_2 \to$ 2NO$_2$ has rate $= k[\text{NO}]^2[\text{O}_2]$. This suggests the reaction', 'Is definitely elementary', 'May be termolecular (elementary) or may proceed via a multi-step mechanism', 'Is definitely multi-step', 'Has order zero', 'option2', 'The rate law is consistent with a termolecular elementary step, but could also arise from a two-step mechanism with a fast pre-equilibrium.', 'c_rate_factors', 3, 'JEE Mains Prep', 'approved'),
('For the reaction 2N$_2$O$_5 \to$ 4NO$_2$ + O$_2$, the rate law is $r = k[\text{N}_2\text{O}_5]$. This shows that', 'The reaction is first order despite having stoichiometric coefficient 2', 'The reaction is second order', 'Order always equals stoichiometry', 'The reaction does not occur', 'option1', 'Order is experimental. This reaction proceeds via a multi-step mechanism where the first step (unimolecular decomposition of N$_2$O$_5$) is rate-determining.', 'c_rate_factors', 3, 'JEE Mains Prep', 'approved'),
('The integrated rate law is useful for', 'Finding the equilibrium constant', 'Measuring temperature', 'Determining the order of a reaction by fitting concentration-time data', 'Determining molecularity', 'option3', 'Plot $[\text{A}]$ vs $t$ (zero order), $\ln[\text{A}]$ vs $t$ (first order), or $1/[\text{A}]$ vs $t$ (second order). The linear plot reveals the order.', 'c_rate_factors', 3, 'JEE Mains Prep', 'approved'),
('A negative order with respect to a reactant means', 'Negative orders are impossible', 'The reaction does not involve that reactant', 'The rate is always zero', 'Increasing its concentration decreases the rate', 'option4', 'Negative order: the reactant inhibits the reaction (e.g., by blocking active sites in catalysis). Rare but possible.', 'c_rate_factors', 3, 'JEE Mains Prep', 'approved'),
('The overall order of a reaction can be fractional because', 'Only zero and first orders exist', 'All reactions have integer orders', 'Fractional orders are errors', 'The reaction proceeds via a multi-step mechanism with intermediates', 'option4', 'Fractional orders arise from complex mechanisms. E.g., the decomposition of acetaldehyde: $r = k[\text{CH}_3\text{CHO}]^{3/2}$ (chain mechanism).', 'c_rate_factors', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_rate_law_orders (7 easy, 7 medium, 7 hard = 21)
-- Rate law, rate constant, zero/first-order, half-lives
-- ============================================================
('The integrated rate law for a first-order reaction is', '$\ln[\text{A}] = \ln[\text{A}]_0 - kt$', '$[\text{A}] = [\text{A}]_0 - kt$', '$1/[\text{A}] = 1/[\text{A}]_0 + kt$', '$[\text{A}]^2 = [\text{A}]_0^2 - kt$', 'option1', 'First order: $\ln[\text{A}] = \ln[\text{A}]_0 - kt$ or $[\text{A}] = [\text{A}]_0 e^{-kt}$.', 'c_rate_law_orders', 1, 'JEE Mains Prep', 'approved'),
('The half-life of a first-order reaction is', '$t_{1/2} = 1/(2k[\text{A}]_0)$', '$t_{1/2} = 0.693/k$', '$t_{1/2} = [\text{A}]_0/(2k)$', '$t_{1/2} = 0.693k$', 'option2', '$t_{1/2} = \ln 2/k = 0.693/k$. Independent of initial concentration for first order.', 'c_rate_law_orders', 1, 'JEE Mains Prep', 'approved'),
('The integrated rate law for a zero-order reaction is', '$[\text{A}] = [\text{A}]_0 - kt$', '$\ln[\text{A}] = \ln[\text{A}]_0 - kt$', '$1/[\text{A}] = 1/[\text{A}]_0 + kt$', '$[\text{A}] = [\text{A}]_0 e^{-kt}$', 'option1', 'Zero order: $[\text{A}]$ decreases linearly with time. Rate is constant.', 'c_rate_law_orders', 1, 'JEE Mains Prep', 'approved'),
('The half-life of a zero-order reaction is', '$0.693/k$', '$[\text{A}]_0/(2k)$', '$1/(k[\text{A}]_0)$', 'Independent of concentration', 'option2', '$t_{1/2} = [\text{A}]_0/(2k)$. Depends on initial concentration (unlike first order).', 'c_rate_law_orders', 1, 'JEE Mains Prep', 'approved'),
('For a first-order reaction, a plot of $\ln[\text{A}]$ vs $t$ gives', 'A straight line with slope $+k$', 'A curve', 'A horizontal line', 'A straight line with slope $-k$', 'option4', '$\ln[\text{A}] = -kt + \ln[\text{A}]_0$. Linear with slope $= -k$ and intercept $= \ln[\text{A}]_0$.', 'c_rate_law_orders', 1, 'JEE Mains Prep', 'approved'),
('Radioactive decay follows', 'Zero-order kinetics', 'First-order kinetics', 'Second-order kinetics', 'No kinetics', 'option2', '$N = N_0 e^{-\lambda t}$. First order with rate constant $\lambda$ (decay constant).', 'c_rate_law_orders', 1, 'JEE Mains Prep', 'approved'),
('The integrated rate law for a second-order reaction (in one reactant) is', '$[\text{A}] = [\text{A}]_0 - kt$', '$1/[\text{A}] = 1/[\text{A}]_0 + kt$', '$\ln[\text{A}] = \ln[\text{A}]_0 - kt$', '$[\text{A}]^2 = [\text{A}]_0^2 + kt$', 'option2', 'Second order: $1/[\text{A}]$ vs $t$ is linear with slope $k$.', 'c_rate_law_orders', 1, 'JEE Mains Prep', 'approved'),
('A first-order reaction has $k = 0.01\;\text{s}^{-1}$. Its half-life is', '$69.3\;\text{s}$', '$100\;\text{s}$', '$50\;\text{s}$', '$6.93\;\text{s}$', 'option1', '$t_{1/2} = 0.693/0.01 = 69.3\;\text{s}$.', 'c_rate_law_orders', 2, 'JEE Mains Prep', 'approved'),
('After 3 half-lives, the fraction of reactant remaining in a first-order reaction is', '$1/4$', '$1/8$', '$1/2$', '$1/16$', 'option2', 'After $n$ half-lives: fraction $= (1/2)^n = (1/2)^3 = 1/8$.', 'c_rate_law_orders', 2, 'JEE Mains Prep', 'approved'),
('A first-order reaction is $75\%$ complete in $32\;\text{min}$. The half-life is', '$32\;\text{min}$', '$8\;\text{min}$', '$16\;\text{min}$', '$24\;\text{min}$', 'option3', '$75\%$ complete $= 2$ half-lives ($50\% \to 75\%$). $t_{1/2} = 32/2 = 16\;\text{min}$.', 'c_rate_law_orders', 2, 'JEE Mains Prep', 'approved'),
('The time for $99.9\%$ completion of a first-order reaction is', '$10 \times t_{1/2}$', '$3 \times t_{1/2}$', '$7 \times t_{1/2}$', '$100 \times t_{1/2}$', 'option1', '$t = (2.303/k)\log(1000) = (2.303/k) \times 3 = 6.909/k = 10 \times 0.693/k = 10 \times t_{1/2}$.', 'c_rate_law_orders', 2, 'JEE Mains Prep', 'approved'),
('For a second-order reaction, the half-life is', '$0.693/k$', '$1/(k[\text{A}]_0)$', '$[\text{A}]_0/(2k)$', 'Independent of concentration', 'option2', '$t_{1/2} = 1/(k[\text{A}]_0)$. Inversely proportional to initial concentration.', 'c_rate_law_orders', 2, 'JEE Mains Prep', 'approved'),
('The rate constant of a first-order reaction can be determined from', '$k = [\text{A}]_0 t$', '$k = ([\text{A}]_0 - [\text{A}])/t$', '$k = 1/([\text{A}]t)$', '$k = (2.303/t)\log([\text{A}]_0/[\text{A}])$', 'option4', '$k = (2.303/t)\log(a/(a-x))$ where $a = [\text{A}]_0$ and $x$ is the amount reacted.', 'c_rate_law_orders', 2, 'JEE Mains Prep', 'approved'),
('A zero-order reaction with $[\text{A}]_0 = 0.1\;\text{M}$ and $k = 0.01\;\text{M/s}$ will be complete in', '$5\;\text{s}$', '$100\;\text{s}$', '$10\;\text{s}$', '$1\;\text{s}$', 'option3', '$[\text{A}] = 0$ when $t = [\text{A}]_0/k = 0.1/0.01 = 10\;\text{s}$.', 'c_rate_law_orders', 2, 'JEE Mains Prep', 'approved'),
('For a first-order reaction, the time to reach $87.5\%$ completion is', '$3 \times t_{1/2}$', '$2 \times t_{1/2}$', '$4 \times t_{1/2}$', '$t_{1/2}$', 'option1', '$87.5\%$ complete: $12.5\%$ remaining $= (1/2)^3$. So $t = 3 \times t_{1/2}$.', 'c_rate_law_orders', 3, 'JEE Mains Prep', 'approved'),
('If the half-life of a reaction doubles when the initial concentration is doubled, the order is', '$2$', '$1$', '$0$', '$3$', 'option3', 'For zero order: $t_{1/2} = [\text{A}]_0/(2k) \propto [\text{A}]_0$. Doubling $[\text{A}]_0$ doubles $t_{1/2}$.', 'c_rate_law_orders', 3, 'JEE Mains Prep', 'approved'),
('If the half-life is independent of initial concentration, the order is', '$0$', '$1$', '$2$', '$3$', 'option2', 'First order: $t_{1/2} = 0.693/k$. No dependence on $[\text{A}]_0$.', 'c_rate_law_orders', 3, 'JEE Mains Prep', 'approved'),
('A reaction has $t_{1/2} = 10\;\text{min}$ at $[\text{A}]_0 = 0.1\;\text{M}$ and $t_{1/2} = 20\;\text{min}$ at $[\text{A}]_0 = 0.05\;\text{M}$. The order is', '$1$', '$2$', '$0$', '$3$', 'option2', '$t_{1/2} \propto 1/[\text{A}]_0$ for second order. $10/20 = 0.05/0.1$. Confirmed: second order.', 'c_rate_law_orders', 3, 'JEE Mains Prep', 'approved'),
('The rate constant of a first-order reaction at $300\;\text{K}$ is $0.05\;\text{min}^{-1}$. The concentration drops from $0.1\;\text{M}$ to $0.025\;\text{M}$ in', '$55.4\;\text{min}$', '$13.9\;\text{min}$', '$27.7\;\text{min}$', '$6.93\;\text{min}$', 'option3', '$t = (2.303/0.05)\log(0.1/0.025) = 46.06 \times \log 4 = 46.06 \times 0.602 = 27.7\;\text{min}$.', 'c_rate_law_orders', 3, 'JEE Mains Prep', 'approved'),
('For the general $n$th-order reaction, the half-life is proportional to', '$[\text{A}]_0^{1-n}$', '$[\text{A}]_0^{n-1}$', '$[\text{A}]_0^n$', '$[\text{A}]_0$', 'option1', '$t_{1/2} \propto [\text{A}]_0^{1-n}$. Zero: $\propto [\text{A}]_0$. First: independent. Second: $\propto 1/[\text{A}]_0$.', 'c_rate_law_orders', 3, 'JEE Mains Prep', 'approved'),
('The decomposition of N$_2$O$_5$ in CCl$_4$ is first order with $k = 6.2 \times 10^{-4}\;\text{s}^{-1}$. The time for the concentration to drop to $1/10$ of its initial value is', '$693\;\text{s}$', '$1117\;\text{s}$', '$6930\;\text{s}$', '$3714\;\text{s}$', 'option4', '$t = (2.303/k)\log 10 = 2.303/(6.2 \times 10^{-4}) = 3714\;\text{s}$.', 'c_rate_law_orders', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- c_arrhenius_collision (7 easy, 7 medium, 7 hard = 21)
-- Temperature effect, Arrhenius equation, activation energy, collision theory
-- ============================================================
('The Arrhenius equation is', '$k = A + E_a/RT$', '$k = Ae^{E_a/(RT)}$', '$k = E_a/(RT)$', '$k = Ae^{-E_a/(RT)}$', 'option4', '$k = Ae^{-E_a/(RT)}$ where $A$ is the pre-exponential factor and $E_a$ is the activation energy.', 'c_arrhenius_collision', 1, 'JEE Mains Prep', 'approved'),
('The activation energy ($E_a$) is', 'The kinetic energy of all molecules', 'The energy of the products', 'The enthalpy of reaction', 'The minimum energy required for reactant molecules to undergo a successful reaction', 'option4', '$E_a$ is the energy barrier that must be overcome for the reaction to proceed. Higher $E_a$ means slower reaction.', 'c_arrhenius_collision', 1, 'JEE Mains Prep', 'approved'),
('According to collision theory, a reaction occurs when molecules', 'Simply collide', 'Collide with sufficient energy AND proper orientation', 'Are at rest', 'Are far apart', 'option2', 'Effective collision requires: (1) energy $\geq E_a$ and (2) correct orientation. Only a fraction of collisions are effective.', 'c_arrhenius_collision', 1, 'JEE Mains Prep', 'approved'),
('A catalyst lowers the activation energy. This means', 'More molecules have sufficient energy to react at the same temperature', 'The equilibrium shifts', 'The enthalpy changes', 'The temperature increases', 'option1', 'Lower $E_a$ $\rightarrow$ larger fraction of molecules above the energy threshold $\rightarrow$ faster rate.', 'c_arrhenius_collision', 1, 'JEE Mains Prep', 'approved'),
('The Arrhenius equation in logarithmic form is', '$k = \ln A - E_a$', '$\ln k = \ln A + E_a/(RT)$', '$\log k = A - E_a$', '$\ln k = \ln A - E_a/(RT)$', 'option4', '$\ln k = \ln A - E_a/(RT)$. Plot of $\ln k$ vs $1/T$ gives slope $= -E_a/R$.', 'c_arrhenius_collision', 1, 'JEE Mains Prep', 'approved'),
('As temperature increases, the rate constant $k$', 'Decreases', 'Increases exponentially', 'Remains constant', 'Becomes zero', 'option2', '$k = Ae^{-E_a/(RT)}$. As $T$ increases, $e^{-E_a/(RT)}$ increases, so $k$ increases.', 'c_arrhenius_collision', 1, 'JEE Mains Prep', 'approved'),
('The pre-exponential factor $A$ in the Arrhenius equation represents', 'The activation energy', 'The frequency of collisions with proper orientation', 'The equilibrium constant', 'The enthalpy', 'option2', '$A = Z \times p$ where $Z$ is the collision frequency and $p$ is the steric (orientation) factor.', 'c_arrhenius_collision', 1, 'JEE Mains Prep', 'approved'),
('A plot of $\ln k$ vs $1/T$ gives a straight line with slope', '$-E_a$', '$E_a/R$', '$-E_a/R$', '$R/E_a$', 'option3', 'From $\ln k = \ln A - E_a/(RT)$: slope $= -E_a/R$, intercept $= \ln A$.', 'c_arrhenius_collision', 2, 'JEE Mains Prep', 'approved'),
('The rule of thumb that rate doubles for every $10°\text{C}$ rise corresponds to a temperature coefficient of', '$\sim 2$', '$\sim 10$', '$\sim 1$', '$\sim 0.5$', 'option1', 'Temperature coefficient $= k_{T+10}/k_T \approx 2$-$3$ for many reactions near room temperature.', 'c_arrhenius_collision', 2, 'JEE Mains Prep', 'approved'),
('The activation energy can be determined from rate constants at two temperatures using', '$\ln(k_2/k_1) = (E_a/R)(1/T_1 - 1/T_2)$', '$E_a = k_2 - k_1$', '$E_a = R(T_2 - T_1)$', '$E_a = k_1 k_2/(T_2 - T_1)$', 'option1', 'Two-point Arrhenius: $\ln(k_2/k_1) = (E_a/R)(1/T_1 - 1/T_2)$.', 'c_arrhenius_collision', 2, 'JEE Mains Prep', 'approved'),
('The fraction of molecules with energy $\geq E_a$ at temperature $T$ is given by', '$RT/E_a$', '$E_a/(RT)$', '$e^{-E_a/(RT)}$ (Boltzmann factor)', '$1 - e^{-E_a/(RT)}$', 'option3', 'Boltzmann distribution: fraction $= e^{-E_a/(RT)}$. This fraction increases with $T$.', 'c_arrhenius_collision', 2, 'JEE Mains Prep', 'approved'),
('For a reaction with $E_a = 0$, the rate constant', 'Is zero', 'Equals $A$ (independent of temperature)', 'Is infinite', 'Decreases with temperature', 'option2', '$k = Ae^{0} = A$. No energy barrier: every collision is effective. Rate is temperature-independent.', 'c_arrhenius_collision', 2, 'JEE Mains Prep', 'approved'),
('In collision theory, the steric factor $p$ accounts for', 'The temperature', 'The total number of collisions', 'The fraction of collisions with correct molecular orientation', 'The pressure', 'option3', '$p$ is usually $< 1$ (often much less). Complex molecules need very specific orientations for reaction.', 'c_arrhenius_collision', 2, 'JEE Mains Prep', 'approved'),
('The threshold energy in collision theory is', 'Zero', 'The average kinetic energy', 'The total energy of the system', 'The minimum kinetic energy along the line of approach needed for reaction', 'option4', 'Threshold energy $\approx E_a$. Only collisions with relative kinetic energy $\geq E_a$ along the line of centres can lead to reaction.', 'c_arrhenius_collision', 2, 'JEE Mains Prep', 'approved'),
('If $E_a = 75\;\text{kJ/mol}$ and $k_1 = 0.01\;\text{s}^{-1}$ at $300\;\text{K}$, the rate constant at $310\;\text{K}$ is approximately', '$0.01\;\text{s}^{-1}$', '$0.022\;\text{s}^{-1}$', '$0.1\;\text{s}^{-1}$', '$0.005\;\text{s}^{-1}$', 'option2', '$\ln(k_2/k_1) = (75000/8.314)(1/300 - 1/310) = 9023 \times 1.075 \times 10^{-4} = 0.97$. $k_2/k_1 = e^{0.97} = 2.64$. $k_2 = 0.026$. Closest is $0.022$ (approximate).', 'c_arrhenius_collision', 3, 'JEE Mains Prep', 'approved'),
('A catalyst provides an alternative pathway with $E_a = 50\;\text{kJ/mol}$ instead of $100\;\text{kJ/mol}$. At $300\;\text{K}$, the ratio of catalyzed to uncatalyzed rate constants is approximately', '$\sim 10^{4}$', '$\sim 2$', '$\sim 10^{8.7}$', '$\sim 10^{17}$', 'option3', '$\ln(k_{cat}/k_{uncat}) = (E_{a,uncat} - E_{a,cat})/(RT) = 50000/(8.314 \times 300) = 20.05$. $k_{cat}/k_{uncat} = e^{20} \approx 4.9 \times 10^8 \approx 10^{8.7}$.', 'c_arrhenius_collision', 3, 'JEE Mains Prep', 'approved'),
('The transition state theory (Eyring equation) differs from collision theory in that it', 'Ignores activation energy', 'Considers the formation of an activated complex at the top of the energy barrier', 'Only applies to gases', 'Predicts lower rates', 'option2', 'TST: reactants form an activated complex (transition state) that decomposes to products. $k = (k_BT/h)e^{-\Delta G^\ddagger/(RT)}$.', 'c_arrhenius_collision', 3, 'JEE Mains Prep', 'approved'),
('For two reactions with the same $A$ but $E_{a1} = 50\;\text{kJ}$ and $E_{a2} = 100\;\text{kJ}$, the ratio $k_1/k_2$ at $300\;\text{K}$ is', '$\sim 10^{4}$', '$\sim 2$', '$\sim 10^{8.7}$', '$\sim 10^{17}$', 'option3', 'Same as the catalyst problem: $\ln(k_1/k_2) = (100000 - 50000)/(8.314 \times 300) = 20.05$. Ratio $\approx 10^{8.7}$.', 'c_arrhenius_collision', 3, 'JEE Mains Prep', 'approved'),
('The Maxwell-Boltzmann distribution curve at higher temperature shows', 'Fewer molecules at all energies', 'A sharper, narrower curve', 'No change', 'A flatter, broader curve with more molecules at higher energies', 'option4', 'Higher $T$: the peak shifts right and flattens. More molecules exceed $E_a$, increasing the rate.', 'c_arrhenius_collision', 3, 'JEE Mains Prep', 'approved'),
('The energy profile diagram for a catalyzed reaction shows', 'A lower activation energy peak but the same $\Delta H$ as the uncatalyzed reaction', 'A different $\Delta H$', 'No activation energy', 'A higher peak', 'option1', 'Catalyst lowers $E_a$ but does not change $\Delta H$ (thermodynamics unchanged, only kinetics affected).', 'c_arrhenius_collision', 3, 'JEE Mains Prep', 'approved'),
('For an exothermic reaction, the activation energy for the reverse reaction ($E_{a,rev}$) is related to the forward ($E_{a,fwd}$) by', '$E_{a,rev} = E_{a,fwd} - |\Delta H|$', '$E_{a,rev} = E_{a,fwd} + |\Delta H|$', '$E_{a,rev} = E_{a,fwd}$', '$E_{a,rev} = |\Delta H|$', 'option2', '$E_{a,rev} = E_{a,fwd} + |\Delta H|$ (the reverse must climb the full barrier plus recover the energy released).', 'c_arrhenius_collision', 3, 'JEE Mains Prep', 'approved');
